import React, { useState } from "react";
import Link from "next/link";
import { CheckCircle2, Check, User, FileText, Heart, Lightbulb, Archive, ExternalLink } from "lucide-react";
import type { AboutData } from "@/types/about";
import type { ExperienceData } from "@/types/experience";
import type { HardSkillsData } from "@/types/hardSkill";
import type { Project } from "@/types/projects";
import { getProxiedUrl } from "@/lib/utils";

interface AboutContentProps {
    aboutData?: AboutData | null;
    experienceData?: ExperienceData | null;
    hardSkillsData?: HardSkillsData | null;
    projects?: Project[];
}

interface MenuButtonProps {
    id: 'about' | 'cv' | 'philosophy' | 'interests' | 'archive';
    label: string;
    count?: string;
    icon: any;
    activeTab: string;
    setActiveTab: (id: any) => void;
}

const MenuButton = ({ id, label, count, icon: Icon, activeTab, setActiveTab }: MenuButtonProps) => (
    <button
        onClick={() => setActiveTab(id)}
        className={`w-full flex items-center justify-between py-2 rounded-md text-sm transition-colors whitespace-nowrap overflow-hidden ${activeTab === id
            ? "bg-black/10 text-black font-semibold"
            : "text-gray-600 hover:bg-black/5"
            }`}
        title={label}
    >
        <div className="flex items-center gap-0 shrink-0">
            <div className="w-[48px] flex justify-center shrink-0">
                <Icon size={16} />
            </div>
            <span className="opacity-0 md:opacity-100 transition-opacity duration-300 ml-1">{label}</span>
        </div>
        {count && <span className="text-gray-400 text-xs opacity-0 md:opacity-100 transition-opacity duration-300 ml-2 mr-3">{count}</span>}
    </button>
);

export default function AboutContent({ aboutData, experienceData, hardSkillsData, projects = [] }: AboutContentProps) {
    const [activeTab, setActiveTab] = useState<'about' | 'cv' | 'philosophy' | 'interests' | 'archive'>('about');

    const archiveProjects = projects.filter(p => p.type === 'visual_art');

    return (
        <div className="flex h-full w-full bg-[#ECECEC] font-sans">
            <style jsx>{`
                .about-scrollbar::-webkit-scrollbar {
                    width: 8px;
                }
                .about-scrollbar::-webkit-scrollbar-track {
                    background: transparent;
                }
                .about-scrollbar::-webkit-scrollbar-thumb {
                    background-color: rgba(0,0,0,0.1);
                    border-radius: 4px;
                    border: 2px solid transparent;
                    background-clip: content-box;
                }
                .about-scrollbar::-webkit-scrollbar-thumb:hover {
                    background-color: rgba(0,0,0,0.2);
                }
            `}</style>

            {/* Sidebar (Left) */}
            <div className="w-[72px] md:w-[200px] shrink-0 bg-[#E3E3E3]/50 border-r border-[#D1D1D1] p-3 flex flex-col gap-1 pt-4 transition-[width] duration-300 ease-in-out overflow-hidden z-20 relative">
                <div className="text-[10px] uppercase tracking-wider text-gray-500 font-bold px-3 mb-1 opacity-0 md:opacity-100 transition-opacity duration-300 whitespace-nowrap">
                    Personal
                </div>
                <MenuButton id="about" label="About me" count="18" icon={User} activeTab={activeTab} setActiveTab={setActiveTab} />
                <MenuButton id="cv" label="CV" count={experienceData?.workExperience.length ? String(experienceData.workExperience.length) : "0"} icon={FileText} activeTab={activeTab} setActiveTab={setActiveTab} />
                <MenuButton id="philosophy" label="Philosophy" count="3" icon={Lightbulb} activeTab={activeTab} setActiveTab={setActiveTab} />
                <MenuButton id="interests" label="Interests" count={(aboutData?.softSkills?.items?.length || aboutData?.softSkills?.texts?.length) ? "∞" : "0"} icon={Heart} activeTab={activeTab} setActiveTab={setActiveTab} />

                <div className="h-px bg-gray-300 my-2 mx-1 opacity-0 md:opacity-50 transition-opacity duration-300"></div>

                <div className="text-[10px] uppercase tracking-wider text-gray-500 font-bold px-3 mb-1 opacity-0 md:opacity-100 transition-opacity duration-300 whitespace-nowrap">
                    Works
                </div>
                <MenuButton id="archive" label="Archive" count={String(archiveProjects.length)} icon={Archive} activeTab={activeTab} setActiveTab={setActiveTab} />

                <div className="mt-auto pt-4 overflow-hidden">
                    <Link
                        href="/cv?mode=ats&print=true"
                        target="_blank"
                        className="w-full flex items-center gap-0 py-2 rounded-md text-sm transition-colors text-gray-600 hover:bg-red-600 hover:text-white active:bg-red-700 active:text-white whitespace-nowrap"
                        title="Download CV"
                    >
                        {/* Fixed width container matching MenuButton for alignment */}
                        <div className="w-[48px] flex justify-center shrink-0">
                            <FileText size={16} />
                        </div>
                        <span className="opacity-0 md:opacity-100 transition-opacity duration-300 ml-1">Download CV</span>
                    </Link>
                </div>
            </div>

            {/* Content Area (Right) */}
            <div
                data-lenis-prevent
                className="flex-1 bg-white h-full overflow-y-auto overscroll-contain p-8 pb-20 about-scrollbar min-h-0"
                style={{ touchAction: "pan-y" }}
            >
                {activeTab === 'about' && (
                    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <div>
                            <h1 className="text-2xl font-bold text-black mb-2">
                                {aboutData?.hero.title || "Fullstack Developer"}
                            </h1>



                            <p className="text-gray-600 leading-relaxed text-sm whitespace-pre-wrap">
                                {aboutData?.professional.bio.content || "Loading..."}
                            </p>
                        </div>

                        <div>
                            <h2 className="text-sm font-bold text-black mb-4">I can do...</h2>
                            <div className="space-y-6">
                                {hardSkillsData?.skills?.filter(s => s.isActive !== false).map((skill, idx) => (
                                    <div key={idx} className="flex flex-col gap-2">
                                        {/* Skill Name */}
                                        <div className="flex items-center gap-2">

                                            {skill.iconUrl && (
                                                <img
                                                    src={getProxiedUrl(skill.iconUrl)}
                                                    alt={skill.name}
                                                    className="w-5 h-5 object-contain"
                                                />
                                            )}
                                            <h3 className="font-bold text-gray-900 text-sm">{skill.name}</h3>
                                        </div>

                                        {/* Description Points */}
                                        <div className="pl-7 space-y-1">
                                            {skill.details && skill.details.length > 0 ? (
                                                skill.details.map((detail, i) => (
                                                    <div key={i} className="flex items-start gap-2">
                                                        <div className="flex items-center justify-center w-4 h-4 rounded-full border border-[#42b549] bg-[#42b549]/10 mt-0.5 shrink-0">
                                                            <Check size={8} className="text-[#42b549]" strokeWidth={3} />
                                                        </div>
                                                        <span className="text-sm text-gray-600 leading-tight">
                                                            {detail}
                                                        </span>
                                                    </div>
                                                ))
                                            ) : (
                                                <div className="text-xs text-gray-400 italic">No details available</div>
                                            )}
                                        </div>
                                    </div>
                                )) || (
                                        <div className="text-gray-400 text-xs italic">No skills data loaded.</div>
                                    )}
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'cv' && (
                    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <h1 className="text-2xl font-bold text-black">Curriculum Vitae</h1>
                        <div className="border-l-2 border-gray-200 pl-4 space-y-6">
                            {experienceData?.workExperience.map((job, idx) => (
                                <div key={idx}>
                                    <h3 className="font-bold text-black">{job.position}</h3>
                                    <div className="flex justify-between items-center pr-4">
                                        <span className="text-orange-600 text-xs font-semibold">{job.company}</span>
                                        <span className="text-gray-400 text-xs">{job.duration} • {job.year}</span>
                                    </div>
                                    <div className="text-sm text-gray-600 mt-2">
                                        <ul className="list-disc ml-4 space-y-1">
                                            {job.description.map((desc, dIdx) => (
                                                <li key={dIdx}>{desc}</li>
                                            ))}
                                        </ul>
                                    </div>
                                </div>
                            )) || <p className="text-gray-500 italic">No experience data found.</p>}
                        </div>
                    </div>
                )}

                {activeTab === 'philosophy' && (
                    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <div>
                            <h1 className="text-2xl font-bold text-black mb-2">
                                {aboutData?.designPhilosophy?.heading || "Design Philosophy"}
                            </h1>
                            <p className="text-gray-600 font-medium">
                                {aboutData?.designPhilosophy?.subheading || "Creating meaningful experiences through thoughtful design"}
                            </p>
                        </div>

                        <div className="grid grid-cols-1 gap-4">
                            {aboutData?.designPhilosophy?.steps.map((step, idx) => (
                                <div key={idx} className="bg-gray-50 border border-gray-200 rounded-lg p-4 hover:border-orange-300 transition-colors">
                                    <div className="flex items-start justify-between mb-2">
                                        <span className="text-orange-500 font-bold font-mono text-lg">{step.number}</span>
                                        <h3 className="font-bold text-gray-900">{step.title}</h3>
                                    </div>
                                    <p className="text-sm text-gray-700 mb-3 leading-relaxed">
                                        {step.desc}
                                    </p>
                                    <div className="text-xs text-gray-500 italic border-l-2 border-orange-200 pl-2">
                                        &quot;{step.quote}&quot;
                                    </div>
                                </div>
                            )) || (
                                    // Fallback if no data
                                    <>
                                        {/* Fallback code same as before */}
                                    </>
                                )}
                        </div>
                    </div>
                )}

                {activeTab === 'interests' && (
                    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <h1 className="text-2xl font-bold text-black mb-6">Interests & Soft Skills</h1>

                        {/* Logic to prepare interests data */}
                        {(() => {
                            // Normalize data
                            const rawItems = aboutData?.softSkills?.items ||
                                (aboutData?.softSkills?.texts?.map((text, i) => ({
                                    text,
                                    description: aboutData?.softSkills?.descriptions?.[i] || '',
                                    isDraft: false
                                })) || []);

                            // Filter out drafts
                            const interests = rawItems.filter(item => !item.isDraft);

                            if (interests.length === 0) {
                                return (
                                    <div className="text-gray-400 text-sm italic">
                                        No interests to display.
                                    </div>
                                );
                            }

                            return (
                                <div className="space-y-8">
                                    {interests.map((item, idx) => (
                                        <div key={idx} className="group">
                                            <h3 className="font-bold text-black text-lg mb-2 flex items-center gap-2">
                                                {item.text}
                                            </h3>
                                            <p className="text-gray-600 leading-relaxed text-sm whitespace-pre-wrap">
                                                {item.description}
                                            </p>
                                        </div>
                                    ))}
                                </div>
                            );
                        })()}
                    </div>
                )}

                {activeTab === 'archive' && (
                    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <div>
                            <h1 className="text-2xl font-bold text-black mb-2">Archive</h1>
                            <p className="text-gray-600 text-sm">
                                Experimental works, visual art, and personal explorations.
                                These projects showcase style range outside of commercial constraints.
                            </p>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            {archiveProjects.map((project) => (
                                <div key={project.id} className="group relative aspect-[4/5] bg-gray-100 rounded-lg overflow-hidden border border-gray-200">
                                    {project.type === 'visual_art' && (
                                        <div className="absolute top-2 right-2 z-10 bg-black/50 text-white text-[10px] px-2 py-0.5 rounded-full backdrop-blur-sm">
                                            Art
                                        </div>
                                    )}
                                    {/* Handle Image/Video */}
                                    {project.cover.endsWith('.mp4') ? (
                                        <video
                                            src={getProxiedUrl(project.cover)}
                                            className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity"
                                            autoPlay
                                            muted
                                            loop
                                            playsInline
                                            preload="none"
                                        />
                                    ) : (
                                        <img
                                            src={getProxiedUrl(project.cover)}
                                            alt={project.title}
                                            loading="lazy"
                                            className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity"
                                        />
                                    )}
                                    <div className="absolute bottom-0 left-0 w-full p-3 bg-gradient-to-t from-black/80 to-transparent pt-8">
                                        <h3 className="text-white text-sm font-bold truncate">{project.title}</h3>
                                        <p className="text-white/70 text-xs truncate">{project.tags.join(', ')}</p>
                                    </div>
                                </div>
                            ))}
                            {archiveProjects.length === 0 && (
                                <p className="text-gray-400 italic col-span-2 text-center py-8">No archived projects found.</p>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Send, MoreVertical, Search, CheckCheck, Paperclip, Smile, Mic, ArrowLeft, BadgeCheck, FileText, ExternalLink } from 'lucide-react';
import { m, AnimatePresence } from 'framer-motion';
import Image from 'next/image';
import { mockChats, ContactProfile, ChatMessage } from './data/mockChats';
import { soundManager } from "./utils/SoundManager";
import { getAvatarUrl } from '@/lib/avatar';
import { Project } from '@/types/projects';

// Letter Avatar Helper (Clean & Consistent)
const USER_AVATAR = `https://ui-avatars.com/api/?background=00a884&color=ffffff&name=R&size=128&bold=true&length=1`; // User (Ramos) - Green background
const CLIENT_AVATAR = `https://ui-avatars.com/api/?background=d9fdd3&color=128c7e&name=C&size=128&bold=true&length=1`; // Default Client Fallback

interface ChatWindowProps {
    settings?: any;
    activeChatId?: string | null;
    customContacts?: Record<string, ContactProfile>;
}

export default function ChatWindow({ settings, activeChatId, customContacts }: ChatWindowProps) {
    const [chats, setChats] = useState<Record<string, ContactProfile>>({});
    const [input, setInput] = useState('');
    const bottomRef = useRef<HTMLDivElement>(null);
    const [activeContact, setActiveContact] = useState<ContactProfile | null>(null);
    const [visibleMessages, setVisibleMessages] = useState<ChatMessage[]>([]);
    const [isRemoteTyping, setIsRemoteTyping] = useState(false);
    const [projects, setProjects] = useState<Record<string, Project>>({});
    const sequencerRef = useRef<NodeJS.Timeout | null>(null);

    // Sound notification via centralized SoundManager
    const playNotificationSound = () => {
        soundManager.play('notification', 0.6);
    };

    // Load projects for thumbnails
    useEffect(() => {
        const loadProjects = async () => {
            try {
                const response = await fetch('/api/projects');
                const data = await response.json();
                const projectMap: Record<string, Project> = {};
                (data.projects || []).forEach((p: Project) => {
                    projectMap[p.id] = p;
                });
                setProjects(projectMap);
            } catch (err) {
                console.error('Error loading projects for chat:', err);
            }
        };
        loadProjects();
    }, []);

    // Sequencer Logic: Autoplay conversation
    useEffect(() => {
        const initialChats = customContacts || mockChats;
        setChats(initialChats);

        const contactId = activeChatId || Object.keys(initialChats)[0];
        const contact = contactId ? initialChats[contactId] : (Object.values(initialChats)[0] || null);

        if (contact) {
            setActiveContact(contact);
            // Reset visibility
            setVisibleMessages([]);
            setIsRemoteTyping(false);
            if (sequencerRef.current) clearTimeout(sequencerRef.current);

            let currentIndex = 0;
            const fullConversation = contact.conversation;

            const nextStep = () => {
                if (currentIndex >= fullConversation.length) return;

                const msg = fullConversation[currentIndex];

                // If the next message is from Client (Remote), show typing first
                if (!msg.isMe) {
                    setIsRemoteTyping(true);
                    sequencerRef.current = setTimeout(() => {
                        setIsRemoteTyping(false);
                        setVisibleMessages(prev => [...prev, msg]);
                        playNotificationSound();
                        currentIndex++;
                        // Wait 1.5s after a message before showing the next one
                        sequencerRef.current = setTimeout(nextStep, 1500);
                    }, 2000); // Typing duration
                } else {
                    // Internal messages appear faster
                    setVisibleMessages(prev => [...prev, msg]);
                    currentIndex++;
                    sequencerRef.current = setTimeout(nextStep, 1000);
                }
            };

            // Start after a small initial delay
            sequencerRef.current = setTimeout(nextStep, 800);
        }

        return () => {
            if (sequencerRef.current) clearTimeout(sequencerRef.current);
        };
    }, [activeChatId, customContacts]);

    // Scroll to bottom on visible messages change
    useEffect(() => {
        bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [visibleMessages, isRemoteTyping]);

    const handleSend = (e: React.FormEvent) => {
        e.preventDefault();
        if (!input.trim() || !activeContact) return;

        const newMessage: ChatMessage = {
            id: Date.now(),
            text: input,
            isMe: true,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            status: 'sent' as const,
            type: 'text'
        };

        setVisibleMessages(prev => [...prev, newMessage]);
        setInput('');
        soundManager.play('click', 0.4); // Subtle feedback for sending a message
    };

    if (!activeContact) return <div className="h-full bg-[#efeae2]"></div>;

    return (
        <div key="chat-window-inner" className="flex flex-col h-full w-full bg-[#efeae2] relative overflow-hidden text-[#111b21]">
            {/* Chat Background Pattern */}
            <div
                key="chat-bg-pattern-os-v2"
                className="absolute inset-0 opacity-100 pointer-events-none z-0"
                style={{
                    backgroundImage: 'url("/assets/whatsapp-bg.png")',
                    backgroundRepeat: 'repeat',
                    backgroundSize: '400px'
                }}
            ></div>

            {/* Header */}
            <div className="bg-[#f0f2f5] py-2 px-4 flex items-center justify-between shrink-0 h-[60px] border-b border-[#d1d7db] z-10">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full overflow-hidden cursor-pointer relative shrink-0">
                        <Image
                            src={activeContact.avatar && activeContact.avatar.startsWith('http') ? activeContact.avatar : getAvatarUrl(activeContact.name)}
                            alt={activeContact.name}
                            width={40}
                            height={40}
                            unoptimized
                            className="w-full h-full object-cover"
                        />
                    </div>
                    <div className="flex flex-col justify-center min-w-0">
                        <h3 className="text-[16px] text-[#111b21] font-semibold leading-none truncate">{activeContact.name}</h3>
                        {isRemoteTyping ? (
                            <span className="text-[11px] text-[#00a884] font-medium mt-0.5 animate-pulse">sedang mengetik...</span>
                        ) : (
                            <span className="text-[11px] text-[#00a884] font-medium flex items-center gap-1 mt-0.5">
                                <BadgeCheck size={14} fill="#00a884" className="text-white" /> Verified Client Testimonial
                            </span>
                        )}
                    </div>
                </div>
                <div className="flex items-center gap-5 text-[#54656f]">
                    <Search size={20} className="cursor-pointer" />
                    <MoreVertical size={20} className="cursor-pointer" />
                </div>
            </div>

            {/* Messages Area */}
            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-y-5 z-10 custom-scrollbar relative">
                <AnimatePresence mode="popLayout">
                    {visibleMessages.map((msg) => (
                        <m.div
                            initial={{ opacity: 0, y: 10, scale: 0.95 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            key={msg.id}
                            className={`flex ${msg.isMe ? 'justify-end' : 'justify-start'}`}
                        >
                            <div className={`relative max-w-[85%] rounded-lg px-2 pt-1.5 pb-1 shadow-sm text-[14.2px] 
                                ${msg.isMe ? 'bg-[#d9fdd3] rounded-tr-none' : 'bg-white rounded-tl-none'}`}
                            >
                                <div className="flex flex-col">
                                    {/* Project Thumbnail Bubble */}
                                    {msg.type === 'project' && msg.projectId && projects[msg.projectId] && (
                                        <div className="mb-2 rounded-md overflow-hidden bg-black/5 border border-black/5 group cursor-pointer relative">
                                            <Image
                                                src={projects[msg.projectId].cover}
                                                alt={projects[msg.projectId].title}
                                                width={300}
                                                height={200}
                                                className="w-full h-auto object-cover max-h-[180px]"
                                            />
                                            <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/60 to-transparent p-2">
                                                <p className="text-white text-[11px] font-bold truncate">{projects[msg.projectId].title}</p>
                                            </div>
                                        </div>
                                    )}

                                    {/* Image Bubble */}
                                    {msg.type === 'image' && msg.imageSrc && (
                                        <div className="mb-2 rounded-md overflow-hidden bg-black/5 border border-black/5">
                                            <img
                                                src={msg.imageSrc}
                                                alt="Shared media"
                                                className="w-full h-auto object-cover max-h-[250px]"
                                            />
                                        </div>
                                    )}

                                    <p className="text-[#111b21] leading-[19px] break-words whitespace-pre-wrap pr-1">
                                        {msg.text}
                                    </p>
                                    <div className="flex justify-end items-center gap-1 select-none mt-1 h-3">
                                        <span className="text-[11px] text-[#667781] leading-none">{msg.time}</span>
                                        {msg.isMe && (
                                            <m.span
                                                initial={{ color: "#667781" }}
                                                animate={{ color: "#53bdeb" }}
                                                transition={{ delay: 1 }}
                                                className="text-[#53bdeb]"
                                            >
                                                <CheckCheck size={16} strokeWidth={1.5} />
                                            </m.span>
                                        )}
                                    </div>
                                </div>
                                {/* Triangle tip */}
                                <div className={`absolute top-0 w-0 h-0 border-[6px] border-transparent 
                                    ${msg.isMe
                                        ? 'right-[-6px] border-t-[#d9fdd3] border-l-[#d9fdd3]'
                                        : 'left-[-6px] border-t-white border-r-white'
                                    }`}
                                />
                            </div>
                        </m.div>
                    ))}
                    {isRemoteTyping && (
                        <m.div
                            initial={{ opacity: 0, y: 5 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0 }}
                            className="flex justify-start"
                        >
                            <div className="bg-white rounded-lg rounded-tl-none px-3 py-2 shadow-sm flex gap-1 items-center">
                                <span className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce"></span>
                                <span className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                                <span className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                            </div>
                        </m.div>
                    )}
                </AnimatePresence>
                <div ref={bottomRef} />
            </div>

            {/* Footer / Input Area */}
            <div className="bg-[#f0f2f5] px-4 py-2 flex items-center gap-2 shrink-0 z-10 min-h-[62px]">
                <div className="flex gap-4 text-[#54656f]">
                    <Smile size={26} className="cursor-pointer hover:text-[#41525d]" />
                    <Paperclip size={24} className="cursor-pointer hover:text-[#41525d]" />
                </div>
                <form onSubmit={handleSend} className="flex-1 mx-2">
                    <input
                        type="text"
                        value={input}
                        onChange={e => setInput(e.target.value)}
                        placeholder="Ketik pesan"
                        className="w-full bg-white rounded-lg px-4 py-[9px] text-[15px] text-[#111b21] placeholder:text-[#667781] focus:outline-none border border-transparent focus:border-white"
                    />
                </form>
                <div className="flex gap-3 text-[#54656f]">
                    {input.trim() ? (
                        <button onClick={handleSend} className="text-[#54656f] hover:text-[#41525d]">
                            <Send size={24} />
                        </button>
                    ) : (
                        <Mic size={24} className="cursor-pointer hover:text-[#41525d]" />
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Lock, Loader2 } from 'lucide-react';

interface PasswordModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}

export default function PasswordModal({ isOpen, onClose, onSuccess }: PasswordModalProps) {
    const [pin, setPin] = useState(['', '', '', '']);
    const [isVerifying, setIsVerifying] = useState(false);
    const [error, setError] = useState(false);
    const inputRefs = [useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null)];

    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
    }, []);

    useEffect(() => {
        if (isOpen) {
            setPin(['', '', '', '']);
            setError(false);
            const timer = setTimeout(() => inputRefs[0].current?.focus(), 100);
            return () => clearTimeout(timer);
        }
    }, [isOpen]);

    const handlePinChange = async (index: number, value: string) => {
        if (!/^\d*$/.test(value)) return;

        const newPin = [...pin];
        newPin[index] = value.slice(-1);
        setPin(newPin);

        if (value && index < 3) {
            inputRefs[index + 1].current?.focus();
        }

        if (newPin.every(digit => digit !== '')) {
            const finalPin = newPin.join('');
            verifyPin(finalPin);
        }
    };

    const handleKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Backspace' && !pin[index] && index > 0) {
            inputRefs[index - 1].current?.focus();
        }
    };

    const verifyPin = async (finalPin: string) => {
        setIsVerifying(true);
        setError(false);

        try {
            const response = await fetch('/api/os/verify-password', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ password: finalPin }),
            });

            const data = await response.json();

            if (data.success) {
                onSuccess();
                setPin(['', '', '', '']);
            } else {
                setError(true);
                setPin(['', '', '', '']);
                inputRefs[0].current?.focus();
            }
        } catch (err) {
            console.error('Verification failed', err);
            setError(true);
        } finally {
            setIsVerifying(false);
        }
    };

    if (!mounted) return null;

    return createPortal(
        <AnimatePresence>
            {isOpen && (
                <div className="fixed inset-0 z-[1000000] flex items-center justify-center p-4">
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="absolute inset-0 bg-black/40 backdrop-blur-md"
                    />

                    <motion.div
                        initial={{ scale: 0.9, opacity: 0, y: 20 }}
                        animate={{
                            scale: 1,
                            opacity: 1,
                            y: 0,
                            x: error ? [0, -10, 10, -10, 10, 0] : 0
                        }}
                        exit={{ scale: 0.9, opacity: 0, y: 20 }}
                        transition={{
                            x: error ? { duration: 0.4, ease: "easeInOut" } : { type: "spring", damping: 20, stiffness: 300 }
                        }}
                        className="relative w-[320px] bg-white/10 backdrop-blur-2xl border border-white/20 rounded-[32px] p-8 shadow-2xl flex flex-col items-center gap-6 overflow-hidden mt-[-10vh]"
                    >
                        <div className="absolute top-0 left-0 right-0 h-1/2 bg-gradient-to-b from-white/10 to-transparent pointer-events-none" />

                        <div className="space-y-4 text-center relative z-10 w-full">
                            <div className="w-12 h-12 rounded-2xl bg-white/10 border border-white/20 flex items-center justify-center mx-auto">
                                <Lock size={20} className={error ? "text-red-400" : "text-white/80"} />
                            </div>
                            <div className="space-y-1">
                                <h2 className="text-xl font-semibold text-white">Enter PIN</h2>
                                <p className="text-sm text-white/50">To unlock editing mode</p>
                            </div>
                        </div>

                        <div className="flex gap-2 relative z-10">
                            {pin.map((digit, i) => (
                                <input
                                    key={i}
                                    ref={inputRefs[i]}
                                    type="text"
                                    inputMode="numeric"
                                    pattern="\d*"
                                    maxLength={1}
                                    value={digit}
                                    onChange={(e) => handlePinChange(i, e.target.value)}
                                    onKeyDown={(e) => handleKeyDown(i, e)}
                                    disabled={isVerifying}
                                    className={`w-12 h-14 bg-white/5 border ${error ? 'border-red-500/50' : 'border-white/20'} rounded-2xl text-center text-2xl font-bold text-white focus:outline-none focus:border-white/50 transition-all`}
                                />
                            ))}
                        </div>

                        <div className="relative z-10 w-full mt-2">
                            {isVerifying ? (
                                <div className="flex items-center justify-center gap-2 text-white/50 text-xs font-medium uppercase tracking-tighter">
                                    <Loader2 size={16} className="animate-spin" />
                                    Verifying...
                                </div>
                            ) : error ? (
                                <div className="text-center">
                                    <span className="text-red-400 text-xs font-semibold uppercase tracking-wider">Incorrect PIN</span>
                                </div>
                            ) : (
                                <div className="text-center">
                                    <button
                                        onClick={onClose}
                                        className="text-white/30 hover:text-white/60 text-xs font-medium transition-colors"
                                    >
                                        Cancel
                                    </button>
                                </div>
                            )}
                        </div>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>,
        document.body
    );
}

"use client";

import React, { useRef, useEffect } from "react";
import { m, useDragControls, AnimatePresence } from "framer-motion";
import { X, Minus, Square, Pin, Lock } from "lucide-react";
import { soundManager } from "./utils/SoundManager";

interface WindowProps {
    id: string;
    title: string;
    children: React.ReactNode;
    isOpen: boolean;
    isMinimized?: boolean;
    isMaximized?: boolean;
    onClose: () => void;
    onMinimize?: () => void;
    onMaximize?: () => void;
    onFocus?: () => void;
    zIndex?: number;
    initialPosition?: { x: number; y: number }; // Default position
    minimizeTarget?: { x: number; y: number }; // Target for minimize animation
    noPadding?: boolean;
    onUpdatePosition?: (x: number, y: number) => void;
    width?: number;
    height?: number;
    onResize?: (width: number, height: number) => void;
    onResizeEnd?: (width: number, height: number) => void;
    isPinned?: boolean;
    onTogglePin?: () => void;
    isAdmin?: boolean;
    animationVariant?: 'genie' | 'scale' | 'tv' | 'snap';
}

export default function OSWindow({
    id,
    title,
    children,
    isOpen,
    isMinimized = false,
    isMaximized = false,
    onClose,
    onMinimize,
    onMaximize,
    onFocus,
    zIndex = 10,
    initialPosition = { x: 100, y: 100 },
    minimizeTarget,
    noPadding = false,
    onUpdatePosition,
    width,
    height,
    onResize,
    onResizeEnd,
    isPinned = false,
    onTogglePin,
    isAdmin = false,
    animationVariant = 'genie',
}: WindowProps) {
    const isMobileWindow = typeof window !== 'undefined' && window.innerWidth < 768;
    const isTabletWindow = typeof window !== 'undefined' && window.innerWidth >= 768 && window.innerWidth < 1024;
    const isSmallScreen = isMobileWindow || isTabletWindow;
    const winWidth = isMobileWindow ? window.innerWidth : isTabletWindow ? Math.min(window.innerWidth - 32, 700) : 600;
    const dragControls = useDragControls();

    // Internal state for resizing
    const [isResizing, setIsResizing] = React.useState(false);
    const [dynamicSize, setDynamicSize] = React.useState({ width, height });

    // Sync props to state (when not resizing)
    useEffect(() => {
        if (!isResizing) {
            setDynamicSize({ width, height });
        }
    }, [width, height, isResizing]);

    // Sound effect on open - delay until user interaction
    useEffect(() => {
        if (isOpen) {
            // Use setTimeout to ensure user interaction is detected first
            const timer = setTimeout(() => {
                soundManager.play('window-open', 0.4);
            }, 100);
            return () => clearTimeout(timer);
        }
    }, [isOpen]);

    // "Premium Solid" Mode (Snappy, No Bounce, Direct)
    const getMinimizeState = () => {
        return {
            scale: 0.9,
            opacity: 0,
            x: initialPosition.x, // Force snap to origin X
            y: initialPosition.y, // Force snap to origin Y
            transition: { duration: 0.15, ease: "easeIn" } // Fast exit
        };
    };

    // Resize Handlers
    const resizeStartRef = useRef<{ x: number, y: number, w: number, h: number, dir: 'e' | 's' | 'se' } | null>(null);

    // Refs for callbacks to avoid stale closures
    const onResizeRef = useRef(onResize);
    const onResizeEndRef = useRef(onResizeEnd);
    useEffect(() => { onResizeRef.current = onResize; }, [onResize]);
    useEffect(() => { onResizeEndRef.current = onResizeEnd; }, [onResizeEnd]);

    // Separate ref for final size (to avoid mutating start values)
    const finalSizeRef = useRef({ w: 0, h: 0 });

    const handleResizeStart = (e: React.MouseEvent | React.TouchEvent, direction: 'e' | 's' | 'se') => {
        e.preventDefault();
        e.stopPropagation();
        setIsResizing(true);
        const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
        const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
        resizeStartRef.current = {
            x: clientX,
            y: clientY,
            w: dynamicSize.width || 0,
            h: dynamicSize.height || 0,
            dir: direction
        };
    };

    useEffect(() => {
        if (!isResizing) return;

        const handleMouseMove = (moveEvent: MouseEvent | TouchEvent) => {
            if (!resizeStartRef.current) return;

            const clientX = 'touches' in moveEvent ? moveEvent.touches[0].clientX : moveEvent.clientX;
            const clientY = 'touches' in moveEvent ? moveEvent.touches[0].clientY : moveEvent.clientY;

            const { x: startX, y: startY, w: startWidth, h: startHeight, dir: direction } = resizeStartRef.current;
            const deltaX = clientX - startX;
            const deltaY = clientY - startY;

            let newWidth = startWidth;
            let newHeight = startHeight;

            if (direction === 'e' || direction === 'se') {
                newWidth = Math.max(300, startWidth + deltaX);
            }
            if (direction === 's' || direction === 'se') {
                newHeight = Math.max(200, startHeight + deltaY);
            }

            // Update LOCAL state only (super fast, no parent re-render)
            setDynamicSize({ width: newWidth, height: newHeight });

            // Store final size in separate ref (DO NOT mutate resizeStartRef.w/.h!)
            finalSizeRef.current = { w: newWidth, h: newHeight };
        };

        const handleMouseUp = () => {
            if (isResizing) {
                const finalW = finalSizeRef.current.w;
                const finalH = finalSizeRef.current.h;

                // Sync to parent ONCE at the end via refs
                if (onResizeRef.current) onResizeRef.current(finalW, finalH);
                if (onResizeEndRef.current) onResizeEndRef.current(finalW, finalH);
            }
            setIsResizing(false);
            resizeStartRef.current = null;
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        window.addEventListener('touchmove', handleMouseMove, { passive: false });
        window.addEventListener('touchend', handleMouseUp);

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            window.removeEventListener('touchmove', handleMouseMove);
            window.removeEventListener('touchend', handleMouseUp);
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isResizing]); // ONLY depend on isResizing, NOT dynamicSize


    return (
        <>
            {isOpen && (
                <m.div
                    drag={!isMaximized && !isResizing && !isPinned && !isSmallScreen}
                    dragControls={dragControls}
                    dragListener={false}
                    dragMomentum={false}
                    dragElastic={0}
                    onDragEnd={(e, info) => {
                        // We only want to update position if NOT maximizing/minimizing and NOT pinned
                        if (!isMaximized && !isMinimized && !isPinned && onUpdatePosition) {
                            // The final position is current (initial) + delta
                            // OR we can trust the visual position if we tracked it?
                            // Framer motion 'drag' modifies the transform, not the layout.
                            // To persist, we should add delta to initial.
                            const newX = initialPosition.x + info.offset.x;
                            const newY = initialPosition.y + info.offset.y;
                            onUpdatePosition(newX, newY);
                        }
                    }}
                    initial={{
                        scale: 0.95,
                        opacity: 0,
                        x: initialPosition.x,
                        y: initialPosition.y,
                    }}
                    animate={
                        isMinimized
                            ? getMinimizeState()
                            : isMaximized
                                ? {
                                    scale: 1,
                                    opacity: 1,
                                    x: 0,
                                    y: 0,
                                    width: "100%",
                                    height: "100%",
                                    borderRadius: 0,
                                    transition: { duration: 0.3, ease: [0.32, 0.72, 0, 1] }
                                }
                                : {
                                    scale: 1,
                                    opacity: 1,
                                    x: initialPosition.x,
                                    y: initialPosition.y,
                                    width: dynamicSize.width || width || winWidth, // USE DYNAMIC SIZE
                                    height: dynamicSize.height || height || "auto", // USE DYNAMIC SIZE
                                    borderRadius: 10,
                                    // Solid, Premium Spring (No wobble)
                                    transition: isResizing ? { duration: 0 } : { type: "spring", stiffness: 260, damping: 25 }
                                }
                    }
                    exit={{
                        scale: 0.95,
                        opacity: 0,
                        transition: { duration: 0.15 }
                    }}
                    onPointerDown={onFocus}
                    style={{
                        position: "absolute",
                        zIndex: zIndex,
                        top: 0,
                        left: 0,
                    }}
                    data-lenis-prevent
                    className={`flex flex-col shadow-lg overflow-hidden border border-white/40 will-change-transform pointer-events-auto ${isSmallScreen
                        ? 'bg-white/95'
                        : 'bg-white/80 backdrop-blur-xl'
                        }`}
                >
                    {/* Title Bar */}
                    <div
                        onPointerDown={(e) => {
                            if (!isMaximized && !isPinned) dragControls.start(e);
                        }}
                        onDoubleClick={onMaximize}
                        className="h-8 sm:h-7 bg-[#EFEFEF] border-b border-[#D1D1D1] flex items-center justify-between px-3 shrink-0 cursor-default select-none relative z-50"
                    >
                        {/* Traffic Lights */}
                        <div className="flex gap-[8px] mr-3 items-center group">
                            <button
                                onClick={(e) => {
                                    e.stopPropagation();
                                    soundManager.play('window-close', 0.4);
                                    onClose();
                                }}
                                onPointerDown={(e) => e.stopPropagation()}
                                className="w-6 h-6 min-w-[24px] min-h-[24px] p-0 rounded-full flex items-center justify-center group-hover:brightness-90 active:brightness-75 transition-all"
                                aria-label="Close window"
                            >
                                <span className="w-[12px] h-[12px] rounded-full bg-[#FF5F57] border-[0.5px] border-[#D6443F] shadow-sm flex items-center justify-center">
                                    <X size={8} className="text-black/60 opacity-0 group-hover:opacity-100 transition-opacity" strokeWidth={3} />
                                </span>
                            </button>
                            <button
                                onClick={(e) => { e.stopPropagation(); onMinimize && onMinimize(); }}
                                onPointerDown={(e) => e.stopPropagation()}
                                className="w-6 h-6 min-w-[24px] min-h-[24px] p-0 rounded-full flex items-center justify-center group-hover:brightness-90 active:brightness-75 transition-all"
                                aria-label="Minimize window"
                            >
                                <span className="w-[12px] h-[12px] rounded-full bg-[#FEBC2E] border-[0.5px] border-[#DDA335] shadow-sm flex items-center justify-center">
                                    <Minus size={8} className="text-black/60 opacity-0 group-hover:opacity-100 transition-opacity" strokeWidth={3} />
                                </span>
                            </button>
                            <button
                                onClick={(e) => { e.stopPropagation(); onMaximize && onMaximize(); }}
                                onPointerDown={(e) => e.stopPropagation()}
                                className="w-6 h-6 min-w-[24px] min-h-[24px] p-0 rounded-full flex items-center justify-center group-hover:brightness-90 active:brightness-75 transition-all"
                                aria-label="Maximize window"
                            >
                                <span className="w-[12px] h-[12px] rounded-full bg-[#28C840] border-[0.5px] border-[#22AA32] shadow-sm flex items-center justify-center">
                                    {/* Outline Square for Expand */}
                                    <span className="w-[6px] h-[6px] bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity rotate-45 transform scale-[0.8] block" style={{ clipPath: "polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)" }} />
                                </span>
                            </button>
                        </div>

                        {/* Title Indicator */}
                        <div className="absolute left-1/2 -translate-x-1/2 flex items-center justify-center gap-1.5 opacity-80 pointer-events-none w-[60%]">
                            <span className="text-xs font-semibold text-gray-700 tracking-wide drop-shadow-sm truncate block text-center w-full">{title}</span>
                        </div>

                        {/* Top Right Pin/Lock Button - Admin Only */}
                        {isAdmin && onTogglePin && (
                            <div className="flex items-center gap-2">
                                <button
                                    onClick={(e) => { e.stopPropagation(); onTogglePin(); }}
                                    onPointerDown={(e) => e.stopPropagation()}
                                    className={`p-1 rounded transition-colors ${isPinned ? 'text-orange-600' : 'text-gray-400'}`}
                                    title={isPinned ? "Unlock Position" : "Pin/Lock Position"}
                                >
                                    {isPinned ? <Lock size={12} /> : <Pin size={12} />}
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Window Content */}
                    <div
                        data-lenis-prevent
                        style={{ touchAction: "auto" }}
                        className={`relative flex-1 bg-white/50 w-full overflow-hidden ${noPadding ? '' : 'p-4'}`}
                    >
                        {children}

                        {/* Safe Zone for Resize Overlays (Only if not maximized and resizable) */}
                        {!isMaximized && !isSmallScreen && onResize && (
                            <>
                                {/* Right Handle */}
                                <div
                                    className="absolute top-0 right-0 w-2 h-full cursor-ew-resize z-[60] hover:bg-blue-500/20 active:bg-blue-500/40 transition-colors"
                                    onMouseDown={(e) => handleResizeStart(e, 'e')}
                                    onTouchStart={(e) => handleResizeStart(e, 'e')}
                                    onPointerDown={(e) => e.stopPropagation()}
                                />
                                {/* Bottom Handle */}
                                <div
                                    className="absolute bottom-0 left-0 w-full h-2 cursor-ns-resize z-[60] hover:bg-blue-500/20 active:bg-blue-500/40 transition-colors"
                                    onMouseDown={(e) => handleResizeStart(e, 's')}
                                    onTouchStart={(e) => handleResizeStart(e, 's')}
                                    onPointerDown={(e) => e.stopPropagation()}
                                />
                                {/* Corner Handle */}
                                <div
                                    className="absolute bottom-0 right-0 w-5 h-5 cursor-nwse-resize z-[70] hover:bg-blue-500/20 active:bg-blue-500/40 transition-colors rounded-tl"
                                    onMouseDown={(e) => handleResizeStart(e, 'se')}
                                    onTouchStart={(e) => handleResizeStart(e, 'se')}
                                    onPointerDown={(e) => e.stopPropagation()}
                                />
                            </>
                        )}
                    </div>
                </m.div>
            )}
        </>
    );
}

