);

export default function RetroMobileOverlay() {
    const [step, setStep] = useState<"boot" | "error" | "details">("boot");
    const [progress, setProgress] = useState(0);
    const [locale, setLocale] = useState<"id" | "en">(() => {
        // Safe check for locale during initialization if possible
        if (typeof Intl !== 'undefined') {
            try {
                const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
                const indonesianTz = ["Asia/Jakarta", "Asia/Pontianak", "Asia/Makassar", "Asia/Jayapura"];
                if (indonesianTz.includes(tz)) return "id";
            } catch (e) { }
        }
        return "en";
    });
    const [copied, setCopied] = useState(false);
    const [siteUrl, setSiteUrl] = useState(() => {
        if (typeof window !== 'undefined') return window.location.origin;
        return "";
    });

    // Sound effect on error
    useEffect(() => {
        if (step === "error") {
            soundManager.play('error', 0.5);
        }
    }, [step]);

    // Initial interaction listener for mobile as well
    useEffect(() => {
        const initAudio = () => {
            soundManager.init();
            window.removeEventListener('touchstart', initAudio);
            window.removeEventListener('mousedown', initAudio);
        };
        window.addEventListener('touchstart', initAudio);
        window.addEventListener('mousedown', initAudio);
        return () => {
            window.removeEventListener('touchstart', initAudio);
            window.removeEventListener('mousedown', initAudio);
        };
    }, []);


    // Locale is now initialized in useState to avoid cascading render

    const t = {
        id: {
            boot: "Memuat Macintosh OS...",
            title: "Akses Terbatas",
            errorTitle: "Smartphone tidak cocok untuk pengalaman ini.",
            errorMessage: "Portfolio ini merupakan simulasi Desktop OS utuh yang memerlukan layar lebar. Smartphone Anda tidak memiliki cukup 'Creative RAM' untuk merendernya.",
            errorCode: "Peringatan: HARAP GUNAKAN LAPTOP/PC",
            restartBtn: "Buka di Desktop",
            loadingTrans: "Menyiapkan tautan sinkronisasi...",
            qrInstruction: "Pindai disket ini untuk pindah ke Desktop.",
            backBtn: "Kembali ke Beranda",
            copyBtn: "Salin Link",
            copied: "Tersalin!",
            shareBtn: "Bagikan"
        },
        en: {
            boot: "Loading Macintosh OS...",
            title: "Access Restricted",
            errorTitle: "Smartphone is not suitable for this OS.",
            errorMessage: "This portfolio is a full Desktop OS simulation. Your smartphone lacks the 'Creative Canvas' required to render the full installation.",
            errorCode: "Notice: PLEASE SWITCH TO DESKTOP/PC",
            restartBtn: "Open in Desktop",
            loadingTrans: "Preparing sync interface...",
            qrInstruction: "Scan this disk to switch to Desktop.",
            backBtn: "Back to Home",
            copyBtn: "Copy Link",
            copied: "Copied!",
            shareBtn: "Share"
        }
    }[locale];

    const handleCopy = () => {
        navigator.clipboard.writeText(siteUrl);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handleShare = async () => {
        if (navigator.share) {
            try {
                await navigator.share({
                    title: 'Ramos Portfolio',
                    text: 'Buka portfolio Ramos di Desktop untuk pengalaman OS penuh!',
                    url: siteUrl,
                });
            } catch (err) {
                console.error('Share failed', err);
            }
        } else {
            handleCopy();
        }
    };

    useEffect(() => {
        if (step === "boot") {
            const timer = setTimeout(() => setStep("error"), 2000);
            return () => clearTimeout(timer);
        }
        if (step === "details") {
            const interval = setInterval(() => {
                setProgress(p => (p < 100 ? p + 2 : p));
            }, 50);
            return () => clearInterval(interval);
        }
    }, [step]);

    return (
        <div className="fixed inset-0 z-[10000] bg-[#c0c0c0] flex items-center justify-center p-6 retro-os-container touch-none select-none overflow-hidden text-[#000]">
            <AnimatePresence mode="wait">
                {step === "boot" && (
                    <m.div
                        key="boot"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="flex flex-col items-center gap-6"
                    >
                        <div className="w-20 h-24 bg-white/20 rounded animate-pulse flex items-center justify-center">
                            {/* Simplified Apple Retro Logo Placeholder */}
                            <div className="flex flex-col gap-1">
                                <div className="w-12 h-2 bg-[#5EBD3E]" />
                                <div className="w-12 h-2 bg-[#FFB900]" />
                                <div className="w-12 h-2 bg-[#F78200]" />
                                <div className="w-12 h-2 bg-[#E23838]" />
                                <div className="w-12 h-2 bg-[#973999]" />
                                <div className="w-12 h-2 bg-[#009CDF]" />
                            </div>
                        </div>
                        <p className="font-bold tracking-widest text-sm uppercase">{t.boot}</p>
                    </m.div>
                )}

                {(step === "error" || step === "details") && (
                    <m.div
                        key="error-box"
                        initial={{ scale: 0.8, opacity: 0 }}
                        animate={{ scale: 1, opacity: 1 }}
                        className="retro-window w-full max-w-[340px] shadow-2xl"
                    >
                        <div className="retro-title-bar">
                            <span className="retro-title-text">{t.title}</span>
                        </div>
                        <div className="retro-content flex flex-col items-center gap-4 text-center">
                            {step === "error" ? (
                                <>
                                    {/* Detail Error Message */}
                                    <div className="flex-1 flex flex-col items-center justify-center p-6 space-y-6">
                                        <div className="w-16 h-16 opacity-80">
                                            <SadMacIcon />
                                        </div>

                                        <div className="text-center space-y-3 max-w-[280px]">
                                            <p className="text-[14px] leading-tight text-black font-bold uppercase tracking-tight">
                                                {locale === 'en'
                                                    ? "The desktop experience is not compatible with this device."
                                                    : "Pengalaman desktop tidak kompatibel dengan perangkat ini."}
                                            </p>
                                            <p className="text-[11px] leading-normal text-gray-700">
                                                {locale === 'en'
                                                    ? "Please switch to a desktop computer for the full interactive OS experience."
                                                    : "Silakan gunakan komputer desktop untuk pengalaman OS interaktif sepenuhnya."}
                                            </p>
                                        </div>



                                    </div>
                                    <button
                                        onClick={() => setStep("details")}
                                        className="retro-button mt-2 font-bold"
                                    >
                                        {t.restartBtn}
                                    </button>
                                </>
                            ) : (
                                <div className="w-full space-y-4">
                                    <div className="retro-progress-container">
                                        <div className="retro-progress-bar" style={{ width: `${progress}%` }} />
                                    </div>
                                    <p className="text-[10px]">{t.loadingTrans}</p>

                                    {progress >= 100 && (
                                        <m.div
                                            initial={{ opacity: 0, y: 10 }}
                                            animate={{ opacity: 1, y: 0 }}
                                            className="bg-white p-4 border border-black flex flex-col items-center gap-2"
                                        >
                                            {/* Interactive Floppy Disk UI */}
                                            <div
                                                onClick={handleCopy}
                                                className="w-28 h-28 bg-[#9ca3af] border-2 border-black flex flex-col items-center justify-between p-1 relative cursor-pointer active:scale-95 transition-transform"
                                            >
                                                {/* Floppy Slider */}
                                                <div className="w-full bg-[#f3f4f6] h-10 border border-black p-1 flex items-center justify-center">
                                                    <QRCodeSVG value={siteUrl} size={32} level="L" />
                                                </div>
                                                {/* Label */}
                                                <div className="flex-1 w-full bg-white border border-black mt-1 p-1 flex items-center justify-center">
                                                    <span className="text-[8px] font-bold text-center uppercase tracking-tighter">PORTORAMOS<br />DISK 1</span>
                                                </div>
                                                {/* Write Protect Notch */}
                                                <div className="absolute top-0 right-0 w-4 h-4 bg-gray-600 border-l-2 border-b-2 border-black" />
                                            </div>

                                            <p className="text-[10px] font-bold mt-1 uppercase">{t.qrInstruction}</p>

                                            <div className="flex gap-2 w-full">
                                                <button
                                                    onClick={handleCopy}
                                                    className="retro-button flex-1 text-[10px] py-1"
                                                >
                                                    {copied ? t.copied : t.copyBtn}
                                                </button>
                                                <button
                                                    onClick={handleShare}
                                                    className="retro-button flex-1 text-[10px] py-1"
                                                >
                                                    {t.shareBtn}
                                                </button>
                                            </div>

                                            <a href="/" className="text-[10px] underline mt-1">{t.backBtn}</a>
                                        </m.div>
                                    )}
                                </div>
                            )}
                        </div>
                    </m.div>
                )}
            </AnimatePresence>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { Project } from '@/types/projects';
import { Grid, Check, Folder, MousePointer2 } from 'lucide-react';

interface DesktopPreferences {
    visibleProjectIds: string[];
    maxIcons: number;
    layout: 'grid' | 'scattered';
}

interface DesktopProjectsFormProps {
    data?: DesktopPreferences;
    projects: Project[];
    onUpdate: (data: DesktopPreferences) => void;
}

export default function DesktopProjectsForm({ data, projects, onUpdate }: DesktopProjectsFormProps) {
    const [preferences, setPreferences] = useState<DesktopPreferences>({
        visibleProjectIds: [],
        maxIcons: 5,
        layout: 'grid'
    });

    // Sync state with props in render
    const [lastData, setLastData] = useState(data);
    if (data && data !== lastData) {
        setPreferences({
            visibleProjectIds: data.visibleProjectIds || [],
            maxIcons: data.maxIcons || 5,
            layout: data.layout || 'grid'
        });
        setLastData(data);
    }

    const updatePrefs = (updates: Partial<DesktopPreferences>) => {
        const newData = { ...preferences, ...updates };
        setPreferences(newData);
        onUpdate(newData);
    };

    const toggleProject = (id: string) => {
        const current = preferences.visibleProjectIds;
        let newIds;
        if (current.includes(id)) {
            newIds = current.filter(pid => pid !== id);
        } else {
            if (current.length >= preferences.maxIcons) {
                // Shake effect or toast could go here
                return;
            }
            newIds = [...current, id];
        }
        updatePrefs({ visibleProjectIds: newIds });
    };

    return (
        <div className="space-y-6">
            <div className="flex items-start justify-between">
                <div>
                    <h3 className="text-lg font-medium text-gray-900 mb-2">Desktop Icons</h3>
                    <p className="text-sm text-gray-600">
                        Pilih project yang akan muncul di Desktop OS. Max {preferences.maxIcons} icons.
                    </p>
                </div>

                {/* Configuration Panel (Right Side) */}
                <div className="flex flex-col gap-3 items-end">
                    {/* Layout Toggle */}
                    <div className="bg-gray-100 p-1 rounded-lg flex items-center">
                        <button
                            onClick={() => updatePrefs({ layout: 'grid' })}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${preferences.layout === 'grid'
                                ? 'bg-white text-blue-600 shadow-sm'
                                : 'text-gray-500 hover:text-gray-700'
                                }`}
                        >
                            <Grid size={14} />
                            Auto Grid
                        </button>
                        <button
                            onClick={() => updatePrefs({ layout: 'scattered' })}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${preferences.layout === 'scattered'
                                ? 'bg-white text-blue-600 shadow-sm'
                                : 'text-gray-500 hover:text-gray-700'
                                }`}
                        >
                            <MousePointer2 size={14} />
                            Scattered
                        </button>
                    </div>

                    {/* Max Icons Slider */}
                    <div className="flex items-center gap-3 bg-white border border-gray-200 px-3 py-1.5 rounded-lg shadow-sm">
                        <span className="text-[10px] uppercase font-bold text-gray-400">Limit</span>
                        <input
                            type="range"
                            min="1"
                            max="10"
                            value={preferences.maxIcons}
                            onChange={(e) => updatePrefs({ maxIcons: parseInt(e.target.value) })}
                            className="w-24 h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                        />
                        <span className="text-xs font-mono font-bold w-4 text-center">{preferences.maxIcons}</span>
                    </div>
                </div>
            </div>

            {/* Visual Project Grid */}
            <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-6">
                {projects.map(p => {
                    const isSelected = preferences.visibleProjectIds.includes(p.id);
                    const isDisabled = !isSelected && preferences.visibleProjectIds.length >= preferences.maxIcons;

                    return (
                        <button
                            key={p.id}
                            onClick={() => toggleProject(p.id)}
                            disabled={isDisabled}
                            className={`
                                group relative aspect-square rounded-2xl border-2 border-transparent transition-all duration-200 flex flex-col items-center justify-center gap-4 p-4
                                ${isSelected
                                    ? 'scale-[1.02]'
                                    : isDisabled
                                        ? 'opacity-50 cursor-not-allowed grayscale'
                                        : 'hover:-translate-y-1'
                                }
                            `}
                        >
                            {/* Selected Badge */}
                            {isSelected && (
                                <div className="absolute top-4 right-4 bg-blue-500 text-white p-1.5 rounded-full shadow-lg z-10 animate-in zoom-in duration-200">
                                    <Check size={14} strokeWidth={4} />
                                </div>
                            )}

                            {/* Folder Icon Visualization */}
                            <div className="relative w-full flex-1 aspect-[1.15/1]">
                                {/* Inner Content (Preview) */}
                                <div className="absolute inset-0 rounded-xl flex items-center justify-center overflow-hidden bg-gray-50">
                                    {p.cover ? (
                                        p.cover.match(/\.(mp4|webm)$/i) ? (
                                            <video
                                                src={p.cover}
                                                className="w-full h-full object-cover"
                                                autoPlay
                                                muted
                                                loop
                                                playsInline
                                            />
                                        ) : (
                                            <img src={p.cover} className="w-full h-full object-cover" alt="" />
                                        )
                                    ) : (
                                        <Folder size={48} className="text-blue-300" />
                                    )}
                                </div>

                                {/* Front Plate (Glassy effect) - Optional: making it subtler or removing if user wants simple */}
                                <div className={`absolute bottom-0 w-full h-1/3 bg-gradient-to-t from-black/5 to-transparent rounded-b-xl pointer-events-none`} />
                            </div>

                            {/* Label */}
                            <div className="w-full text-center px-2">
                                <p className={`text-sm font-bold truncate transition-colors ${isSelected ? 'text-blue-700' : 'text-gray-700 group-hover:text-black'}`}>
                                    {p.title}
                                </p>
                                <p className="text-[10px] text-gray-400 font-medium uppercase tracking-wider truncate mt-1">
                                    {p.client}
                                </p>
                            </div>
                        </button>
                    );
                })}
            </div>
        </div>
    );
}

