import React, { useState, useEffect } from 'react';
import { LayoutGrid, Eye, EyeOff, Upload, Save, Pencil, Image as ImageIcon } from 'lucide-react';
import IconPickerModal from './IconPickerModal';

interface DockItemConfig {
    label?: string;
    iconUrl?: string;
    isHidden?: boolean;
}

interface DockPreferences {
    [key: string]: DockItemConfig;
}

interface DockConfigFormProps {
    data?: DockPreferences;
    onUpdate: (data: DockPreferences) => void;
}

const DEFAULT_DOCK_ITEMS = [
    { id: "about", defaultLabel: "About Me" },
    { id: "projects", defaultLabel: "Projects" },
    { id: "contact", defaultLabel: "Contact" },
    { id: "gallery", defaultLabel: "Photos" },
    { id: "whatsapp", defaultLabel: "WhatsApp" },
    { id: "notes", defaultLabel: "Notes" },
    { id: "trash", defaultLabel: "Trash" },
];

export default function DockConfigForm({ data, onUpdate }: DockConfigFormProps) {
    const [preferences, setPreferences] = useState<DockPreferences>({});
    const [isPickerOpen, setIsPickerOpen] = useState(false);
    const [activeItemId, setActiveItemId] = useState<string | null>(null);
    const isInitialMount = React.useRef(true);
    const lastSavedData = React.useRef<string>('');

    // Sync state with props in render (Initial mount only)
    const [lastData, setLastData] = useState<any>(null);
    if (data && data !== lastData) {
        if (isInitialMount.current) {
            setPreferences(data);
            lastSavedData.current = JSON.stringify(data);
        }
        setLastData(data);
    }

    // Debounced Save
    useEffect(() => {
        if (isInitialMount.current) {
            isInitialMount.current = false;
            return;
        }

        const currentString = JSON.stringify(preferences);
        if (currentString === lastSavedData.current) return; // No changes

        const handler = setTimeout(() => {
            onUpdate(preferences);
            lastSavedData.current = currentString;
        }, 1000); // 1 second debounce

        return () => {
            clearTimeout(handler);
        };
    }, [preferences, onUpdate]);

    const handleUpdateItem = (id: string, updates: Partial<DockItemConfig>) => {
        const newPreferences = {
            ...preferences,
            [id]: { ...(preferences[id] || {}), ...updates }
        };
        setPreferences(newPreferences);
    };

    const handleOpenPicker = (id: string) => {
        setActiveItemId(id);
        setIsPickerOpen(true);
    };

    const handleSelectIcon = (url: string) => {
        if (activeItemId) {
            handleUpdateItem(activeItemId, { iconUrl: url });
            setIsPickerOpen(false);
            setActiveItemId(null);
        }
    };

    return (
        <div className="space-y-6">
            <div>
                <h3 className="text-lg font-medium text-gray-900 mb-2">Dock Configuration</h3>
                <p className="text-sm text-gray-600 mb-6">
                    Klik ikon untuk mengganti. Perubahan disimpan secara otomatis (Auto-Save).
                </p>

                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                    {DEFAULT_DOCK_ITEMS.map((item) => {
                        const config = preferences[item.id] || {};
                        const label = config.label || item.defaultLabel;
                        const isHidden = config.isHidden || false;

                        return (
                            <div
                                key={item.id}
                                className={`
                                    relative p-4 rounded-2xl border transition-all duration-200 group
                                    ${isHidden
                                        ? 'bg-gray-50 border-gray-100 opacity-60 grayscale-[0.5]'
                                        : 'bg-white border-gray-200 shadow-sm hover:shadow-md hover:border-blue-200'
                                    }
                                `}
                            >
                                {/* Visibility Toggle (Top Right) */}
                                <button
                                    onClick={() => handleUpdateItem(item.id, { isHidden: !isHidden })}
                                    className={`absolute top-3 right-3 p-1.5 rounded-full transition-all z-10
                                        ${isHidden
                                            ? 'text-gray-400 hover:text-gray-600 bg-gray-100'
                                            : 'text-gray-300 hover:text-blue-500 hover:bg-gray-50 opacity-0 group-hover:opacity-100'
                                        }
                                    `}
                                    title={isHidden ? "Show in Dock" : "Hide from Dock"}
                                >
                                    {isHidden ? <EyeOff size={16} /> : <Eye size={16} />}
                                </button>

                                <div className="flex flex-col items-center text-center gap-3 pt-2">
                                    {/* Large Icon Preview */}
                                    <button
                                        onClick={() => handleOpenPicker(item.id)}
                                        className="relative w-20 h-20 rounded-[22px] overflow-hidden group/icon focus:outline-none focus:ring-4 focus:ring-blue-500/10 transition-transform active:scale-95"
                                    >
                                        <div className="w-full h-full bg-gray-50 flex items-center justify-center">
                                            {config.iconUrl ? (
                                                <img
                                                    src={config.iconUrl}
                                                    alt={label}
                                                    className="w-full h-full object-contain drop-shadow-sm transition-transform group-hover/icon:scale-110"
                                                />
                                            ) : (
                                                <div className="flex flex-col items-center gap-1 opacity-20 text-gray-500">
                                                    <ImageIcon size={24} />
                                                    <span className="text-[9px] font-black uppercase tracking-tighter">{item.id.slice(0, 3)}</span>
                                                </div>
                                            )}
                                        </div>

                                        {/* Edit Overlay */}
                                        <div className="absolute inset-0 bg-black/40 backdrop-blur-[2px] opacity-0 group-hover/icon:opacity-100 flex items-center justify-center transition-all duration-200">
                                            <Pencil size={20} className="text-white drop-shadow-md scale-90 group-hover/icon:scale-100 transition-transform" />
                                        </div>
                                    </button>

                                    {/* Label Input */}
                                    <div className="w-full space-y-1">
                                        <input
                                            type="text"
                                            value={label}
                                            onChange={(e) => handleUpdateItem(item.id, { label: e.target.value })}
                                            className="w-full text-center text-sm font-semibold bg-transparent border-none p-0 focus:ring-0 hover:text-blue-600 placeholder-gray-300 transition-colors cursor-text"
                                            placeholder="Label"
                                        />
                                        <div className="h-0.5 w-8 bg-gray-100 mx-auto rounded-full group-hover:bg-blue-100 transition-colors" />
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Icon Picker Modal */}
            <IconPickerModal
                isOpen={isPickerOpen}
                onClose={() => setIsPickerOpen(false)}
                onSelect={handleSelectIcon}
                currentIcon={activeItemId ? preferences[activeItemId]?.iconUrl : undefined}
            />
        </div >
    );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Trash2, Edit2, Save, X, MoveUp, MoveDown, Sparkles, Loader2, Search } from 'lucide-react';
import { useAdminAuth } from '@/hooks/useAdminAuth';

interface HardSkill {
    id: string;
    name: string;
    icon: string;
    level: string;
    color: string;
    details: string[];
}

export default function HardSkillsManager() {
    const [skills, setSkills] = useState<HardSkill[]>([]);
    const [loading, setLoading] = useState(true);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editForm, setEditForm] = useState<HardSkill | null>(null);
    const [isAdding, setIsAdding] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);
    const [isSearchingIcon, setIsSearchingIcon] = useState(false);
    const { csrfToken } = useAdminAuth();

    const handleAutoIcon = async () => {
        if (!editForm?.name) {
            alert('Please enter a Skill Name first!');
            return;
        }

        setIsSearchingIcon(true);
        try {
            const res = await fetch('/api/utils/search-icon', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-csrf-token': csrfToken
                },
                credentials: 'include',
                body: JSON.stringify({ query: editForm.name })
            });

            if (res.ok) {
                const data = await res.json();
                if (data.iconUrl) {
                    setEditForm(prev => prev ? { ...prev, icon: data.iconUrl } : null);
                }
            } else {
                alert('Icon not found. Please try manually or check the name.');
            }
        } catch (err) {
            console.error(err);
        } finally {
            setIsSearchingIcon(false);
        }
    };

    const handleAiGenerate = async () => {
        if (!editForm?.name) {
            alert('Please enter a Skill Name first!');
            return;
        }

        setIsGenerating(true);
        try {
            const res = await fetch('/api/ai/suggest-skills', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-csrf-token': csrfToken
                },
                credentials: 'include',
                body: JSON.stringify({ skillName: editForm.name })
            });

            if (res.ok) {
                const data = await res.json();
                if (data.details && Array.isArray(data.details)) {
                    // Ensure exactly 4 items
                    const newDetails = [...data.details, '', '', '', ''].slice(0, 4);
                    setEditForm(prev => prev ? { ...prev, details: newDetails } : null);
                }
            } else {
                alert('Failed to generate suggestions. Please try again.');
            }
        } catch (err) {
            console.error(err);
            alert('Error connecting to AI.');
        } finally {
            setIsGenerating(false);
        }
    };

    // Initial fetch
    useEffect(() => {
        fetchSkills();
    }, []);

    const fetchSkills = async () => {
        setLoading(true);
        try {
            const res = await fetch('/api/hard-skills');
            if (res.ok) {
                const data = await res.json();
                setSkills(data);
            }
        } catch (error) {
            console.error('Error fetching skills:', error);
        } finally {
            setLoading(false);
        }
    };

    const saveOrder = async (newSkills: HardSkill[]) => {
        setSkills(newSkills);
        await fetch('/api/hard-skills', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-csrf-token': csrfToken
            },
            credentials: 'include',
            body: JSON.stringify(newSkills),
        });
    };

    const moveUp = (index: number) => {
        if (index === 0) return;
        const newSkills = [...skills];
        [newSkills[index - 1], newSkills[index]] = [newSkills[index], newSkills[index - 1]];
        saveOrder(newSkills);
    };

    const moveDown = (index: number) => {
        if (index === skills.length - 1) return;
        const newSkills = [...skills];
        [newSkills[index + 1], newSkills[index]] = [newSkills[index], newSkills[index + 1]];
        saveOrder(newSkills);
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this skill?')) return;
        const newSkills = skills.filter(s => s.id !== id);
        saveOrder(newSkills);
    };

    const handleEdit = (skill: HardSkill) => {
        setEditingId(skill.id);
        setEditForm({ ...skill });
        setIsAdding(false);
    };

    const handleAdd = () => {
        const newSkill: HardSkill = {
            id: Date.now().toString(),
            name: '',
            icon: '',
            level: 'Intermediate',
            color: '#000000',
            details: ['', '', '', '']
        };
        setEditForm(newSkill);
        setIsAdding(true);
        setEditingId(null);
    };

    const handleSave = async () => {
        if (!editForm) return;

        let newSkills = [...skills];
        if (isAdding) {
            newSkills.push(editForm);
        } else {
            newSkills = newSkills.map(s => s.id === editForm.id ? editForm : s);
        }

        await saveOrder(newSkills);
        setEditingId(null);
        setIsAdding(false);
        setEditForm(null);
    };

    const updateFormDetail = (index: number, value: string) => {
        if (!editForm) return;
        const newDetails = [...editForm.details];
        newDetails[index] = value;
        setEditForm({ ...editForm, details: newDetails });
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold">Hard Skills Manager</h2>
                <button
                    onClick={handleAdd}
                    className="flex items-center gap-2 bg-black text-white px-4 py-2 rounded-lg hover:bg-gray-800"
                >
                    <Plus size={18} /> Add New Skill
                </button>
            </div>

            {/* Editor Modal/Form */}
            <AnimatePresence>
                {(editingId || isAdding) && editForm && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        className="bg-gray-50 p-6 rounded-xl border border-gray-200 mb-6 space-y-4"
                    >
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold text-lg">{isAdding ? 'Add New Skill' : 'Edit Skill'}</h3>
                            <button onClick={() => { setIsAdding(false); setEditingId(null); setEditForm(null); }}><X size={20} /></button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium mb-1">Skill Name</label>
                                <input
                                    type="text"
                                    value={editForm.name}
                                    onChange={e => setEditForm({ ...editForm, name: e.target.value })}
                                    className="w-full p-2 border rounded-lg"
                                    placeholder="e.g. Photoshop"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium mb-1">Level</label>
                                <select
                                    value={editForm.level}
                                    onChange={e => setEditForm({ ...editForm, level: e.target.value })}
                                    className="w-full p-2 border rounded-lg"
                                >
                                    <option value="Basic">Basic</option>
                                    <option value="Intermediate">Intermediate</option>
                                    <option value="Advanced">Advanced</option>
                                    <option value="Expert">Expert</option>
                                </select>
                            </div>
                            <div>
                                <div className="flex justify-between items-center mb-1">
                                    <label className="block text-sm font-medium">Icon URL (SVG)</label>
                                    <button
                                        onClick={handleAutoIcon}
                                        disabled={isSearchingIcon || !editForm.name}
                                        className="text-xs flex items-center gap-1 text-blue-600 hover:text-blue-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors font-medium bg-blue-50 px-2 py-1 rounded-md"
                                    >
                                        {isSearchingIcon ? <Loader2 size={12} className="animate-spin" /> : <Search size={12} />}
                                        {isSearchingIcon ? 'Searching...' : 'Find Icon'}
                                    </button>
                                </div>
                                <input
                                    type="text"
                                    value={editForm.icon}
                                    onChange={e => setEditForm({ ...editForm, icon: e.target.value })}
                                    className="w-full p-2 border rounded-lg"
                                    placeholder="https://cdn..."
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium mb-1">Color (Hex)</label>
                                <div className="flex gap-2">
                                    <input
                                        type="color"
                                        value={editForm.color}
                                        onChange={e => setEditForm({ ...editForm, color: e.target.value })}
                                        className="h-10 w-10 p-1 rounded cursor-pointer"
                                    />
                                    <input
                                        type="text"
                                        value={editForm.color}
                                        onChange={e => setEditForm({ ...editForm, color: e.target.value })}
                                        className="w-full p-2 border rounded-lg"
                                    />
                                </div>
                            </div>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-sm font-medium">Capabilities (4 Points)</label>
                                <button
                                    onClick={handleAiGenerate}
                                    disabled={isGenerating || !editForm.name}
                                    className="text-xs flex items-center gap-1 text-purple-600 hover:text-purple-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors font-medium bg-purple-50 px-2 py-1 rounded-md"
                                >
                                    {isGenerating ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                                    {isGenerating ? 'Thinking...' : 'AI Auto-Fill'}
                                </button>
                            </div>
                            <div className="space-y-2">
                                {editForm.details.map((detail, idx) => (
                                    <input
                                        key={idx}
                                        type="text"
                                        value={detail}
                                        onChange={e => updateFormDetail(idx, e.target.value)}
                                        className="w-full p-2 border rounded-lg"
                                        placeholder={`Point ${idx + 1}`}
                                    />
                                ))}
                            </div>
                        </div>

                        <div className="pt-4 flex justify-end gap-3">
                            <button
                                onClick={() => { setIsAdding(false); setEditingId(null); setEditForm(null); }}
                                className="px-4 py-2 text-gray-600 hover:text-black"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleSave}
                                className="px-6 py-2 bg-black text-white rounded-lg hover:bg-gray-800 flex items-center gap-2"
                            >
                                <Save size={18} /> Save Skill
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Skills List */}
            <div className="bg-white rounded-xl border shadow-sm divide-y">
                {skills.map((skill, index) => (
                    <div key={skill.id} className="p-4 flex items-center justify-between hover:bg-gray-50">
                        <div className="flex items-center gap-4">
                            <div className="flex flex-col gap-1">
                                <button
                                    disabled={index === 0}
                                    onClick={() => moveUp(index)}
                                    className="p-1 text-gray-400 hover:text-black disabled:opacity-30"
                                >
                                    <MoveUp size={16} />
                                </button>
                                <button
                                    disabled={index === skills.length - 1}
                                    onClick={() => moveDown(index)}
                                    className="p-1 text-gray-400 hover:text-black disabled:opacity-30"
                                >
                                    <MoveDown size={16} />
                                </button>
                            </div>
                            <img src={skill.icon} alt="" className="w-8 h-8 object-contain" />
                            <div>
                                <h4 className="font-bold">{skill.name}</h4>
                                <span className="text-xs px-2 py-0.5 rounded-full bg-gray-100 text-gray-600">
                                    {skill.level}
                                </span>
                            </div>
                        </div>
                        <div className="flex gap-2">
                            <button
                                onClick={() => handleEdit(skill)}
                                className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"
                            >
                                <Edit2 size={18} />
                            </button>
                            <button
                                onClick={() => handleDelete(skill.id)}
                                className="p-2 text-red-600 hover:bg-red-50 rounded-lg"
                            >
                                <Trash2 size={18} />
                            </button>
                        </div>
                    </div>
                ))}
                {skills.length === 0 && !loading && (
                    <div className="p-8 text-center text-gray-500">
                        No skills found. Add one to get started.
                    </div>
                )}
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { X, Trash2, Search, Upload, CheckCircle2, Loader2, Image as ImageIcon, RotateCcw } from 'lucide-react';
import AdminFileUpload from '@/app/admin/components/AdminFileUpload';
import { useAdminAuth } from '@/hooks/useAdminAuth';

interface IconPickerModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSelect: (url: string) => void;
    currentIcon?: string;
}

export default function IconPickerModal({ isOpen, onClose, onSelect, currentIcon }: IconPickerModalProps) {
    const [icons, setIcons] = useState<string[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [refreshTrigger, setRefreshTrigger] = useState(0);

    const [selectedUrl, setSelectedUrl] = useState<string | null>(null);
    const { csrfToken } = useAdminAuth();

    useEffect(() => {
        if (!isOpen) return;

        const fetchIcons = async () => {
            setLoading(true);
            try {
                const res = await fetch(`/api/admin/icons?v=${Date.now()}`);
                const data = await res.json();
                if (data.icons) setIcons(data.icons);
            } catch (e) {
                console.error('Failed to fetch icons', e);
            } finally {
                setLoading(false);
            }
        };

        fetchIcons();
    }, [isOpen, refreshTrigger]);

    // Handle ESC key
    useEffect(() => {
        const handleEsc = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };
        window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [onClose]);

    const handleIconClick = (url: string) => {
        if (selectedUrl) return; // Prevent double clicks
        setSelectedUrl(url);
        // Delay to show animation
        setTimeout(() => {
            onSelect(url);
            setSelectedUrl(null); // Reset for next time
        }, 300);
    };

    const handleDelete = async (e: React.MouseEvent, url: string) => {
        e.stopPropagation();
        if (!window.confirm('Hapus ikon ini secara permanen?')) return;

        try {
            const res = await fetch(`/api/admin/icons?url=${encodeURIComponent(url)}`, {
                method: 'DELETE',
                headers: {
                    'x-csrf-token': csrfToken
                }
            });
            if (res.ok) {
                setRefreshTrigger(prev => prev + 1);
            } else {
                const data = await res.json();
                alert(`Gagal menghapus ikon: ${data.error || 'Permission Denied'}`);
            }
        } catch (e) {
            console.error('Delete error', e);
            alert('Terjadi kesalahan saat menghapus');
        }
    };

    if (!isOpen) return null;

    const filteredIcons = icons.filter(icon =>
        icon.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            {/* Backdrop */}
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />

            {/* Modal Content */}
            <div className="bg-white w-full max-w-4xl max-h-[85vh] rounded-2xl shadow-2xl overflow-hidden relative flex flex-col animate-in fade-in zoom-in duration-200">

                {/* Header */}
                <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                    <div>
                        <h2 className="text-xl font-bold text-gray-900">Icon Library</h2>
                        <p className="text-sm text-gray-500">Pilih dari koleksi atau upload ikon baru</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-400">
                        <X size={24} />
                    </button>
                </div>

                <div className="flex-1 overflow-hidden flex flex-col md:flex-row">

                    {/* Sidebar / Upload Area */}
                    <div className="w-full md:w-72 border-r border-gray-100 p-6 bg-gray-50/50 flex flex-col gap-6">
                        <div className="space-y-2">
                            <h3 className="text-xs font-bold uppercase text-gray-400 tracking-wider">Quick Upload</h3>
                            <div className="bg-white border-2 border-dashed border-gray-200 rounded-xl p-4 transition-all hover:border-blue-400 group">
                                <AdminFileUpload
                                    folder="assets/icons-library"
                                    multiple={true}
                                    accept="image/*,.icns"
                                    onUpload={() => setRefreshTrigger(prev => prev + 1)}
                                />
                            </div>
                            <p className="text-[10px] text-gray-400 leading-tight">
                                Dukungan .icns, .png, .webp. Otomatis dikonversi & dioptimasi.
                            </p>
                        </div>

                        <div className="space-y-2">
                            <div className="flex items-center justify-between">
                                <h3 className="text-xs font-bold uppercase text-gray-400 tracking-wider">Search</h3>
                                <button
                                    onClick={() => setRefreshTrigger(prev => prev + 1)}
                                    className="p-1 hover:bg-gray-100 rounded-lg transition-colors text-gray-400 hover:text-blue-500"
                                    title="Refresh Library"
                                >
                                    <RotateCcw size={14} className={loading ? 'animate-spin' : ''} />
                                </button>
                            </div>
                            <div className="relative">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                                <input
                                    type="text"
                                    placeholder="Cari ikon..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Main Gallery Grid */}
                    <div className="flex-1 overflow-y-auto p-6">
                        {loading ? (
                            <div className="h-full flex flex-col items-center justify-center text-gray-400 gap-3">
                                <Loader2 className="animate-spin" size={32} />
                                <p className="text-sm">Memuat galeri ikon...</p>
                            </div>
                        ) : filteredIcons.length > 0 ? (
                            <div className="grid grid-cols-3 sm:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
                                {filteredIcons.map((iconUrl, idx) => {
                                    const isSelected = selectedUrl === iconUrl;
                                    const isActive = currentIcon === iconUrl || isSelected;

                                    return (
                                        <div
                                            key={idx}
                                            onClick={() => handleIconClick(iconUrl)}
                                            className={`aspect-square rounded-2xl border-2 transition-all group relative flex items-center justify-center p-2 cursor-pointer
                                                ${isActive ? 'border-blue-500 bg-blue-50/30' : 'border-gray-100 bg-white hover:border-blue-200 hover:shadow-md'}
                                                ${isSelected ? 'scale-95 ring-4 ring-blue-500/20' : ''}
                                                ${selectedUrl ? 'pointer-events-none opacity-50' : ''}
                                            `}
                                        >
                                            <img
                                                src={iconUrl}
                                                alt="icon"
                                                className="w-full h-full object-contain drop-shadow-sm transition-transform group-hover:scale-110"
                                            />
                                            {isActive && (
                                                <div className="absolute -top-2 -right-2 bg-blue-500 text-white rounded-full p-0.5 shadow-lg animate-in zoom-in duration-200">
                                                    <CheckCircle2 size={16} />
                                                </div>
                                            )}

                                            {/* Delete Button - Using Trash icon now, bottom-right and subtle */}
                                            <button
                                                onClick={(e) => handleDelete(e, iconUrl)}
                                                onContextMenu={(e) => {
                                                    e.preventDefault();
                                                    handleDelete(e, iconUrl);
                                                }}
                                                className="absolute bottom-1 right-1 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all z-20 p-1.5 rounded-lg hover:bg-red-50"
                                                title="Hapus ikon (Klik kanan juga bisa)"
                                                type="button"
                                            >
                                                <Trash2 size={16} />
                                            </button>

                                            <div className="absolute inset-0 bg-blue-500/0 group-hover:bg-blue-500/5 rounded-2xl transition-colors" />
                                        </div>
                                    );
                                })}
                            </div>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center text-gray-400 gap-2">
                                <ImageIcon size={48} className="opacity-20" />
                                <p className="text-sm font-medium">Belum ada ikon di folder ini.</p>
                                <p className="text-xs text-gray-500">Upload beberapa file untuk memulai.</p>
                            </div>
                        )}
                    </div>
                </div>

                {/* Footer */}
                <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end">
                    <button
                        onClick={onClose}
                        className="px-6 py-2 bg-white border border-gray-200 text-gray-700 rounded-lg hover:bg-gray-50 text-sm font-medium transition-colors"
                    >
                        Close
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useRef } from 'react';
import { Plus, Trash2, Save, Bell, Eye, EyeOff, MessageSquare, Clock, User as UserIcon, Check, Pencil, X, Info, Sparkles, Wand2, Loader2 } from 'lucide-react';
import { useToast } from '@/contexts/ToastContext';
import { AboutIslandNotification, ChatMessage } from '@/types/about';
import { useAdminAuth } from '@/hooks/useAdminAuth';

interface NotificationsManagerProps {
    notifications: AboutIslandNotification[];
    onUpdate: (notifications: AboutIslandNotification[]) => void;
}

export default function NotificationsManager({ notifications, onUpdate }: NotificationsManagerProps) {
    const [localNotifications, setLocalNotifications] = useState<AboutIslandNotification[]>(notifications || []);
    const [selectedNotifId, setSelectedNotifId] = useState<string | null>(null);
    const { showSuccess, showError } = useToast();
    const { csrfToken } = useAdminAuth();
    const [saving, setSaving] = useState(false);
    const [generatingAiId, setGeneratingAiId] = useState<string | null>(null);
    const [generatingNotifId, setGeneratingNotifId] = useState<string | null>(null);
    const scrollRef = useRef<HTMLDivElement>(null);

    const handleAdd = () => {
        const newNotif: AboutIslandNotification = {
            id: crypto.randomUUID(),
            name: 'Nama Pengirim',
            message: 'Isi pesan notifikasi...',
            avatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?q=80&w=150&auto=format&fit=crop',
            isActive: true,
            conversation: [],
            status: 'Online'
        };
        setLocalNotifications([...localNotifications, newNotif]);
        setSelectedNotifId(newNotif.id); // Langsung buka mode edit untuk notifikasi baru
    };

    const handleUpdate = (id: string, updates: Partial<AboutIslandNotification>) => {
        setLocalNotifications(localNotifications.map((n: AboutIslandNotification) => n.id === id ? { ...n, ...updates } : n));
    };

    const handleDelete = (id: string) => {
        if (confirm('Apakah Anda yakin ingin menghapus notifikasi ini?')) {
            setLocalNotifications(localNotifications.filter((n: AboutIslandNotification) => n.id !== id));
            if (selectedNotifId === id) setSelectedNotifId(null);
        }
    };

    const handleSave = async () => {
        try {
            setSaving(true);
            await onUpdate(localNotifications);
            showSuccess('Daftar notifikasi berhasil diperbarui.');
        } catch (err) {
            showError('Gagal memperbarui notifikasi.');
        } finally {
            setSaving(false);
        }
    };

    const handleAiGenerateNotif = async (notif: AboutIslandNotification) => {
        try {
            setGeneratingNotifId(notif.id);
            const res = await fetch('/api/ai/generate-notif-message', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-csrf-token': csrfToken
                },
                credentials: 'include',
                body: JSON.stringify({ senderName: notif.name })
            });

            if (!res.ok) throw new Error('AI Generation failed');

            const data = await res.json();
            handleUpdate(notif.id, { message: data.message });
            showSuccess('Pesan notifikasi berhasil di-generate!');
        } catch (err) {
            showError('Gagal generate pesan.');
        } finally {
            setGeneratingNotifId(null);
        }
    };

    const handleAiGenerate = async (notif: AboutIslandNotification) => {
        try {
            setGeneratingAiId(notif.id);
            const res = await fetch('/api/ai/generate-conversation', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-csrf-token': csrfToken
                },
                credentials: 'include',
                body: JSON.stringify({
                    senderName: notif.name,
                    notifMessage: notif.message
                })
            });

            if (!res.ok) throw new Error('AI Generation failed');

            const generatedMessages = await res.json();

            // Suffix IDs to avoid collision and ensure uniqueness
            const timestamp = Date.now();
            const sanitizedMessages = generatedMessages.map((msg: any, i: number) => ({
                ...msg,
                id: timestamp + i
            }));

            handleUpdate(notif.id, {
                conversation: [...(notif.conversation || []), ...sanitizedMessages]
            });

            showSuccess('AI berhasil membuatkan kelanjutan chat!');
        } catch (err) {
            showError('Gagal generate chat via AI.');
        } finally {
            setGeneratingAiId(null);
        }
    };

    // Auto-resize chat textareas and auto-scroll to bottom
    useEffect(() => {
        if (!scrollRef.current) return;

        // Auto-resize chat bubbles only
        const textareas = scrollRef.current.querySelectorAll('textarea.chat-textarea');
        textareas.forEach(ta => {
            const el = ta as HTMLTextAreaElement;
            el.style.height = 'auto';
            el.style.height = `${el.scrollHeight}px`;
        });

        // Auto-scroll to bottom when conversation changes
        const scrollContainer = scrollRef.current;
        scrollContainer.scrollTo({
            top: scrollContainer.scrollHeight,
            behavior: 'smooth'
        });
    }, [localNotifications, selectedNotifId]);

    return (
        <div className="space-y-6">
            <div className="bg-indigo-50 border border-indigo-200 rounded-lg p-4 flex items-start sm:items-center justify-between gap-4">
                <div>
                    <h3 className="font-bold text-indigo-800 flex items-center gap-2">
                        <Bell className="w-5 h-5" /> Kelola Notifikasi Dynamic Island
                    </h3>
                    <p className="text-sm text-indigo-600 mt-1 italic">
                        Klik ikon Edit untuk menyesuaikan data pengirim dan alur chatting WhatsApp.
                    </p>
                </div>
                <div className="flex gap-2 shrink-0">
                    <button
                        onClick={handleAdd}
                        className="flex items-center gap-2 px-4 py-2 bg-white text-indigo-700 border border-indigo-200 rounded-lg hover:bg-slate-50 transition-colors text-sm font-bold"
                    >
                        <Plus size={16} /> Tambah
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={saving}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors text-sm font-bold shadow-lg shadow-indigo-200 disabled:opacity-50"
                    >
                        <Save size={16} /> {saving ? 'Menyimpan...' : 'Simpan Perubahan'}
                    </button>
                </div>
            </div>

            {/* List View Container */}
            <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden mb-20">
                {/* Table Header - Desktop Only */}
                <div className="hidden md:grid grid-cols-[80px_1fr_120px] items-center px-8 py-4 bg-gray-50 border-b border-gray-200 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                    <div>Avatar</div>
                    <div className="text-center">Status Notifikasi</div>
                    <div className="text-right">Actions</div>
                </div>

                <div className="divide-y divide-gray-100">
                    {localNotifications.map((notif: AboutIslandNotification) => (
                        <div key={notif.id} className={`group px-2 md:px-3 py-6 hover:bg-indigo-50/20 transition-colors ${!notif.isActive ? 'bg-gray-50/50' : ''}`}>
                            <div className="flex flex-col md:grid md:grid-cols-[80px_1fr_120px] items-center gap-4">

                                {/* Avatar */}
                                <div className="w-[60px] relative shrink-0">
                                    <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-white shadow-sm ring-2 ring-indigo-50 bg-gray-100">
                                        <img src={notif.avatar} alt={notif.name} className="w-full h-full object-cover" />
                                    </div>
                                    <div className={`absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 border-2 border-white rounded-full ${notif.isActive ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                                </div>

                                {/* Status Toggle */}
                                <div className="flex justify-center">
                                    <button
                                        onClick={() => handleUpdate(notif.id, { isActive: !notif.isActive })}
                                        className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all ${notif.isActive
                                            ? 'text-green-600'
                                            : 'text-gray-400'
                                            }`}
                                    >
                                        {notif.isActive ? <><Eye size={12} strokeWidth={3} /> Aktif</> : <><EyeOff size={12} strokeWidth={3} /> Draft</>}
                                    </button>
                                </div>

                                {/* Actions */}
                                <div className="flex justify-end items-center gap-2 w-full md:w-auto">
                                    <button
                                        onClick={() => setSelectedNotifId(selectedNotifId === notif.id ? null : notif.id)}
                                        className={`p-2 rounded-lg transition-all ${selectedNotifId === notif.id
                                            ? 'bg-amber-100 text-amber-600'
                                            : 'text-indigo-600 hover:bg-indigo-50 active:bg-indigo-100'
                                            }`}
                                        title={selectedNotifId === notif.id ? "Tutup" : "Edit"}
                                    >
                                        {selectedNotifId === notif.id ? <X size={20} /> : <Pencil size={20} />}
                                    </button>
                                    <button
                                        onClick={() => handleDelete(notif.id)}
                                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                        title="Hapus"
                                    >
                                        <Trash2 size={18} />
                                    </button>
                                </div>
                            </div>

                            {selectedNotifId === notif.id && (
                                <div className="mt-6 border-t border-gray-100 pt-8 pb-4 animate-in fade-in slide-in-from-top-4 duration-500 ease-out">
                                    <div className="space-y-10">

                                        {/* Row 1: Notification Info (Horizontal on Desktop) */}
                                        <div className="space-y-4">
                                            <div className="flex items-center gap-2.5 mb-2">
                                                <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg shadow-sm">
                                                    <Info size={18} />
                                                </div>
                                                <div>
                                                    <h4 className="font-black text-gray-800 text-sm uppercase tracking-tight">Detail Notifikasi</h4>
                                                    <p className="text-[10px] text-gray-400 font-medium">Pengaturan utama yang tampil pada Dynamic Island.</p>
                                                </div>
                                            </div>

                                            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 bg-indigo-50/20 p-6 rounded-3xl border border-indigo-50 shadow-inner">
                                                <div>
                                                    <label className="text-[9px] font-black text-indigo-300 uppercase tracking-[0.2em] block mb-2 ml-1">Nama Pengirim</label>
                                                    <input
                                                        type="text"
                                                        value={notif.name}
                                                        onChange={(e) => handleUpdate(notif.id, { name: e.target.value })}
                                                        className="w-full text-sm font-bold bg-white border border-indigo-100 rounded-xl px-4 py-3 shadow-sm focus:ring-2 focus:ring-indigo-400 focus:outline-none transition-all"
                                                        placeholder="Misal: Rini (HRD)"
                                                    />
                                                </div>
                                                <div>
                                                    <label className="text-[9px] font-black text-indigo-300 uppercase tracking-[0.2em] block mb-2 ml-1">Avatar Profile URL</label>
                                                    <input
                                                        type="text"
                                                        value={notif.avatar}
                                                        onChange={(e) => handleUpdate(notif.id, { avatar: e.target.value })}
                                                        className="w-full text-[10px] font-mono bg-white border border-indigo-100 rounded-xl px-4 py-3 shadow-sm focus:ring-2 focus:ring-indigo-400 focus:outline-none transition-all"
                                                        placeholder="https://..."
                                                    />
                                                </div>
                                                <div>
                                                    <div className="flex items-center justify-between mb-2 ml-1">
                                                        <label className="text-[9px] font-black text-indigo-300 uppercase tracking-[0.2em] block">Pesan Notifikasi</label>
                                                        <button
                                                            onClick={() => handleAiGenerateNotif(notif)}
                                                            disabled={generatingNotifId === notif.id}
                                                            className="text-indigo-400 hover:text-indigo-600 transition-colors disabled:opacity-50"
                                                            title="Generate via AI"
                                                        >
                                                            {generatingNotifId === notif.id ? (
                                                                <Loader2 size={12} className="animate-spin" />
                                                            ) : (
                                                                <Sparkles size={12} />
                                                            )}
                                                        </button>
                                                    </div>
                                                    <input
                                                        type="text"
                                                        value={notif.message}
                                                        onChange={(e) => handleUpdate(notif.id, { message: e.target.value })}
                                                        className="w-full text-sm font-bold bg-white border border-indigo-100 rounded-xl px-4 py-3 shadow-sm focus:ring-2 focus:ring-indigo-400 focus:outline-none transition-all"
                                                        placeholder="Isi pesan di Island..."
                                                    />
                                                </div>
                                            </div>
                                        </div>

                                        {/* Row 2: Conversation History (Full Width) */}
                                        <div className="space-y-4 border-t border-gray-50 pt-8">
                                            {/* Magic AI Helper Section */}
                                            <div className="bg-gradient-to-r from-violet-50 to-fuchsia-50 p-4 border border-violet-100 rounded-3xl mb-4">
                                                <div className="flex items-center justify-between">
                                                    <div>
                                                        <h4 className="text-sm font-bold text-violet-900 flex items-center gap-2">
                                                            <Sparkles className="w-4 h-4 text-violet-600" />
                                                            Magic AI Chat Helper
                                                        </h4>
                                                        <p className="text-[10px] text-violet-600 mt-0.5 font-medium">
                                                            Generate alur chat otomatis berdasarkan pengirim & pesan di atas.
                                                        </p>
                                                    </div>

                                                    <button
                                                        onClick={() => handleAiGenerate(notif)}
                                                        disabled={generatingAiId === notif.id}
                                                        className="flex items-center gap-2 px-4 py-2 text-[10px] font-black uppercase tracking-wider text-white bg-violet-600 hover:bg-violet-700 rounded-xl shadow-lg shadow-violet-200 transition-all disabled:opacity-50"
                                                    >
                                                        {generatingAiId === notif.id ? (
                                                            <>
                                                                <Loader2 className="w-3 h-3 animate-spin" />
                                                                Thinking...
                                                            </>
                                                        ) : (
                                                            <>
                                                                <Wand2 className="w-3 h-3" />
                                                                Generate Chat
                                                            </>
                                                        )}
                                                    </button>
                                                </div>
                                            </div>

                                            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-2">
                                                <div className="flex items-center gap-3">
                                                    <div className="p-2 bg-green-50 text-green-600 rounded-lg shadow-sm border border-green-100">
                                                        <MessageSquare size={20} />
                                                    </div>
                                                    <div>
                                                        <h4 className="font-black text-gray-800 text-sm uppercase tracking-tight">Kustomisasi Chat WA</h4>
                                                        <p className="text-[10px] text-gray-400 font-medium">Alur percakapan setelah notifikasi diklik.</p>
                                                    </div>
                                                </div>

                                                <div className="flex items-center gap-4 self-end sm:self-auto">
                                                    <div className="flex flex-col items-end mr-1">
                                                        <span className="text-[9px] font-black text-indigo-300 uppercase tracking-[0.2em] leading-none mb-1.5">Status Online</span>
                                                        <input
                                                            type="text"
                                                            value={notif.status || ''}
                                                            onChange={(e) => handleUpdate(notif.id, { status: e.target.value })}
                                                            className="text-right text-xs font-black text-indigo-600 bg-indigo-50 px-2 py-1 rounded border-none focus:ring-0 placeholder:text-gray-300 w-28"
                                                            placeholder="Online"
                                                        />
                                                    </div>
                                                    <button
                                                        onClick={() => {
                                                            const newMsg: ChatMessage = {
                                                                id: Date.now(),
                                                                text: 'Pesan baru...',
                                                                isMe: false,
                                                                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                                                                status: 'read'
                                                            };
                                                            handleUpdate(notif.id, { conversation: [...(notif.conversation || []), newMsg] });
                                                        }}
                                                        className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-all shadow-md text-xs font-black uppercase tracking-tighter"
                                                    >
                                                        <Plus size={16} /> Tambah Balon Chat
                                                    </button>
                                                </div>
                                            </div>

                                            <div ref={scrollRef} className="space-y-5 p-3 md:p-4 bg-gray-50/50 rounded-[2rem] border border-gray-200/50 shadow-inner custom-scrollbar relative overflow-hidden">
                                                <div className="max-h-[600px] overflow-y-auto pr-2 space-y-6">
                                                    {(notif.conversation || []).map((msg: ChatMessage, idx: number) => (
                                                        <div key={msg.id} className={`flex items-start gap-4 group/msg ${msg.isMe ? 'flex-row-reverse' : 'flex-row'} animate-in zoom-in-95 duration-300`}>
                                                            {/* Avatar icon in chat for Them */}
                                                            {!msg.isMe && (
                                                                <div className="w-10 h-10 rounded-full overflow-hidden border-2 border-white shadow-md shrink-0 mt-2">
                                                                    <img src={notif.avatar} className="w-full h-full object-cover" />
                                                                </div>
                                                            )}

                                                            <div className={`pt-3 pb-3 px-4 rounded-2xl flex-1 max-w-[100%] transition-all border ${msg.isMe ? 'bg-[#DCF8C6] text-gray-800 rounded-tr-none border-[#beddb0]' : 'bg-white text-gray-800 rounded-tl-none border-black/10'}`}>
                                                                <div className="flex flex-col gap-2">
                                                                    {/* Participant Label at the TOP */}
                                                                    <div className={`flex items-center gap-1.5 ${msg.isMe ? 'flex-row' : 'flex-row'}`}>
                                                                        {msg.isMe && <div className="w-2 h-2 rounded-full bg-green-500" />}
                                                                        <button
                                                                            onClick={() => {
                                                                                const newConv = [...(notif.conversation || [])];
                                                                                newConv[idx] = { ...msg, isMe: !msg.isMe };
                                                                                handleUpdate(notif.id, { conversation: newConv });
                                                                            }}
                                                                            className={`text-[9px] font-black uppercase tracking-widest transition-all border-none outline-none focus:outline-none ${msg.isMe ? 'text-green-700' : 'text-gray-400'} hover:opacity-100 flex items-center gap-1`}
                                                                        >
                                                                            {msg.isMe ? 'SAYA (DESIGNER)' : 'DIA (GUEST)'}
                                                                        </button>
                                                                    </div>
                                                                    <textarea
                                                                        value={msg.text}
                                                                        onChange={(e) => {
                                                                            const newConv = [...(notif.conversation || [])];
                                                                            newConv[idx] = { ...msg, text: e.target.value };
                                                                            handleUpdate(notif.id, { conversation: newConv });
                                                                        }}
                                                                        rows={1}
                                                                        className="chat-textarea w-full bg-transparent border-none focus:ring-0 p-0 text-sm font-semibold md:text-base resize-none overflow-hidden placeholder:text-gray-400 tracking-tight leading-normal"
                                                                        placeholder="Tulis pesan..."
                                                                        onInput={(e) => {
                                                                            const target = e.target as HTMLTextAreaElement;
                                                                            target.style.height = 'auto';
                                                                            target.style.height = `${target.scrollHeight}px`;
                                                                        }}
                                                                    />

                                                                    <div className={`flex items-center gap-3 border-t border-black/5 pt-2 mt-1 ${msg.isMe ? 'justify-end' : 'justify-start'}`}>
                                                                        <div className={`flex items-center gap-1 ${msg.isMe ? 'opacity-60' : 'opacity-40'}`}>
                                                                            <Clock size={11} />
                                                                            <input
                                                                                type="text"
                                                                                value={msg.time}
                                                                                onChange={(e) => {
                                                                                    const newConv = [...(notif.conversation || [])];
                                                                                    newConv[idx] = { ...msg, time: e.target.value };
                                                                                    handleUpdate(notif.id, { conversation: newConv });
                                                                                }}
                                                                                className="w-10 bg-transparent border-none focus:ring-0 p-0 text-[10px] font-bold"
                                                                            />
                                                                        </div>
                                                                        <div className={`flex -space-x-1.5 ${msg.isMe ? 'text-blue-500' : 'opacity-40 text-blue-500'}`}>
                                                                            <Check size={12} strokeWidth={3} />
                                                                            <Check size={12} strokeWidth={3} />
                                                                        </div>
                                                                    </div>
                                                                </div>
                                                            </div>
                                                            <button
                                                                onClick={() => {
                                                                    if (confirm('Hapus balon chat ini?')) {
                                                                        const newConv = (notif.conversation || []).filter((m: ChatMessage) => m.id !== msg.id);
                                                                        handleUpdate(notif.id, { conversation: newConv });
                                                                    }
                                                                }}
                                                                className="p-3 text-gray-200 hover:text-red-500 hover:bg-red-50 rounded-2xl opacity-0 group-hover/msg:opacity-100 transition-all shrink-0 self-center"
                                                            >
                                                                <Trash2 size={20} />
                                                            </button>
                                                        </div>
                                                    ))}
                                                </div>

                                                {(notif.conversation || []).length === 0 && (
                                                    <div className="py-24 text-center bg-white/50 rounded-[2rem] border-2 border-dashed border-indigo-100/50">
                                                        <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-6">
                                                            <MessageSquare className="w-10 h-10 text-indigo-200" />
                                                        </div>
                                                        <h5 className="text-gray-400 text-base font-black uppercase tracking-[0.2em]">Belum Ada Chat</h5>
                                                        <p className="text-xs text-gray-300 mt-2 max-w-[250px] mx-auto font-medium">Mulai buat percakapan dengan menekan tombol Tambah Balon Chat di atas.</p>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    ))}
                </div>

                {localNotifications.length === 0 && (
                    <div className="py-20 text-center bg-gray-50">
                        <Bell className="w-16 h-16 text-gray-200 mx-auto mb-4 opacity-50" />
                        <h3 className="text-gray-400 font-black uppercase tracking-widest text-sm">Belum ada notifikasi</h3>
                        <p className="text-gray-300 text-xs mt-2">Buat notifikasi pertama Anda untuk menghidupkan Dynamic Island.</p>
                        <button
                            onClick={handleAdd}
                            className="mt-6 px-6 py-2.5 bg-indigo-600 text-white rounded-xl text-xs font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
                        >
                            Tambah Sekarang
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Type, GripHorizontal, Palette, Pin, Star, CheckSquare } from 'lucide-react';
import { useToast } from '@/contexts/ToastContext';
import { NoteData } from '@/app/about/_components/os/StickyNoteItem';
import { useAdminAuth } from '@/hooks/useAdminAuth';

const COLORS = [
    '#fef08a', // Yellow
    '#bfdbfe', // Blue
    '#bbf7d0', // Green
    '#fbcfe8', // Pink
    '#f5f5f4', // White
    '#ddd6fe', // Purple
];

interface StickyNotesManagerProps {
    onUpdate?: (data: any) => void; // Optional if we want parent to handle save, but this component can self-manage
}

export default function StickyNotesManager({ }: StickyNotesManagerProps) {
    const [notes, setNotes] = useState<NoteData[]>([]);
    const [loading, setLoading] = useState(true);
    const { showSuccess, showError } = useToast();
    const [saving, setSaving] = useState(false);
    const { csrfToken } = useAdminAuth();

    useEffect(() => {
        loadNotes();
    }, []);

    const loadNotes = async () => {
        try {
            setLoading(true);
            const response = await fetch('/api/sticky-notes');
            const data = await response.json();
            // Data might be array directly or { notes: [] } depending on API. 
            // Checking route.ts line 8: return NextResponse.json(data); 
            // Assuming service.getNotes() returns the array.
            setNotes(Array.isArray(data) ? data : []);
        } catch (err) {
            showError('Gagal memuat catatan tempel.');
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        try {
            setSaving(true);
            const response = await fetch('/api/sticky-notes', {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'x-csrf-token': csrfToken
                },
                credentials: 'include',
                body: JSON.stringify(notes)
            });

            if (response.ok) {
                showSuccess('Catatan tempel berhasil disimpan.');
            } else {
                showError('Gagal menyimpan catatan.');
            }
        } catch (err) {
            showError('Gagal menyimpan catatan.');
        } finally {
            setSaving(false);
        }
    };

    const handleAddNote = () => {
        const newNote: NoteData = {
            id: crypto.randomUUID(),
            text: 'Catatan Baru',
            date: new Date().toISOString(),
            color: COLORS[0],
            isStarred: false,
            isDeleted: false,
            x: 100 + (notes.length * 20), // Cascade position
            y: 100 + (notes.length * 20),
            width: 280,
            height: 280,
            zIndex: 100,
            fontFamily: 'var(--font-caveat), sans-serif',
            fontSize: 24,
            isPinned: false
        };
        setNotes([...notes, newNote]);
    };

    const updateNote = (id: string, updates: Partial<NoteData>) => {
        setNotes(notes.map(note => note.id === id ? { ...note, ...updates } : note));
    };

    const deleteNote = (id: string) => {
        if (confirm('Apakah Anda yakin ingin menghapus catatan ini?')) {
            setNotes(notes.filter(n => n.id !== id));
        }
    };

    if (loading) return <div className="p-8 text-center text-gray-500">Memuat catatan...</div>;

    return (
        <div className="space-y-6">
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 flex items-start sm:items-center justify-between gap-4">
                <div>
                    <h3 className="font-bold text-blue-800 flex items-center gap-2">
                        <CheckSquare className="w-5 h-5" /> Kelola Catatan Tempel
                    </h3>
                    <p className="text-sm text-blue-600 mt-1">
                        Buat, edit, atau hapus catatan tempel yang muncul di desktop OS.
                    </p>
                </div>
                <div className="flex gap-2 shrink-0">
                    <button
                        onClick={handleAddNote}
                        className="flex items-center gap-2 px-4 py-2 bg-white text-blue-700 border border-blue-200 rounded-lg hover:bg-blue-50 transition-colors text-sm font-medium"
                    >
                        <Plus size={16} /> Tambah Catatan
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={saving}
                        className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm font-medium disabled:opacity-50"
                    >
                        <Save size={16} /> {saving ? 'Menyimpan...' : 'Simpan Perubahan'}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-[repeat(auto-fill,minmax(280px,1fr))] gap-6">
                {notes.map((note, index) => (
                    <div key={note.id} className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden flex flex-col group hover:shadow-md transition-shadow">
                        {/* Header color strip */}
                        <div
                            className="h-3 w-full"
                            style={{ backgroundColor: note.color }}
                        />

                        <div className="p-4 flex-1 flex flex-col space-y-4">
                            {/* Controls */}
                            <div className="flex items-center justify-between border-b border-gray-100 pb-3">
                                <div className="flex items-center gap-1">
                                    {COLORS.map(c => (
                                        <button
                                            key={c}
                                            onClick={() => updateNote(note.id, { color: c })}
                                            className={`w-5 h-5 rounded-full border border-gray-200 transition-transform hover:scale-110 ${note.color === c ? 'ring-2 ring-blue-500 ring-offset-1' : ''}`}
                                            style={{ backgroundColor: c }}
                                            title="Atur Warna"
                                        />
                                    ))}
                                </div>
                                <div className="flex items-center gap-1">
                                    <button
                                        onClick={() => updateNote(note.id, { isPinned: !note.isPinned })}
                                        className={`p-1.5 rounded-md transition-colors ${note.isPinned ? 'bg-orange-100 text-orange-600' : 'text-gray-400 hover:bg-gray-100'}`}
                                        title="Sematkan Catatan"
                                    >
                                        <Pin size={14} className={note.isPinned ? "fill-current" : ""} />
                                    </button>
                                    <button
                                        onClick={() => updateNote(note.id, { isStarred: !note.isStarred })}
                                        className={`p-1.5 rounded-md transition-colors ${note.isStarred ? 'bg-yellow-100 text-yellow-600' : 'text-gray-400 hover:bg-gray-100'}`}
                                        title="Bintang"
                                    >
                                        <Star size={14} className={note.isStarred ? "fill-current" : ""} />
                                    </button>
                                </div>
                            </div>

                            {/* Content Editor */}
                            <div>
                                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Content (HTML Supported)</label>
                                <textarea
                                    value={note.text}
                                    onChange={(e) => updateNote(note.id, { text: e.target.value })}
                                    className="w-full h-40 p-3 bg-gray-50 border border-gray-200 rounded-lg text-sm text-gray-700 focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none font-mono"
                                    placeholder="Enter note content..."
                                />
                            </div>

                            {/* Meta Info */}
                            <div className="flex items-center justify-between pt-2">
                                <span className="text-xs text-gray-400 bg-gray-100 px-2 py-1 rounded inline-block">
                                    ID: {note.id.slice(0, 8)}
                                </span>
                                <div className="flex items-center gap-3">
                                    <div className="flex items-center gap-2 text-xs text-gray-500 bg-gray-100 px-2 py-1 rounded">
                                        <span title="X Position">x: {Math.round(note.x || 0)}</span>
                                        <span title="Y Position">y: {Math.round(note.y || 0)}</span>
                                    </div>
                                    <button
                                        onClick={() => deleteNote(note.id)}
                                        className="text-red-500 hover:text-red-700 text-xs font-medium px-2 py-1 hover:bg-red-50 rounded transition-colors"
                                    >
                                        Hapus
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}

                {notes.length === 0 && (
                    <div className="col-span-full py-12 text-center border-2 border-dashed border-gray-200 rounded-xl bg-gray-50">
                        <CheckSquare className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                        <h3 className="text-gray-500 font-medium">Tidak ada catatan tempel ditemukan</h3>
                        <p className="text-gray-400 text-sm mt-1">Klik &quot;Tambah Catatan&quot; untuk membuat yang pertama.</p>
                    </div>
                )}
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { Plus, Check, Trash2 } from 'lucide-react';
import AdminFileUpload from '@/app/admin/components/AdminFileUpload';
import { WallpaperConfig, Wallpaper } from '@/types/about';

interface WallpaperManagerProps {
    data?: WallpaperConfig;
    onUpdate: (data: WallpaperConfig) => void;
}

const DEFAULT_WALLPAPERS = [
    { id: 'default', url: 'https://images.unsplash.com/photo-1550684848-fac1c5b4e853?q=80&w=2070', name: 'Cyberpunk' },
    { id: 'minimal', url: 'https://images.unsplash.com/photo-1493246507139-91e8fad9978e?q=80&w=2070', name: 'Alps' },
];

export default function WallpaperManager({ data, onUpdate }: WallpaperManagerProps) {
    const [wallpapers, setWallpapers] = useState<Wallpaper[]>(DEFAULT_WALLPAPERS);
    const [activeId, setActiveId] = useState<string>('default');

    // Sync state with props in render
    const [lastData, setLastData] = useState(data);
    if (data && data !== lastData) {
        if (data.collection && data.collection.length > 0) {
            setWallpapers(data.collection);
            setActiveId(data.activeWallpaperId || 'default');
        }
        setLastData(data);
    }

    const handleUpload = (urls: string[]) => {
        if (!urls || urls.length === 0) return;

        const newWallpapers: Wallpaper[] = urls.map(url => ({
            id: `w-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            url: url,
            name: 'Custom Wallpaper'
        }));

        const newCollection = [...wallpapers, ...newWallpapers];
        setWallpapers(newCollection);
        // Auto-select the first new wallpaper
        const newActiveId = newWallpapers[0].id;
        setActiveId(newActiveId);

        onUpdate({
            activeWallpaperId: newActiveId,
            collection: newCollection,
            blur: data?.blur
        });
    };

    const handleDelete = (id: string) => {
        const newCollection = wallpapers.filter(w => w.id !== id);
        setWallpapers(newCollection);
        // If active was deleted, reset to first
        let newActive = activeId;
        if (activeId === id) {
            newActive = newCollection[0]?.id || 'default';
            setActiveId(newActive);
        }
        onUpdate({
            activeWallpaperId: newActive,
            collection: newCollection,
            blur: data?.blur
        });
    };

    const handleSetActive = (id: string) => {
        setActiveId(id);
        onUpdate({
            activeWallpaperId: id,
            collection: wallpapers,
            blur: data?.blur
        });
    };

    return (
        <div className="space-y-6">
            <div>
                <h3 className="text-lg font-medium text-gray-900 mb-2">Desktop Wallpaper</h3>
                <p className="text-sm text-gray-600 mb-6">
                    Pilih wallpaper utama sistem. Klik untuk menerapkan (Auto-Save).
                </p>

                <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-6">
                    <div className="flex items-center justify-between mb-2">
                        <label className="block text-sm font-medium text-gray-700">
                            Blur Intensity (0-20px)
                        </label>
                        <span className="text-sm px-2 py-1 bg-white rounded border border-gray-200 text-gray-600 font-mono">
                            {data?.blur || 0}px
                        </span>
                    </div>
                    <input
                        type="range"
                        min="0"
                        max="20"
                        step="1"
                        value={data?.blur || 0}
                        onChange={(e) => onUpdate({ ...data!, collection: wallpapers, activeWallpaperId: activeId, blur: parseInt(e.target.value) })}
                        className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                    />
                    <p className="text-xs text-gray-500 mt-2">
                        Geser untuk mengatur tingkat keburaman wallpaper desktop. 0 = Tajam.
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Active Wallpaper Hero (Optional Visual Emphasis) */}

                    {wallpapers.map(wp => {
                        const isActive = activeId === wp.id;
                        return (
                            <div
                                key={wp.id}
                                onClick={() => handleSetActive(wp.id)}
                                className={`
                                    group relative aspect-video rounded-2xl overflow-hidden cursor-pointer transition-all duration-300
                                    ${isActive
                                        ? 'ring-4 ring-blue-500 shadow-2xl shadow-blue-500/20 scale-[1.02]'
                                        : 'ring-1 ring-gray-200 hover:shadow-xl hover:-translate-y-1'
                                    }
                                `}
                            >
                                <img src={wp.url} alt={wp.name} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" />

                                {/* Active Badge */}
                                <div className={`absolute top-4 right-4 bg-blue-500 text-white p-2 rounded-full shadow-lg transition-transform duration-300 ${isActive ? 'scale-100' : 'scale-0'}`}>
                                    <Check size={16} strokeWidth={3} />
                                </div>

                                {/* Overlay & Info */}
                                <div className={`absolute inset-0 bg-gradient-to-t from-black/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-6 ${isActive ? 'opacity-100' : ''}`}>
                                    <p className="text-white font-medium text-lg drop-shadow-md transform translate-y-2 group-hover:translate-y-0 transition-transform">
                                        {isActive ? 'Active Wallpaper' : wp.name || 'Wallpaper'}
                                    </p>
                                    <span className="text-[10px] text-white/80 font-mono mt-1 uppercase tracking-widest">
                                        {isActive ? 'Applied' : 'Click to Apply'}
                                    </span>
                                </div>

                                {/* Delete Action */}
                                {wp.id !== 'default' && wp.id !== 'minimal' && (
                                    <button
                                        onClick={(e) => { e.stopPropagation(); handleDelete(wp.id); }}
                                        className="absolute top-4 left-4 bg-white/10 backdrop-blur-md text-white hover:bg-red-500 hover:text-white p-2 rounded-full opacity-0 group-hover:opacity-100 transition-all hover:scale-110"
                                        title="Delete Wallpaper"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                )}
                            </div>
                        );
                    })}

                    {/* Clean Upload Area */}
                    <div className="relative aspect-video rounded-2xl border-3 border-dashed border-gray-200 hover:border-blue-400 bg-gray-50/50 hover:bg-blue-50/10 flex flex-col items-center justify-center transition-all group cursor-pointer gap-4">
                        <div className="p-4 bg-white rounded-full shadow-sm group-hover:scale-110 transition-transform text-blue-500">
                            <Plus size={32} />
                        </div>
                        <div className="text-center">
                            <h4 className="font-semibold text-gray-700">Upload New</h4>
                            <p className="text-xs text-gray-400 mt-1">1920x1080 or higher rec.</p>
                        </div>
                        <div className='absolute inset-0 opacity-0 cursor-pointer overflow-hidden'>
                            <AdminFileUpload
                                folder="wallpapers"
                                onUpload={handleUpload}
                            />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useRef, useCallback } from 'react';
import { useToast } from '@/contexts/ToastContext';
// FFmpeg imports removed from top-level to improve bundle size
import { Loader2, CheckCircle2 } from 'lucide-react';
import { useAdminAuth } from '@/hooks/useAdminAuth';


interface AdminFileUploadProps {
  onUpload: (urls: string[]) => void;
  accept?: string;
  multiple?: boolean;
  maxFiles?: number;
  maxSize?: number; // in MB
  className?: string;
  disabled?: boolean;
  folder?: string;        // 'temp', 'comparisons', or default 'projects'
  customFilename?: string; // Optional custom filename (without extension)
}

export default function AdminFileUpload({
  onUpload,
  accept = 'image/*,video/*',
  multiple = true,
  maxFiles = 10,
  maxSize = 10,
  className = '',
  disabled = false,
  enableCrop = false,
  enableVideoTrim = false,
  autoUpload = true,
  onFileSelect,
  folder,
  customFilename
}: AdminFileUploadProps & { enableCrop?: boolean; enableVideoTrim?: boolean; autoUpload?: boolean; onFileSelect?: (file: File) => void }) {
  const [isDragOver, setIsDragOver] = useState(false);
  const [status, setStatus] = useState<string>('');
  const [progress, setProgress] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { showSuccess: success, showError, showWarning } = useToast();
  const { csrfToken } = useAdminAuth();

  // Cropping & Trimming State
  const [activeCrop, setActiveCrop] = useState<{ src: string; file: File } | null>(null);
  const [activeTrim, setActiveTrim] = useState<{ file: File } | null>(null);

  // FFmpeg Ref
  const ffmpegRef = useRef<any>(null);

  const validateFile = useCallback((file: File): string | null => {
    // limit video size to maxSize as well (default 10MB, but can be higher)
    // Caller should pass appropriate maxSize (e.g. 200) for video contexts
    const limit = maxSize;

    if (file.size > limit * 1024 * 1024) {
      return `File ${file.name} is too large. Max size is ${limit}MB.`;
    }

    const acceptedTypes = accept.split(',').map(type => type.trim());
    const fileType = file.type;
    const fileExtension = '.' + file.name.split('.').pop()?.toLowerCase();

    const isValidType = acceptedTypes.some(type => {
      if (type.endsWith('/*')) {
        const baseType = type.split('/')[0];
        return fileType.startsWith(baseType + '/');
      }
      return fileType === type || fileExtension === type;
    });

    if (!isValidType) {
      return `File ${file.name} is not a supported format.`;
    }

    return null;
  }, [accept, maxSize]);

  const loadFFmpeg = async () => {
    if (ffmpegRef.current) return ffmpegRef.current;
    setStatus('Loading Compression Core...');

    // Dynamic import to save ~500KB from initial bundle
    const { FFmpeg } = await import('@ffmpeg/ffmpeg');
    const { toBlobURL } = await import('@ffmpeg/util');

    const ffmpeg = new FFmpeg();
    try {
      const baseURL = window.location.origin + '/ffmpeg';
      await ffmpeg.load({
        coreURL: await toBlobURL(`${baseURL}/ffmpeg-core.js`, 'text/javascript'),
        wasmURL: await toBlobURL(`${baseURL}/ffmpeg-core.wasm`, 'application/wasm'),
      });
    } catch (e) {
      throw new Error('Compression engine failed to load.');
    }
    ffmpegRef.current = ffmpeg;
    return ffmpeg;
  };

  const compressVideoClient = async (
    file: File,
    onProgress: (p: number) => void,
    trimOptions?: { start: number; end: number; crop?: { x: number; y: number; width: number; height: number } }
  ): Promise<File> => {
    setStatus('Initializing Compressor...');
    const ffmpeg = await loadFFmpeg();
    setStatus('Compressing Video (Wait)...');

    const inputName = 'input.mp4';
    const outputName = 'output.mp4';
    const startTime = Date.now();

    const { fetchFile } = await import('@ffmpeg/util');
    await ffmpeg.writeFile(inputName, await fetchFile(file));

    ffmpeg.on('progress', ({ progress }: { progress: number }) => {
      const percent = Math.round(progress * 100);
      onProgress(percent);
      if (progress > 0) {
        const elapsed = (Date.now() - startTime) / 1000;
        const estimatedTotal = elapsed / progress;
        const remaining = Math.round(estimatedTotal - elapsed);
        setStatus(`Compressing Video (${percent}%) - ~${remaining}s remaining...`);
      } else {
        setStatus(`Compressing Video (${percent}%)...`);
      }
    });

    const ffmpegArgs: string[] = [];

    // Trim (Fast Seek)
    if (trimOptions) {
      ffmpegArgs.push('-ss', trimOptions.start.toString());
      ffmpegArgs.push('-to', trimOptions.end.toString());
    }

    ffmpegArgs.push('-i', inputName);

    // Filters (Crop + Scale)
    const filters: string[] = [];

    if (trimOptions?.crop) {
      const { width, height, x, y } = trimOptions.crop;
      // Ensure even dimensions
      const w = Math.round(width / 2) * 2;
      const h = Math.round(height / 2) * 2;
      const px = Math.round(x / 2) * 2;
      const py = Math.round(y / 2) * 2;
      filters.push(`crop=${w}:${h}:${px}:${py}`);
    }

    // Scale logic: Scale to 720p (short side) if needed
    // Only scale if not already cropped small
    filters.push("scale='if(gt(iw,ih),-2,720)':'if(gt(iw,ih),720,-2)'");

    ffmpegArgs.push('-vf', filters.join(','));

    ffmpegArgs.push('-c:v', 'libx264');
    ffmpegArgs.push('-crf', '23');
    ffmpegArgs.push('-preset', 'fast');
    ffmpegArgs.push('-an');
    ffmpegArgs.push('-movflags', '+faststart');
    ffmpegArgs.push(outputName);

    await ffmpeg.exec(ffmpegArgs);

    const data = await ffmpeg.readFile(outputName);
    const blob = new Blob([data as any], { type: 'video/mp4' });
    return new File([blob], file.name, { type: 'video/mp4' });
  };

  const uploadToGitHub = useCallback(async (file: File): Promise<{ url: string; publicPath?: string; warning?: string }> => {
    setStatus('Uploading to GitHub...');
    const formData = new FormData();
    formData.append('file', file);

    // Construct Query Params
    const params = new URLSearchParams();
    if (folder) params.append('folder', folder);
    if (customFilename) params.append('filename', customFilename);

    const response = await fetch(`/api/upload/github?${params.toString()}`, {
      method: 'POST',
      headers: {
        'x-csrf-token': csrfToken
      },
      credentials: 'include',
      body: formData,
    });
    if (!response.ok) {
      const errorText = await response.text();
      try {
        const errorJson = JSON.parse(errorText);
        throw new Error(errorJson.error || 'GitHub upload failed');
      } catch {
        throw new Error(errorText || 'GitHub upload failed');
      }
    }
    const data = await response.json();
    return { url: data.url, publicPath: data.publicPath, warning: data.warning };
  }, [folder, customFilename, csrfToken]); // Add folder/filename and csrfToken to dependencies

  const compressImageServer = useCallback(async (filePath: string): Promise<{ success: boolean; stats?: any; newPath?: string }> => {
    try {
      setStatus('Optimizing Image (Server)...');
      const response = await fetch('/api/admin/compress', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrfToken
        },
        credentials: 'include',
        body: JSON.stringify({ filePath }),
      });
      if (!response.ok) {
        return { success: false };
      }
      const data = await response.json();
      return { success: true, stats: data, newPath: data.newPath };
    } catch (e) {
      return { success: false };
    }
  }, [csrfToken]);

  const executeUpload = useCallback(async (files: File[], trimOptions?: { start: number; end: number; crop?: any }) => {
    setStatus('starting');
    setProgress(0);

    try {
      const uploadPromises = files.map(async (file, index) => {
        let fileToUpload = file;

        // VIDEO COMPRESSION / TRIM
        if (file.type.startsWith('video/')) {
          try {
            const originalSize = file.size;
            // setProgress(0); // Optional: reset for individual?
            fileToUpload = await compressVideoClient(file, (p) => setProgress(p), trimOptions);
            const newSize = fileToUpload.size;
            success(`Video Processed! ${(originalSize / 1024 / 1024).toFixed(2)}MB -> ${(newSize / 1024 / 1024).toFixed(2)}MB`);
          } catch (e) {
            console.error('Client compression failed, falling back to original', e);
            showWarning('Compression engine offline. Uploading original file...');
          }
        }

        // DEFERRED UPLOAD MODE
        if (autoUpload === false && onFileSelect) {
          onFileSelect(fileToUpload);
          // We return a fake URL-like string or just empty, 
          // because the parent ProjectForm handles the Blob logic now.
          // Or we can return a Blob URL so it renders in the UI immediately without callback complexity?
          // Actually, validateFile logic expects onUpload to callback with URLs?
          // AdminFileUploadProps calls onUpload(urls).
          // If we are in manual mode, maybe we call onUpload with a Blob URL?
          // Yes, let's create a Blob URL so the parent (ProjectMediaUpload) can display it immediately.
          const blobUrl = URL.createObjectURL(fileToUpload);
          return blobUrl;
        }

        // IMMEDIATE UPLOAD MODE
        const { url, publicPath, warning } = await uploadToGitHub(fileToUpload);
        if (warning) {
          showWarning(warning);
        }
        setProgress(((index + 1) / files.length) * 100);
        let finalUrl = url;

        const isImageFile = file.type.startsWith('image/') || file.name.toLowerCase().endsWith('.icns');

        if (isImageFile && publicPath) {
          const { success: compSuccess, stats, newPath } = await compressImageServer(publicPath);
          if (compSuccess && stats) {
            success(`${file.name} Optimized! (${stats.originalSize} -> ${stats.newSize}). Saved ${stats.saved}`);
            if (newPath && newPath !== publicPath) {
              const extOld = '.' + file.name.split('.').pop()?.toLowerCase();
              if (finalUrl.includes(extOld) && newPath.endsWith('.webp')) {
                finalUrl = finalUrl.replace(extOld, '.webp');
              }
            }
          }
        }
        return finalUrl;
      });

      const results = await Promise.all(uploadPromises);

      // If deferred mode, we might pass the blobUrls so ProjectMediaUpload can show preview
      // But we also called onFileSelect(file) above.
      // onUpload(results) might be confusing if results are blob URLs.
      // But ProjectMediaUpload displays "cover" which is usually a string.
      // So blob URL is fine for preview!
      onUpload(results);

      if (autoUpload !== false) {
        success('All files processed successfully.');
      }

      // UX Improvement: Show Success State
      setStatus('Upload Complete!');
      setProgress(100);

      // Wait 2 seconds before resetting
      await new Promise(resolve => setTimeout(resolve, 2000));

    } catch (err: any) {
      console.error(err);
      showError(`Process failed: ${err.message || 'Unknown error'}`);
    } finally {
      setStatus('');
      setProgress(0);
    }
  }, [uploadToGitHub, compressImageServer, compressVideoClient, onUpload, success, showError, showWarning, autoUpload, onFileSelect]);

  const handleFiles = useCallback(async (files: FileList) => {
    if (disabled) return;
    const fileArray = Array.from(files);

    if (fileArray.length > maxFiles) {
      showError(`Too many files. Maximum ${maxFiles} files allowed`);
      return;
    }

    const validationErrors: string[] = [];
    fileArray.forEach(file => {
      const error = validateFile(file);
      if (error) validationErrors.push(error);
    });

    if (validationErrors.length > 0) {
      showError(`Invalid files: ${validationErrors.join(', ')}`);
      return;
    }

    if (enableCrop && fileArray.length === 1 && fileArray[0].type.startsWith('image/')) {
      const file = fileArray[0];
      const reader = new FileReader();
      reader.onload = () => {
        setActiveCrop({ src: reader.result as string, file });
      };
      reader.readAsDataURL(file);
      return;
    }

    if (enableVideoTrim && fileArray.length === 1 && fileArray[0].type.startsWith('video/')) {
      const file = fileArray[0];
      setActiveTrim({ file });
      return;
    }

    executeUpload(fileArray);

  }, [disabled, maxFiles, validateFile, executeUpload, enableCrop, enableVideoTrim, showError]);

  const handleCropComplete = async (croppedBlob: Blob) => {
    if (!activeCrop) return;
    const croppedFile = new File([croppedBlob], activeCrop.file.name, {
      type: activeCrop.file.type,
      lastModified: Date.now(),
    });
    setActiveCrop(null);
    executeUpload([croppedFile]);
  };
  const handleCropCancel = () => { setActiveCrop(null); };

  const handleTrimConfirm = (start: number, end: number, crop?: any) => {
    if (!activeTrim) return;
    const file = activeTrim.file;
    setActiveTrim(null);
    executeUpload([file], { start, end, crop });
  };
  const handleTrimCancel = () => { setActiveTrim(null); };

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault(); if (!disabled) setIsDragOver(true);
  }, [disabled]);
  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault(); setIsDragOver(false);
  }, []);
  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault(); setIsDragOver(false);
    if (!disabled && e.dataTransfer.files.length > 0) handleFiles(e.dataTransfer.files);
  }, [disabled, handleFiles]);
  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) handleFiles(e.target.files);
  }, [handleFiles]);
  const handleClick = useCallback(() => {
    if (!disabled && fileInputRef.current) fileInputRef.current.click();
  }, [disabled]);

  return (
    <>
      {activeCrop && (
        <ImageCropperWrapper
          src={activeCrop.src}
          onConfirm={handleCropComplete}
          onCancel={handleCropCancel}
        />
      )}

      {activeTrim && (
        <VideoTrimmerWrapper
          file={activeTrim.file}
          onConfirm={handleTrimConfirm}
          onCancel={handleTrimCancel}
        />
      )}

      <div className={`w-full ${className}`}>
        <div
          className={`
          relative border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-colors
          ${isDragOver
              ? 'border-blue-400 bg-blue-50'
              : 'border-gray-300 hover:border-gray-400'
            }
          ${disabled
              ? 'opacity-50 cursor-not-allowed'
              : 'hover:bg-gray-50'
            }
        `}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={handleClick}
          role="button"
          tabIndex={disabled ? -1 : 0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handleClick(); }
          }}
          aria-label="File upload area"
        >
          <input ref={fileInputRef} type="file" accept={accept} multiple={multiple} onChange={handleFileInput} className="hidden" disabled={disabled} />

          {status ? (
            <div className="space-y-4 w-full max-w-md mx-auto" aria-live="polite">
              <div className="flex flex-col items-center justify-center space-y-3">
                <div className="relative">
                  {status === 'Upload Complete!' ? (
                    <div className="relative bg-white p-3 rounded-2xl shadow-sm border border-green-100 animate-in zoom-in duration-300">
                      <CheckCircle2 className="w-8 h-8 text-green-600" />
                    </div>
                  ) : (
                    <>
                      <div className="absolute inset-0 bg-violet-500 blur-xl opacity-20 rounded-full animate-pulse"></div>
                      <div className="relative bg-white p-3 rounded-2xl shadow-sm border border-violet-100">
                        <Loader2 className="w-8 h-8 text-violet-600 animate-spin" />
                      </div>
                    </>
                  )}
                </div>

                <div className="space-y-1 text-center">
                  <p className={`text-sm font-semibold ${status === 'Upload Complete!' ? 'text-green-600' : 'text-gray-900'}`}>{status}</p>
                  <p className="text-xs text-gray-500 font-mono">{progress}% Complete</p>
                </div>

                <div className="w-full bg-gray-100 rounded-full h-1.5 overflow-hidden">
                  <div
                    className="bg-gradient-to-r from-violet-500 to-fuchsia-500 h-full rounded-full transition-all duration-300 ease-out shadow-[0_0_10px_rgba(139,92,246,0.3)]"
                    style={{ width: `${progress}%` }}
                  ></div>
                </div>
              </div>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="mx-auto h-12 w-12 text-gray-400">
                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                </svg>
              </div>
              <div className="space-y-1">
                <p className="text-sm font-medium text-gray-900">
                  {isDragOver ? 'Drop files here' : 'Click to upload or drag and drop'}
                </p>
                <p className="text-xs text-gray-500">
                  {accept.includes('image') && accept.includes('video') ? 'Video (up to 100MB, auto-compressed) / Images' : 'Files up to 10MB'}
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </>
  );
}

// Wrappers for Lazy Loading
import ImageCropper from '@/components/admin/ImageCropper';
import VideoTrimmer from '@/components/admin/VideoTrimmer';

function ImageCropperWrapper({ src, onConfirm, onCancel }: { src: string, onConfirm: (b: Blob) => void, onCancel: () => void }) {
  return <ImageCropper imageSrc={src} onCropComplete={onConfirm} onCancel={onCancel} />;
}

function VideoTrimmerWrapper({ file, onConfirm, onCancel }: { file: File, onConfirm: (s: number, e: number, c?: any) => void, onCancel: () => void }) {
  return <VideoTrimmer file={file} onConfirm={onConfirm} onCancel={onCancel} />;
}

'use client';

import { useState, useEffect } from 'react';
import Image from 'next/image';
import { ExperienceData, WorkExperience } from '@/types/experience';
import AdminButton from '../components/AdminButton';
import AdminLayout from '../components/AdminLayout';
import { useToast } from '@/contexts/ToastContext';
import { BriefcaseBusiness, Pencil, Save, X, Plus, Trash2 } from 'lucide-react';
import StatusToggle from '../components/StatusToggle';
import { useAdminAuth } from '@/hooks/useAdminAuth';

export default function AdminExperienceClient() {
  const [experienceData, setExperienceData] = useState<ExperienceData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [editingStats, setEditingStats] = useState(false);
  const { csrfToken } = useAdminAuth();

  // Work Experience Edit State
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [workFormData, setWorkFormData] = useState<Partial<WorkExperience>>({});

  // Stats Form Data
  const [statsFormData, setStatsFormData] = useState<Partial<ExperienceData['statistics']>>({});

  const { showSuccess, showError } = useToast();

  const loadExperienceData = async () => {
    try {
      const response = await fetch('/api/experience');
      const data: ExperienceData = await response.json();
      setExperienceData(data);
      setError(null);
    } catch (error) {
      console.error('Error loading experience data:', error);
      setError('Failed to load experience data');
      showError('Failed to load experience data.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadExperienceData();
  }, []);

  // --- Statistics Handlers ---

  const handleEditStats = () => {
    if (!experienceData) return;
    setStatsFormData({ ...experienceData.statistics });
    setEditingStats(true);
  };

  const handleCancelStats = () => {
    setEditingStats(false);
    setStatsFormData({});
  };

  const handleSaveStats = async () => {
    if (!experienceData) return;
    try {
      const response = await fetch('/api/experience', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrfToken
        },
        credentials: 'include',
        body: JSON.stringify({
          statistics: { ...experienceData.statistics, ...statsFormData }
        })
      });

      if (response.ok) {
        setEditingStats(false);
        await loadExperienceData();
        showSuccess('Statistics updated successfully.');
      } else {
        const errorData = await response.json().catch(() => ({}));
        showError(`Failed to update statistics: ${errorData.error || response.statusText} (${response.status})`);
      }
    } catch (error) {
      showError(`Failed to update statistics: ${error instanceof Error ? error.message : 'Network error'}`);
    }
  };

  // --- Work Experience Handlers ---

  const handleAddNew = () => {
    setWorkFormData({
      position: '',
      company: '',
      year: '',
      duration: '',
      description: [],
      imageUrl: '',
      isActive: true
    });
    setIsAddingNew(true);
    setEditingIndex(null);
  };

  const handleEditItem = (index: number) => {
    if (!experienceData) return;
    const item = experienceData.workExperience[index];
    setWorkFormData({ ...item });
    setEditingIndex(index);
    setIsAddingNew(false);
  };

  const handleCancelWorkEdit = () => {
    setIsAddingNew(false);
    setEditingIndex(null);
    setWorkFormData({});
  };

  const handleSaveWorkItem = async () => {
    if (!experienceData) return;

    // Construct new array
    let updatedList = [...experienceData.workExperience];

    const newItem = {
      position: workFormData.position || '',
      company: workFormData.company || '',
      year: workFormData.year || '',
      duration: workFormData.duration || '',
      description: workFormData.description || [],
      imageUrl: workFormData.imageUrl || '',
      isActive: workFormData.isActive !== undefined ? workFormData.isActive : true,
    };

    if (isAddingNew) {
      updatedList.push(newItem);
    } else if (editingIndex !== null) {
      updatedList[editingIndex] = newItem;
    } else {
      return;
    }

    try {
      const response = await fetch('/api/experience', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrfToken
        },
        credentials: 'include',
        body: JSON.stringify({
          workExperience: updatedList
        })
      });

      if (response.ok) {
        handleCancelWorkEdit();
        await loadExperienceData();
        showSuccess(isAddingNew ? 'New experience added.' : 'Experience updated.');
      } else {
        const errorData = await response.json().catch(() => ({}));
        showError(`Failed to save experience: ${errorData.error || response.statusText} (${response.status})`);
      }
    } catch (error) {
      showError(`Failed to save experience: ${error instanceof Error ? error.message : 'Network error'}`);
    }
  };

  const handleDeleteItem = async (index: number) => {
    if (!experienceData || !confirm('Are you sure you want to delete this experience entry?')) return;

    const updatedList = experienceData.workExperience.filter((_, i) => i !== index);

    try {
      const response = await fetch('/api/experience', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrfToken
        },
        credentials: 'include',
        body: JSON.stringify({
          workExperience: updatedList
        })
      });

      if (response.ok) {
        await loadExperienceData();
        showSuccess('Experience deleted.');
      } else {
        const errorData = await response.json().catch(() => ({}));
        showError(`Failed to delete experience: ${errorData.error || response.statusText} (${response.status})`);
      }
    } catch (error) {
      showError(`Failed to delete experience: ${error instanceof Error ? error.message : 'Network error'}`);
    }
  };

  // --- Render ---

  if (loading && !experienceData) {
    return (
      <AdminLayout
        title="Experience Management"
        subtitle="Manage experience statistics and work history"
        breadcrumbs={[{ label: 'Dashboard', href: '/admin' }, { label: 'Experience' }]}
        titleIcon={<BriefcaseBusiness className="h-5 w-5" aria-hidden />}
        titleAccent="bg-emerald-50 text-emerald-700"
      >
        <div className="flex items-center justify-center py-8">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-emerald-600"></div>
        </div>
      </AdminLayout>
    );
  }

  if (!experienceData) {
    return (
      <AdminLayout
        title="Experience Management"
        subtitle="Manage experience statistics and work history"
        breadcrumbs={[{ label: 'Dashboard', href: '/admin' }, { label: 'Experience' }]}
        titleIcon={<BriefcaseBusiness className="h-5 w-5" aria-hidden />}
        titleAccent="bg-emerald-50 text-emerald-700"
      >
        <div className="flex items-center justify-center py-8">
          <p className="text-red-600">Failed to load experience data</p>
        </div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout
      title="Experience Management"
      subtitle="Manage experience statistics and work history"
      breadcrumbs={[{ label: 'Dashboard', href: '/admin' }, { label: 'Experience' }]}
      titleIcon={<BriefcaseBusiness className="h-5 w-5" aria-hidden />}
      titleAccent="bg-emerald-50 text-emerald-700"
    >
      <div className="space-y-8">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold text-gray-900">Overview</h2>
          <div className="text-sm text-gray-500">
            Last updated: {experienceData.lastUpdated ? new Date(experienceData.lastUpdated).toLocaleString() : 'Never'}
          </div>
        </div>

        {error && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg">
            {error}
          </div>
        )}

        {/* Statistics Section */}
        <section>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-9000">Global Statistics</h3>
            {!editingStats && (
              <button
                onClick={handleEditStats}
                className="flex items-center gap-1.5 text-sm font-medium text-emerald-600 hover:text-emerald-700 bg-emerald-50 hover:bg-emerald-100 px-3 py-1.5 rounded-lg transition-colors"
              >
                <Pencil className="w-4 h-4" />
                Edit Stats
              </button>
            )}
          </div>

          {editingStats ? (
            <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 shadow-sm animate-in fade-in duration-200">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Years of Experience</label>
                  <input
                    type="text"
                    value={statsFormData.years || ''}
                    onChange={(e) => setStatsFormData(prev => ({ ...prev, years: e.target.value }))}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Projects Completed</label>
                  <input
                    type="text"
                    value={statsFormData.projects || ''}
                    onChange={(e) => setStatsFormData(prev => ({ ...prev, projects: e.target.value }))}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Design Tools</label>
                  <input
                    type="text"
                    value={statsFormData.designTools || ''}
                    onChange={(e) => setStatsFormData(prev => ({ ...prev, designTools: e.target.value }))}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Client Satisfaction</label>
                  <input
                    type="text"
                    value={statsFormData.clientSatisfaction || ''}
                    onChange={(e) => setStatsFormData(prev => ({ ...prev, clientSatisfaction: e.target.value }))}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div className="col-span-1 md:col-span-2 flex justify-end gap-2 pt-2">
                  <AdminButton onClick={handleCancelStats} variant="secondary">Cancel</AdminButton>
                  <AdminButton onClick={handleSaveStats} variant="primary">Save Changes</AdminButton>
                </div>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="bg-white p-5 rounded-lg border border-gray-200 shadow-sm text-center">
                <div className="text-3xl font-bold text-emerald-600 mb-1">{experienceData.statistics.years}</div>
                <div className="text-sm font-medium text-gray-500">Years Exp.</div>
              </div>
              <div className="bg-white p-5 rounded-lg border border-gray-200 shadow-sm text-center">
                <div className="text-3xl font-bold text-emerald-600 mb-1">{experienceData.statistics.projects}</div>
                <div className="text-sm font-medium text-gray-500">Projects</div>
              </div>
              <div className="bg-white p-5 rounded-lg border border-gray-200 shadow-sm text-center">
                <div className="text-3xl font-bold text-emerald-600 mb-1">{experienceData.statistics.designTools}</div>
                <div className="text-sm font-medium text-gray-500">Design Tools</div>
              </div>
              <div className="bg-white p-5 rounded-lg border border-gray-200 shadow-sm text-center">
                <div className="text-3xl font-bold text-emerald-600 mb-1">{experienceData.statistics.clientSatisfaction}</div>
                <div className="text-sm font-medium text-gray-500">Satisfaction</div>
              </div>
            </div>
          )}
        </section>

        {/* Work Experience Section */}
        <section>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900">Work Experience History</h3>
            {!isAddingNew && editingIndex === null && (
              <button
                onClick={handleAddNew}
                className="flex items-center gap-1.5 text-sm font-medium text-blue-600 hover:text-blue-700 bg-blue-50 hover:bg-blue-100 px-3 py-1.5 rounded-lg transition-colors"
              >
                <Plus className="w-4 h-4" />
                Add New
              </button>
            )}
          </div>

          {(isAddingNew || editingIndex !== null) ? (
            <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 shadow-sm animate-in fade-in duration-200">
              <div className="flex justify-between items-center mb-4">
                <h4 className="text-md font-semibold text-gray-800">{isAddingNew ? 'Add New Position' : 'Edit Position'}</h4>
                <button onClick={handleCancelWorkEdit} className="text-gray-400 hover:text-gray-600">
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Position</label>
                  <input
                    type="text"
                    value={workFormData.position || ''}
                    onChange={(e) => setWorkFormData(prev => ({ ...prev, position: e.target.value }))}
                    className="w-full px-3 py-2 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-1 focus:ring-blue-500"
                    placeholder="e.g. Senior Designer"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Company</label>
                  <input
                    type="text"
                    value={workFormData.company || ''}
                    onChange={(e) => setWorkFormData(prev => ({ ...prev, company: e.target.value }))}
                    className="w-full px-3 py-2 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-1 focus:ring-blue-500"
                    placeholder="e.g. Tech Corp"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Year</label>
                  <input
                    type="text"
                    value={workFormData.year || ''}
                    onChange={(e) => setWorkFormData(prev => ({ ...prev, year: e.target.value }))}
                    className="w-full px-3 py-2 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-1 focus:ring-blue-500"
                    placeholder="e.g. 2020-2023"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Duration</label>
                  <input
                    type="text"
                    value={workFormData.duration || ''}
                    onChange={(e) => setWorkFormData(prev => ({ ...prev, duration: e.target.value }))}
                    className="w-full px-3 py-2 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-1 focus:ring-blue-500"
                    placeholder="e.g. 3 years"
                  />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Image URL</label>
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={workFormData.imageUrl || ''}
                      onChange={(e) => setWorkFormData(prev => ({ ...prev, imageUrl: e.target.value }))}
                      className="w-full px-3 py-2 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-1 focus:ring-blue-500"
                      placeholder="https://example.com/company-logo.png"
                    />
                  </div>
                  {workFormData.imageUrl && (
                    <div className="mt-2 flex items-center gap-3 p-2 bg-white rounded border border-gray-200 max-w-xs">
                      <div className="relative w-8 h-8 rounded overflow-hidden flex-shrink-0 bg-gray-100">
                        <Image
                          src={workFormData.imageUrl}
                          alt="Preview"
                          fill
                          className="object-cover"
                          unoptimized
                        />
                      </div>
                      <span className="text-xs text-gray-500 truncate">{workFormData.imageUrl}</span>
                    </div>
                  )}
                </div>
                <div className="md:col-span-2">
                  <label className="flex items-center space-x-2 cursor-pointer mt-2">
                    <input
                      type="checkbox"
                      checked={workFormData.isActive ?? true}
                      onChange={(e) => setWorkFormData(prev => ({ ...prev, isActive: e.target.checked }))}
                      className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                    />
                    <span className="text-sm font-medium text-gray-700">Aktifkan</span>
                  </label>
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Description (comma separated)</label>
                  <textarea
                    rows={3}
                    value={Array.isArray(workFormData.description) ? workFormData.description.join(', ') : workFormData.description || ''}
                    onChange={(e) => {
                      setWorkFormData(prev => ({
                        ...prev,
                        description: e.target.value.split(',').map(d => d.trim()).filter(d => d)
                      }));
                    }}
                    className="w-full px-3 py-2 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-1 focus:ring-blue-500"
                    placeholder="Led design team, Improved UX by 20%, etc."
                  />
                  <p className="mt-1 text-xs text-gray-500">Each comma creates a new bullet point.</p>
                </div>
              </div>

              <div className="flex justify-end gap-3 pt-6 border-t border-gray-200 mt-6">
                <AdminButton onClick={handleCancelWorkEdit} variant="secondary">Cancel</AdminButton>
                <AdminButton onClick={handleSaveWorkItem} variant="primary">{isAddingNew ? 'Add Position' : 'Update Position'}</AdminButton>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {experienceData.workExperience.map((work, index) => (
                <div key={index} className="bg-white p-5 rounded-lg border border-gray-200 shadow-sm hover:shadow-md transition-shadow flex flex-col h-full">
                  <div className="flex items-start gap-4 flex-1">
                    <div className="relative w-16 h-16 rounded-lg bg-gray-50 border border-gray-100 overflow-hidden flex-shrink-0">
                      {work.imageUrl ? (
                        <Image
                          src={work.imageUrl}
                          alt={work.company}
                          fill
                          className="object-cover"
                          sizes="64px"
                          unoptimized
                        />
                      ) : (
                        <div className="flex items-center justify-center w-full h-full text-gray-300">
                          <BriefcaseBusiness className="w-8 h-8" />
                        </div>
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <h4 className="text-lg font-bold text-gray-900 truncate">{work.position}</h4>
                      <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-gray-600 mb-2">
                        <span className="font-medium text-gray-800">{work.company}</span>
                        <span className="text-gray-300">•</span>
                        <span>{work.year}</span>
                        <span className="text-gray-300">•</span>
                        <span className="text-gray-500">{work.duration}</span>
                        <span className="text-gray-300">•</span>
                        <span className="text-gray-500">{work.duration}</span>
                      </div>
                      <ul className="list-disc list-outside pl-4 space-y-1">
                        {work.description.slice(0, 3).map((desc, i) => (
                          <li key={i} className="text-sm text-gray-600 leading-snug">{desc}</li>
                        ))}
                        {work.description.length > 3 && (
                          <li className="text-xs text-gray-400 italic">+{work.description.length - 3} more items...</li>
                        )}
                      </ul>
                    </div>
                  </div>

                  <div className="mt-4 pt-4 border-t border-gray-100 flex justify-end gap-2">
                    <StatusToggle
                      isActive={work.isActive !== false}
                      onClick={() => {
                        const updatedList = [...experienceData.workExperience];
                        updatedList[index] = { ...work, isActive: work.isActive === false ? true : false };
                        // Direct save
                        fetch('/api/experience', {
                          method: 'PUT',
                          headers: {
                            'Content-Type': 'application/json',
                            'x-csrf-token': csrfToken
                          },
                          credentials: 'include',
                          body: JSON.stringify({ workExperience: updatedList })
                        }).then(res => {
                          if (res.ok) {
                            loadExperienceData();
                            showSuccess('Experience status updated.');
                          } else {
                            showError('Failed to update status.');
                          }
                        });
                      }}
                      className="mr-auto"
                    />
                    <button
                      onClick={() => handleEditItem(index)}
                      className="p-2 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-md transition-colors"
                      title="Edit"
                    >
                      <Pencil className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDeleteItem(index)}
                      className="p-2 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors"
                      title="Delete"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}
              {experienceData.workExperience.length === 0 && (
                <div className="col-span-1 lg:col-span-2 text-center py-10 bg-gray-50 rounded-lg border border-dashed border-gray-300 text-gray-500">
                  No work experience added yet.
                </div>
              )}
            </div>
          )}
        </section>
      </div >
    </AdminLayout >
  );
}

"use client";

import React, { useEffect, useState } from "react";
import Button from "@/components/ui/Button";
import { Trash2, FolderOpen, RefreshCw, Play } from "lucide-react";
import { useToast } from "@/contexts/ToastContext";
import { format } from "date-fns";

interface Sequence {
    name: string;
    frames: number;
    createdAt: string;
    path: string;
}

export default function SequenceList() {
    const { showSuccess, showError } = useToast();
    const [sequences, setSequences] = useState<Sequence[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [deletingId, setDeletingId] = useState<string | null>(null);
    const [activatingId, setActivatingId] = useState<string | null>(null);

    const handleActivate = async (name: string) => {
        setActivatingId(name);
        try {
            const res = await fetch("/api/upload/sequence", {
                method: "PATCH",
                body: JSON.stringify({ name }),
            });

            if (!res.ok) throw new Error("Activation failed");

            const data = await res.json();
            showSuccess(`Active sequence set to: ${name}`);
        } catch (error) {
            console.error(error);
            showError("Failed to activate sequence");
        } finally {
            setActivatingId(null);
        }
    };

    const fetchSequences = async () => {
        setIsLoading(true);
        try {
            const res = await fetch("/api/upload/sequence");
            if (!res.ok) throw new Error("Failed to fetch");
            const data = await res.json();

            // Map strings to dates if needed, though JSON returns strings
            setSequences(data);
        } catch (error) {
            console.error(error);
            showError("Failed to load sequences");
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchSequences();
    }, []);

    // Expose refresh method to parent if needed, or just use button
    // For now, simple auto-refresh on mount.

    const handleDelete = async (name: string) => {
        if (!confirm(`Are you sure you want to delete "${name}"? This cannot be undone.`)) return;

        setDeletingId(name);
        try {
            const res = await fetch(`/api/upload/sequence?name=${name}`, {
                method: "DELETE",
            });

            if (!res.ok) throw new Error("Delete failed");

            showSuccess("Sequence deleted");
            fetchSequences(); // Refresh list
        } catch (error) {
            showError("Failed to delete");
            console.error(error);
        } finally {
            setDeletingId(null);
        }
    };

    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between">
                <h3 className="text-lg font-semibold">Saved Sequences</h3>
                <Button
                    variant="ghost"
                    size="sm"
                    onClick={fetchSequences}
                    disabled={isLoading}
                >
                    <RefreshCw className={`w-4 h-4 mr-2 ${isLoading ? "animate-spin" : ""}`} />
                    Refresh
                </Button>
            </div>

            {sequences.length === 0 && !isLoading && (
                <div className="text-center p-8 border rounded-lg border-dashed text-muted-foreground">
                    No sequences found. Generate one above.
                </div>
            )}

            <div className="grid gap-3">
                {sequences.map((seq) => (
                    <div
                        key={seq.name}
                        className="flex items-center justify-between p-4 border rounded-lg bg-card/50 hover:bg-card transition-colors"
                    >
                        <div className="flex items-start gap-3">
                            <div className="p-2 bg-primary/10 rounded">
                                <FolderOpen className="w-5 h-5 text-primary" />
                            </div>
                            <div>
                                <h4 className="font-medium text-sm flex items-center gap-2">
                                    {seq.name}
                                    {/* Simple 'New' badge logic if created recently could go here */}
                                </h4>
                                <div className="text-xs text-muted-foreground mt-1 space-x-3">
                                    <span>{seq.frames} frames</span>
                                    <span>•</span>
                                    <span>{format(new Date(seq.createdAt), "MMM d, HH:mm")}</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                            <code className="hidden sm:block text-xs bg-muted px-2 py-1 rounded select-all">
                                {seq.name}
                            </code>
                            <Button
                                variant="secondary"
                                size="sm"
                                onClick={() => handleActivate(seq.name)}
                                disabled={activatingId !== null}
                            >
                                {activatingId === seq.name ? (
                                    <span className="animate-pulse">Active...</span>
                                ) : (
                                    <span className="flex items-center">
                                        <Play className="w-3 h-3 mr-1 fill-current" />
                                        Use
                                    </span>
                                )}
                            </Button>

                            <Button
                                variant="secondary"
                                size="sm"
                                onClick={() => handleActivate(seq.name)}
                                disabled={activatingId !== null}
                            >
                                {activatingId === seq.name ? (
                                    <span className="animate-pulse">Active...</span>
                                ) : (
                                    <span className="flex items-center">
                                        <Play className="w-3 h-3 mr-1 fill-current" />
                                        Use
                                    </span>
                                )}
                            </Button>

                            <Button
                                variant="danger"
                                size="sm"
                                onClick={() => handleDelete(seq.name)}
                                loading={deletingId === seq.name}
                                disabled={deletingId !== null}
                            >
                                <Trash2 className="w-4 h-4" />
                            </Button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { Testimonial, TestimonialData, ChatHistoryMessage } from '@/types/testimonial';
import { Project } from '@/types/projects';
import AdminButton from '../components/AdminButton';
import AdminLayout from '../components/AdminLayout';
import { useAutoUpdate } from '@/hooks/useAutoUpdate';
import { useToast } from '@/contexts/ToastContext';
import { Quote, Pencil, Trash2, MessageSquare, Plus, User, CheckCheck, Clock, Sparkles, Wand2, Loader2, Eye, Image as ImageIcon, Link as LinkIcon } from 'lucide-react';
import StatusToggle from '../components/StatusToggle';
import { useAdminAuth } from '@/hooks/useAdminAuth';


import { getAvatarUrl, getAvatarColors } from '@/lib/avatar';

const AutoResizeTextarea = ({ value, onChange, className, placeholder }: { value: string, onChange: (e: React.ChangeEvent<HTMLTextAreaElement>) => void, className?: string, placeholder?: string }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
    }
  }, [value]);

  return (
    <textarea
      ref={textareaRef}
      value={value}
      onChange={onChange}
      className={className}
      placeholder={placeholder}
      rows={1}
    />
  );
};

export default function AdminTestimonialClient() {
  const [testimonials, setTestimonials] = useState<Testimonial[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  // AI Helper States
  const [aiTopic, setAiTopic] = useState('');
  const [aiCount, setAiCount] = useState(3);
  const [isAiGenerating, setIsAiGenerating] = useState(false);

  const [formData, setFormData] = useState<Partial<Testimonial>>({
    name: '',
    notificationText: '',
    isActive: true,
    messages: [],
    projectId: ''
  });

  // Load projects
  useEffect(() => {
    const loadProjects = async () => {
      try {
        const response = await fetch('/api/projects');
        const data = await response.json();
        setProjects(data.projects || []);
      } catch (err) {
        console.error('Error loading projects:', err);
      }
    };
    loadProjects();
  }, []);

  const { showSuccess, showError } = useToast();
  const { csrfToken } = useAdminAuth();

  // Load testimonials
  const loadTestimonials = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/testimonial');
      const data: TestimonialData = await response.json();
      setTestimonials(data.testimonials);
      setError(null);
    } catch (error) {
      console.error('Error loading testimonials:', error);
      setError('Failed to load testimonials');
      showError('Failed to load testimonials.');
    } finally {
      setLoading(false);
    }
  }, [showError]);

  const { lastUpdated, refresh } = useAutoUpdate(loadTestimonials);

  // AI Generation Logic
  const handleAiGenerate = async () => {
    if (!aiTopic) {
      showError('Masukkan topik desain dulu!');
      return;
    }

    if (!csrfToken) {
      showError('Sesi belum siap, tunggu sebentar...');
      return;
    }

    setIsAiGenerating(true);
    try {
      const response = await fetch('/api/ai/generate-testimonial', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrfToken
        },
        credentials: 'include',
        body: JSON.stringify({ topic: aiTopic, messageCount: aiCount })
      });

      if (!response.ok) throw new Error('AI Generation failed');

      const data = await response.json();
      setFormData(prev => ({
        ...prev,
        name: data.name,
        notificationText: data.notificationText,
        messages: data.messages.map((m: any, idx: number) => ({
          ...m,
          id: Date.now() + idx
        }))
      }));
      showSuccess('Konten berhasil dibuat oleh AI!');
    } catch (err) {
      console.error(err);
      showError('Gagal generate AI. Coba lagi.');
    } finally {
      setIsAiGenerating(false);
    }
  };

  // Create testimonial
  const handleCreate = async () => {
    if (!formData.name || !formData.notificationText) return;

    try {
      const response = await fetch('/api/testimonial', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrfToken
        },
        credentials: 'include',
        body: JSON.stringify(formData)
      });

      if (response.ok) {
        setFormData({ name: '', notificationText: '', isActive: true, messages: [] });
        setAiTopic('');
        refresh();
        showSuccess('Testimonial created successfully.');
      } else {
        showError('Failed to create testimonial.');
      }
    } catch (error) {
      console.error('Error creating testimonial:', error);
      showError('Failed to create testimonial.');
    }
  };

  // Update testimonial
  const handleUpdate = async (id: number) => {
    try {
      const response = await fetch('/api/testimonial', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrfToken
        },
        credentials: 'include',
        body: JSON.stringify({ id, ...formData })
      });

      if (response.ok) {
        setEditingId(null);
        setFormData({ name: '', notificationText: '', isActive: true, messages: [] });
        refresh();
        showSuccess('Testimonial updated successfully.');
      } else {
        showError('Failed to update testimonial.');
      }
    } catch (error) {
      console.error('Error updating testimonial:', error);
      showError('Failed to update testimonial.');
    }
  };

  // Delete testimonial
  const handleDelete = async (id: number) => {
    if (!confirm('Are you sure you want to delete this testimonial?')) return;

    try {
      const response = await fetch('/api/testimonial', {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrfToken
        },
        credentials: 'include',
        body: JSON.stringify({ id })
      });

      if (response.ok) {
        refresh();
        showSuccess('Testimonial deleted successfully.');
      } else {
        showError('Failed to delete testimonial.');
      }
    } catch (error) {
      console.error('Error deleting testimonial:', error);
      showError('Failed to delete testimonial.');
    }
  };

  const handleEdit = (testimonial: Testimonial) => {
    setEditingId(testimonial.id);
    setFormData(testimonial);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCancel = () => {
    setEditingId(null);
    setFormData({ name: '', notificationText: '', isActive: true, messages: [] });
  };

  return (
    <AdminLayout
      title="Dynamic Island WA"
      subtitle="Atur simulasi notifikasi WhatsApp di Dynamic Island"
      breadcrumbs={[{ label: 'Dashboard', href: '/admin' }, { label: 'WhatsApp Notif' }]}
      titleIcon={<MessageSquare className="h-5 w-5" aria-hidden />}
      titleAccent="bg-green-50 text-green-700"
    >
      <div className="space-y-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* MAIN COLUMN: Input & AI & Live Editor */}
          <div className="lg:col-span-12 space-y-6">

            {/* AI Magic Tool Section */}
            <div className="bg-gradient-to-br from-green-50 to-emerald-50 p-6 rounded-2xl border border-green-100 shadow-sm relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:rotate-12 transition-transform">
                <Sparkles size={64} className="text-green-600" />
              </div>

              <div className="relative z-10">
                <div className="flex items-center gap-2 mb-4">
                  <div className="bg-green-600 p-1.5 rounded-lg text-white">
                    <Wand2 size={18} />
                  </div>
                  <h3 className="text-lg font-bold text-green-900">AI Magic Testimonial</h3>
                </div>

                <p className="text-sm text-green-700 mb-6 leading-relaxed">
                  Bantu buatkan testimoni natural (sopan & santai) hanya dengan satu klik.
                </p>

                <div className="flex flex-col md:flex-row gap-3">
                  <input
                    type="text"
                    value={aiTopic}
                    onChange={(e) => setAiTopic(e.target.value)}
                    className="flex-1 px-4 py-2.5 bg-white border border-green-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none text-sm"
                    placeholder="Contoh: Desain Banner Ads / Manipulasi Produk"
                  />
                  <select
                    value={aiCount}
                    onChange={(e) => setAiCount(Number(e.target.value))}
                    className="px-4 py-2.5 bg-white border border-green-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none text-sm md:w-32"
                  >
                    <option value={3}>3 Pesan</option>
                    <option value={5}>5 Pesan</option>
                    <option value={7}>7 Pesan</option>
                  </select>
                  <button
                    onClick={handleAiGenerate}
                    disabled={isAiGenerating || !aiTopic}
                    className="px-6 py-2.5 bg-green-600 text-white rounded-xl font-bold text-sm hover:bg-green-700 transition-all flex items-center justify-center gap-2 shadow-lg shadow-green-200 disabled:opacity-50"
                  >
                    {isAiGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                    Generate
                  </button>
                </div>
              </div>
            </div>

            {/* Main Form Section */}
            <div className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm space-y-6">
              <div className="flex justify-between items-center">
                <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                  <Pencil size={20} className="text-violet-600" />
                  {editingId ? 'Edit Testimonial' : 'Manual Input'}
                </h2>
                {editingId && (
                  <button onClick={handleCancel} className="text-sm text-red-500 hover:underline">Discard Changes</button>
                )}
              </div>

              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1.5">Nama Kontak</label>
                  <input
                    type="text"
                    value={formData.name || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-violet-500 outline-none transition-all"
                    placeholder="Contoh: Pak Budi (Klien)"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1.5">Pesan Notifikasi (Dynamic Island)</label>
                  <input
                    type="text"
                    value={formData.notificationText || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, notificationText: e.target.value }))}
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-violet-500 outline-none transition-all"
                    placeholder="Mas, desainnya sudah oke ya!"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1.5">Link ke Project (Opsional)</label>
                  <select
                    value={formData.projectId || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, projectId: e.target.value }))}
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-violet-500 outline-none transition-all text-sm"
                  >
                    <option value="">-- Pilih Project --</option>
                    {projects.map(p => (
                      <option key={p.id} value={p.id}>{p.title}</option>
                    ))}
                  </select>
                </div>

                {/* Message List Editor */}
                <div className="pt-4">
                  <div className="flex justify-between items-center mb-4">
                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest">Alur Percakapan</label>
                    <button
                      type="button"
                      onClick={() => {
                        const newMsg: ChatHistoryMessage = {
                          id: Date.now(),
                          text: '',
                          isMe: false,
                          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                          type: 'text'
                        };
                        setFormData(prev => ({ ...prev, messages: [...(prev.messages || []), newMsg] }));
                      }}
                      className="text-xs bg-violet-50 text-violet-600 px-3 py-1.5 rounded-lg hover:bg-violet-100 flex items-center gap-1 font-bold"
                    >
                      <Plus size={14} /> Tambah Balasan
                    </button>
                  </div>

                  <div key="chat-container-root" className="bg-[#efeae2] rounded-xl border border-green-100 overflow-hidden relative h-[500px] flex flex-col shadow-inner">
                    {/* WhatsApp Pattern Overlay - Rendered only after mount to prevent hydration mismatch */}
                    {mounted && (
                      <div
                        key="fixed-bg-pattern-vfinal"
                        className="absolute inset-0 opacity-100 pointer-events-none z-0"
                        style={{
                          backgroundImage: 'url("/assets/whatsapp-bg.png")',
                          backgroundRepeat: 'repeat',
                          backgroundSize: '400px'
                        }}
                      ></div>
                    )}

                    <div className="flex-1 overflow-y-auto p-4 space-y-3 z-10 custom-scrollbar">
                      {formData.messages?.map((msg, index) => (
                        <div key={msg.id} className={`flex ${msg.isMe ? 'justify-end' : 'justify-start'} group items-end gap-2 mb-3`}>

                          {/* Swap Button (Left for Me) */}
                          {msg.isMe && (
                            <button
                              onClick={() => {
                                const newMessages = [...(formData.messages || [])];
                                newMessages[index].isMe = !newMessages[index].isMe;
                                setFormData(prev => ({ ...prev, messages: newMessages }));
                              }}
                              className="opacity-0 group-hover:opacity-100 p-2 text-gray-400 hover:text-green-600 transition-all transform hover:scale-110"
                              title="Ubah jadi pesan Masuk"
                            >
                              <User size={16} />
                            </button>
                          )}

                          <div className={`relative max-w-[70%] rounded-lg px-2 pt-1.5 pb-1 shadow-sm text-[14.2px] 
                            ${msg.isMe ? 'bg-[#d9fdd3] rounded-tr-none' : 'bg-white rounded-tl-none'}
                          `}>
                            {/* Type Selector */}
                            <div className="flex gap-2 mb-2 border-b border-black/5 pb-1.5">
                              <button
                                onClick={() => {
                                  const newMessages = [...(formData.messages || [])];
                                  newMessages[index].type = 'text';
                                  setFormData(prev => ({ ...prev, messages: newMessages }));
                                }}
                                className={`p-1 rounded ${msg.type === 'text' || !msg.type ? 'bg-black/10' : 'hover:bg-black/5'}`}
                                title="Text Message"
                              >
                                <MessageSquare size={14} />
                              </button>
                              <button
                                onClick={() => {
                                  const newMessages = [...(formData.messages || [])];
                                  newMessages[index].type = 'project';
                                  newMessages[index].projectId = formData.projectId;
                                  setFormData(prev => ({ ...prev, messages: newMessages }));
                                }}
                                className={`p-1 rounded ${msg.type === 'project' ? 'bg-black/10' : 'hover:bg-black/5'}`}
                                title="Project Thumbnail"
                              >
                                <LinkIcon size={14} />
                              </button>
                              <button
                                onClick={() => {
                                  const newMessages = [...(formData.messages || [])];
                                  newMessages[index].type = 'image';
                                  setFormData(prev => ({ ...prev, messages: newMessages }));
                                }}
                                className={`p-1 rounded ${msg.type === 'image' ? 'bg-black/10' : 'hover:bg-black/5'}`}
                                title="Custom Image"
                              >
                                <ImageIcon size={14} />
                              </button>
                            </div>

                            {msg.type === 'project' && (
                              <div className="mb-2 p-2 bg-black/5 rounded-lg border border-black/10">
                                <span className="text-[10px] font-bold text-gray-500 uppercase block mb-1">Linked Project</span>
                                <select
                                  value={msg.projectId || ''}
                                  onChange={(e) => {
                                    const newMessages = [...(formData.messages || [])];
                                    newMessages[index].projectId = e.target.value;
                                    setFormData(prev => ({ ...prev, messages: newMessages }));
                                  }}
                                  className="w-full bg-white/50 border-none text-xs rounded p-1 outline-none"
                                >
                                  <option value="">-- Pilih --</option>
                                  {projects.map(p => (
                                    <option key={p.id} value={p.id}>{p.title}</option>
                                  ))}
                                </select>
                              </div>
                            )}

                            {msg.type === 'image' && (
                              <input
                                type="text"
                                value={msg.imageSrc || ''}
                                onChange={(e) => {
                                  const newMessages = [...(formData.messages || [])];
                                  newMessages[index].imageSrc = e.target.value;
                                  setFormData(prev => ({ ...prev, messages: newMessages }));
                                }}
                                placeholder="URL Gambar..."
                                className="w-full bg-white/50 border-none text-xs rounded p-1 outline-none mb-2"
                              />
                            )}

                            {/* Text Input */}
                            <AutoResizeTextarea
                              value={msg.text}
                              onChange={(e) => {
                                const newMessages = [...(formData.messages || [])];
                                newMessages[index].text = e.target.value;
                                setFormData(prev => ({ ...prev, messages: newMessages }));
                              }}
                              className="w-full bg-transparent border-none focus:ring-0 p-0 text-[#111b21] resize-none overflow-hidden leading-[19px] min-w-[300px]"
                              placeholder={msg.type === 'project' || msg.type === 'image' ? 'Ketik caption (opsional)...' : 'Ketik pesan...'}
                            />

                            {/* Meta & Controls */}
                            <div className="flex justify-end items-center gap-1 mt-1 select-none h-4">
                              <input
                                value={msg.time}
                                onChange={(e) => {
                                  const newMessages = [...(formData.messages || [])];
                                  newMessages[index].time = e.target.value;
                                  setFormData(prev => ({ ...prev, messages: newMessages }));
                                }}
                                className="bg-transparent text-[11px] text-[#667781] w-[35px] text-right border-none focus:ring-0 p-0 h-full"
                              />
                              {msg.isMe && (
                                <span className="text-[#53bdeb] ml-0.5">
                                  <CheckCheck size={15} strokeWidth={1.5} />
                                </span>
                              )}

                              <div className="w-[1px] h-3 bg-black/10 mx-1 opacity-0 group-hover:opacity-100 transition-opacity"></div>

                              <button
                                onClick={() => setFormData(prev => ({ ...prev, messages: prev.messages?.filter(m => m.id !== msg.id) }))}
                                className="opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-500 transition-opacity"
                                title="Hapus pesan"
                              >
                                <Trash2 size={13} />
                              </button>
                            </div>

                            {/* Triangle Tip */}
                            <div className={`absolute top-0 w-0 h-0 border-[6px] border-transparent 
                              ${msg.isMe
                                ? 'right-[-6px] border-t-[#d9fdd3] border-l-[#d9fdd3]'
                                : 'left-[-6px] border-t-white border-r-white'
                              }`}
                            />
                          </div>

                          {/* Swap Button (Right for Contact) */}
                          {!msg.isMe && (
                            <button
                              onClick={() => {
                                const newMessages = [...(formData.messages || [])];
                                newMessages[index].isMe = !newMessages[index].isMe;
                                setFormData(prev => ({ ...prev, messages: newMessages }));
                              }}
                              className="opacity-0 group-hover:opacity-100 p-2 text-gray-400 hover:text-green-600 transition-all transform hover:scale-110"
                              title="Ubah jadi pesan Keluar"
                            >
                              <User size={16} />
                            </button>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="flex gap-2 pt-6">
                    <AdminButton
                      onClick={editingId ? () => handleUpdate(editingId) : handleCreate}
                      disabled={!formData.name || !formData.notificationText}
                      variant="primary"
                      className="flex-1 bg-violet-600 hover:bg-violet-700 py-3 rounded-xl shadow-lg shadow-violet-200 text-base"
                    >
                      {editingId ? 'Simpan Perubahan' : 'Simpan Testimoni'}
                    </AdminButton>
                  </div>
                </div>
              </div>
            </div>

          </div>
        </div>
      </div>
      {/* Testimonials Dashboard (Existing List) */}
      <div className="space-y-6 pt-12 border-t border-gray-100">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-xl font-bold text-gray-900">Database Testimonial</h3>
            <p className="text-sm text-gray-500 mt-1">Total {testimonials.length} simulasi aktif</p>
          </div>
          <div className="text-right">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Update Terakhir</p>
            <p className="text-sm font-medium text-gray-600">{lastUpdated ? new Date(lastUpdated).toLocaleTimeString() : '-'}</p>
          </div>
        </div>

        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 opacity-50">
            {[1, 2, 3].map(i => <div key={i} className="h-40 bg-gray-100 rounded-2xl animate-pulse" />)}
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {testimonials.map((t) => (
              <div key={t.id} className="bg-white rounded-2xl border border-gray-100 p-5 shadow-sm hover:shadow-xl transition-all hover:border-violet-200 group relative">
                <div className="flex items-start justify-between gap-2 mb-4">
                  <div className="flex items-center gap-3 min-w-0">
                    <div
                      className="w-10 h-10 rounded-full overflow-hidden border border-gray-100 flex items-center justify-center font-bold shrink-0"
                      style={{
                        backgroundColor: `#${getAvatarColors(t.name).bg}`,
                        color: `#${getAvatarColors(t.name).text}`
                      }}
                    >
                      <img src={getAvatarUrl(t.name)} alt="" className="w-full h-full object-cover" />
                    </div>
                    <div className="min-w-0">
                      <h4 className="font-bold text-gray-900 truncate text-sm">{t.name}</h4>
                      <div className="flex items-center gap-1 text-[10px] text-gray-400">
                        <Clock size={10} /> {t.messages?.length || 0} Chat
                      </div>
                    </div>
                  </div>
                  <div className="shrink-0">
                    <StatusToggle
                      isActive={t.isActive !== false}
                      onClick={() => {
                        fetch('/api/testimonial', {
                          method: 'PUT',
                          headers: { 'Content-Type': 'application/json', 'x-csrf-token': csrfToken },
                          credentials: 'include',
                          body: JSON.stringify({ id: t.id, isActive: t.isActive === false })
                        }).then(res => res.ok && refresh());
                      }}
                    />
                  </div>
                </div>

                <div className="bg-gray-50 p-3 rounded-xl mb-4 text-xs italic text-gray-600 border border-gray-100 line-clamp-2">
                  &quot;{t.notificationText}&quot;
                </div>

                <div className="flex items-center justify-end gap-2 border-t border-gray-50 pt-4">
                  <button onClick={() => handleEdit(t)} className="p-2 text-gray-400 hover:text-violet-600 hover:bg-violet-50 rounded-xl transition-all">
                    <Pencil size={16} />
                  </button>
                  <button onClick={() => handleDelete(t.id)} className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all">
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </AdminLayout>
  );
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Send, MoreVertical, Phone, Video, Search, CheckCheck } from 'lucide-react';
import { m, AnimatePresence } from 'framer-motion';
import { soundManager } from '@/app/about/_components/os/utils/SoundManager';
// The ID used for this browser session to track polling
import { v4 as uuidv4 } from 'uuid';
import useSWR from 'swr';
import SystemNavFrame from '@/components/layout/SystemNavFrame';

// Helper for fetching
const fetcher = (url: string) => fetch(url).then(res => res.json());

interface ChatMessage {
    id: string;
    text: string;
    sender: 'visitor' | 'admin';
    timestamp: number;
}

export default function FullPageChat({ contactInfo }: { contactInfo: any }) {
    console.log('[FullPageChat] Rendered, contactInfo:', !!contactInfo);
    // Session state
    const [visitorId, setVisitorId] = useState<string>('');
    const [input, setInput] = useState('');
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [isSending, setIsSending] = useState(false);

    const bottomRef = useRef<HTMLDivElement>(null);

    // Initialize visitor ID on mount
    useEffect(() => {
        document.body.setAttribute('data-page', 'contact');
        const storedId = localStorage.getItem('ramos_visitor_id');
        if (storedId) {
            setVisitorId(storedId);
        } else {
            const newId = uuidv4();
            localStorage.setItem('ramos_visitor_id', newId);
            setVisitorId(newId);
        }
        return () => document.body.removeAttribute('data-page');
    }, []);

    // Initial greeting if no messages
    useEffect(() => {
        if (visitorId && messages.length === 0) {
            setMessages([{
                id: 'greeting',
                text: contactInfo?.subtext || "👋 Halo! Ada project menarik yang bisa saya bantu? Ketik pesanmu di bawah ini, langsung masuk ke HP saya loh!",
                sender: 'admin',
                timestamp: Date.now()
            }]);
        }
    }, [visitorId, contactInfo?.subtext, messages.length]);

    // Polling using SWR (Runs every 2.5s)
    const { data: syncData } = useSWR(
        visitorId ? `/api/chat/sync?visitorId=${visitorId}` : null,
        fetcher,
        { refreshInterval: 2500, revalidateOnFocus: true }
    );

    // Update messages when polling returns new data
    useEffect(() => {
        if (syncData?.success && syncData?.messages?.length > 0) {
            setMessages(prev => {
                const newMessages = [...prev];
                let hasNewAdminMessage = false;

                syncData.messages.forEach((serverMsg: ChatMessage) => {
                    // Try to find a temporary optimistic message that matches this server message
                    const existingTempIndex = newMessages.findIndex(
                        m => m.id.startsWith('temp-') && m.text === serverMsg.text && m.sender === serverMsg.sender
                    );

                    // Check if we already have the confirmed server message
                    const hasConfirmed = newMessages.find(m => m.id === serverMsg.id);

                    if (!hasConfirmed) {
                        if (existingTempIndex >= 0) {
                            // Replace temp message with server message to prevent visual duplicates during network race
                            newMessages[existingTempIndex] = serverMsg;
                        } else {
                            newMessages.push(serverMsg);
                            if (serverMsg.sender === 'admin') hasNewAdminMessage = true;
                        }
                    }
                });

                if (hasNewAdminMessage) {
                    soundManager.play('notification', 0.6);
                }

                // Absolute deduplication by ID just in case state got tangled
                const uniqueMsgs: ChatMessage[] = [];
                const seenIds = new Set();

                newMessages.sort((a, b) => a.timestamp - b.timestamp).forEach(m => {
                    if (!seenIds.has(m.id)) {
                        seenIds.add(m.id);
                        uniqueMsgs.push(m);
                    }
                });

                return uniqueMsgs;
            });
        }
    }, [syncData]);

    // Auto-scroll to bottom
    useEffect(() => {
        bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages, isSending]);

    const handleSend = async (e?: React.FormEvent) => {
        e?.preventDefault();
        if (!input.trim() || isSending || !visitorId) return;

        const messageText = input.trim();
        setInput('');
        setIsSending(true);

        // Optimistically add to UI
        const tempId = `temp-${Date.now()}`;
        setMessages(prev => [...prev, {
            id: tempId,
            text: messageText,
            sender: 'visitor',
            timestamp: Date.now()
        }]);

        soundManager.play('click', 0.3);

        try {
            const res = await fetch('/api/chat/send', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    visitorId,
                    message: messageText,
                    pageUrl: window.location.href
                })
            });
            const data = await res.json();

            if (data.success && data.message) {
                // Replace temp message with server confirmed one
                setMessages(prev => {
                    const mapped = prev.map(m => m.id === tempId ? data.message : m);
                    // Absolute deduplication by ID
                    const uniqueMsgs: ChatMessage[] = [];
                    const seenIds = new Set();
                    mapped.forEach(m => {
                        if (!seenIds.has(m.id)) {
                            seenIds.add(m.id);
                            uniqueMsgs.push(m);
                        }
                    });
                    return uniqueMsgs;
                });
            }
        } catch (error) {
            console.error('Failed to send message:', error);
            // Could add a visual error state here
        } finally {
            setIsSending(false);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSend();
        }
    };

    return (
        <SystemNavFrame hideFooter={true}>
            <div className="relative flex-1 bg-[#0a0a0a] overflow-hidden flex flex-col items-center justify-center pt-28 pb-32 px-4 h-full min-h-[100dvh]">
                {/* Device Frame Constraint for Desktop */}
                <div
                    className="w-full h-full md:h-[80vh] bg-[#e5ddd5] dark:bg-[#0b141a] md:rounded-[2.5rem] md:border-[12px] border-gray-800 shadow-[0_20px_50px_-12px_rgba(0,0,0,0.8)] flex flex-col overflow-hidden relative z-10"
                    style={{ maxWidth: '480px' }}
                >

                    {/* Chat Header */}
                    <div className="bg-[#00a884] dark:bg-[#202c33] px-4 py-4 flex items-center justify-between shrink-0 shadow-md z-20">
                        <div className="flex items-center gap-3">
                            {/* Avatar */}
                            <div className="w-10 h-10 rounded-full bg-gray-200 overflow-hidden shrink-0 border border-white/20">
                                <img src={`https://ui-avatars.com/api/?background=ffffff&color=000000&name=R&size=128&bold=true&length=1`} alt="Ramos" className="w-full h-full object-cover" />
                            </div>

                            <div className="flex flex-col">
                                <span className="font-semibold text-white text-base leading-tight">Ramos</span>
                                <span className="text-white/80 text-xs font-medium">Online</span>
                            </div>
                        </div>

                        <div className="flex items-center gap-4 text-white">
                            <Video className="w-5 h-5 opacity-80 cursor-not-allowed" />
                            <Phone className="w-5 h-5 opacity-80 cursor-not-allowed" />
                            <MoreVertical className="w-5 h-5 opacity-80 cursor-not-allowed" />
                        </div>
                    </div>

                    {/* Chat Messages Area */}
                    <div className="flex-1 w-full overflow-y-auto px-4 py-6 flex flex-col gap-3 relative"
                        style={{ backgroundImage: `url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')`, backgroundSize: 'cover', backgroundAttachment: 'fixed' }}>

                        <div className="w-full flex justify-center mb-4">
                            <span className="bg-[#d9ddcf] dark:bg-[#1f2c34] text-[#4a4a4a] dark:text-gray-300 text-xs px-3 py-1 rounded-md shadow-sm">
                                Today
                            </span>
                        </div>

                        <AnimatePresence initial={false}>
                            {messages.map((msg, idx) => {
                                const isMe = msg.sender === 'visitor';
                                return (
                                    <m.div
                                        key={msg.id || idx}
                                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                                        animate={{ opacity: 1, y: 0, scale: 1 }}
                                        className={`flex flex-col max-w-[85%] ${isMe ? 'self-end items-end' : 'self-start items-start'} relative group`}
                                    >
                                        <div
                                            className={`px-3 py-2 rounded-2xl shadow-sm text-[15px] leading-relaxed relative ${isMe
                                                ? 'bg-[#d9fdd3] dark:bg-[#005c4b] text-[#111b21] dark:text-[#e9edef] rounded-tr-none'
                                                : 'bg-white dark:bg-[#202c33] text-[#111b21] dark:text-[#e9edef] rounded-tl-none'
                                                }`}
                                            style={{ wordBreak: 'break-word' }}
                                        >
                                            {/* Chat Tail SVG (Simplified) */}
                                            <svg viewBox="0 0 8 13" width="8" height="13" className={`absolute top-0 ${isMe ? '-right-[8px] text-[#d9fdd3] dark:text-[#005c4b]' : '-left-[8px] text-white dark:text-[#202c33] transform scale-x-[-1]'} fill-current`}>
                                                <path d="M5.188 1H0v11.191L8 1.733V1h-2.812z"></path>
                                            </svg>

                                            <div className="whitespace-pre-wrap">{msg.text}</div>

                                            <div className={`flex items-center justify-end gap-1 mt-1 -mb-1 ${isMe ? 'text-[#667781] dark:text-white/60' : 'text-[#667781] dark:text-white/50'}`}>
                                                <span className="text-[10px] uppercase">
                                                    {new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                </span>
                                                {isMe && <CheckCheck className="w-3.5 h-3.5 text-blue-500" />}
                                            </div>
                                        </div>
                                    </m.div>
                                );
                            })}
                        </AnimatePresence>

                        <div ref={bottomRef} className="h-2 w-full" />
                    </div>

                    <div className="bg-[#f0f2f5] dark:bg-[#202c33] px-3 py-3 md:px-4 md:py-4 flex items-end gap-2 shrink-0 z-20 no-ring">
                        <div
                            className="flex-1 bg-white dark:bg-[#2a3942] rounded-2xl md:rounded-3xl min-h-[44px] flex items-center px-4 overflow-hidden border border-transparent dark:border-white/5 shadow-sm no-ring focus-within:ring-0 focus-within:ring-offset-0"
                            style={{ boxShadow: 'none', outline: 'none' }}
                        >
                            <textarea
                                value={input}
                                onChange={(e) => setInput(e.target.value)}
                                onKeyDown={handleKeyDown}
                                placeholder="Tulis pesan..."
                                className="flex-1 max-h-[120px] py-3 bg-transparent border-none outline-none resize-none text-[15px] text-[#111b21] dark:text-[#d1d7db] placeholder:text-[#8696a0] scrollbar-hide no-ring"
                                rows={1}
                                style={{ minHeight: '44px', boxShadow: 'none', outline: 'none' }}
                            />
                        </div>

                        <button
                            onClick={handleSend}
                            disabled={!input.trim() || isSending}
                            className={`w-11 h-11 md:w-12 md:h-12 rounded-full flex items-center justify-center shrink-0 transition-all ${input.trim() && !isSending
                                ? 'bg-[#00a884] shadow-md hover:bg-[#008f6f] text-white'
                                : 'bg-[#e9edef] dark:bg-[#2a3942] text-[#8696a0] dark:text-[#8696a0] pointer-events-none'
                                }`}
                        >
                            <Send className="w-5 h-5 -translate-x-[2px] translate-y-[1px]" />
                        </button>
                    </div>
                </div>

                {/* Background Decor (blurred) */}
                <div className="absolute inset-0 z-0 pointer-events-none opacity-40 dark:opacity-20 flex justify-center items-center">
                    <div className="w-[80vw] h-[80vw] max-w-[800px] max-h-[800px] bg-[#00a884] rounded-full blur-[120px] mix-blend-screen opacity-50" />
                </div>
            </div>
        </SystemNavFrame>
    );
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Upload, X, ZoomIn, ZoomOut, Move } from 'lucide-react';
import { motion } from 'framer-motion';

interface ProfileMediaEditorProps {
    initialUrl?: string;
    initialType?: 'image' | 'video';
    initialScale?: number;
    initialX?: number;
    initialY?: number;
    onSave: (data: { url: string; type: 'image' | 'video'; scale: number; x: number; y: number }) => void;
}

export default function ProfileMediaEditor({
    initialUrl,
    initialType = 'image',
    initialScale = 1,
    initialX = 0,
    initialY = 0,
    onSave
}: ProfileMediaEditorProps) {
    const [url, setUrl] = useState(initialUrl || '');
    const [type, setType] = useState<'image' | 'video'>(initialType);
    const [scale, setScale] = useState(initialScale);
    const [position, setPosition] = useState({ x: initialX, y: initialY });
    const [uploading, setUploading] = useState(false);
    const [isEditing, setIsEditing] = useState(false);

    const containerRef = useRef<HTMLDivElement>(null);

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploading(true);
        try {
            const formData = new FormData();
            formData.append('file', file);

            // Upload to your existing GitHub upload API
            // Using a specific folder for profile pictures
            const response = await fetch('/api/upload/github?folder=assets/profile', {
                method: 'POST',
                body: formData,
            });

            if (response.ok) {
                const data = await response.json();
                setUrl(data.url);
                setType(file.type.startsWith('video/') ? 'video' : 'image');
                setIsEditing(true);
                // Reset transform for new image
                setScale(1);
                setPosition({ x: 0, y: 0 });
            } else {
                alert('Upload failed');
            }
        } catch (err) {
            console.error('Upload Error:', err);
            alert('Upload error');
        } finally {
            setUploading(false);
        }
    };

    const handleSave = () => {
        onSave({
            url,
            type,
            scale,
            x: position.x,
            y: position.y
        });
        setIsEditing(false);
    };

    return (
        <div className="space-y-4">
            <div className="flex items-center gap-4">
                {/* Preview Circle */}
                <div className="relative w-24 h-24 rounded-full border-2 border-dashed border-gray-300 overflow-hidden bg-gray-50 flex items-center justify-center group">
                    {url ? (
                        <div className="w-full h-full relative cursor-pointer" onClick={() => setIsEditing(true)}>
                            {type === 'video' ? (
                                <video
                                    src={url}
                                    className="w-full h-full object-cover"
                                    style={{ transform: `scale(${scale}) translate(${position.x}%, ${position.y}%)` }}
                                    muted
                                    loop
                                    autoPlay
                                />
                            ) : (
                                <img
                                    src={url}
                                    alt="Profile"
                                    className="w-full h-full object-cover"
                                    style={{ transform: `scale(${scale}) translate(${position.x}%, ${position.y}%)` }}
                                />
                            )}
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                <span className="text-white text-[10px] font-medium">Edit Angle</span>
                            </div>
                        </div>
                    ) : (
                        <Upload className="text-gray-400" size={24} />
                    )}
                </div>

                <div className="flex-1">
                    <label className="block text-sm font-medium text-gray-700 mb-1">Profile Photo/Video</label>
                    <div className="flex gap-2">
                        <label className="cursor-pointer bg-white border border-gray-300 px-3 py-1.5 rounded-md text-xs font-medium hover:bg-gray-50 flex items-center gap-2">
                            <Upload size={14} />
                            {uploading ? 'Uploading...' : 'Upload New'}
                            <input type="file" className="hidden" accept="image/*,video/*" onChange={handleFileUpload} disabled={uploading} />
                        </label>
                        {url && (
                            <button
                                type="button"
                                onClick={(e) => {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    setIsEditing(true);
                                }}
                                className="bg-blue-50 text-blue-600 px-3 py-1.5 rounded-md text-xs font-medium hover:bg-blue-100 border border-blue-100"
                            >
                                Adjust Angle
                            </button>
                        )}
                    </div>
                    <p className="text-[10px] text-gray-500 mt-1">Recommended: 1:1 ratio. Max 5MB for video.</p>
                </div>
            </div>

            {/* Editor Modal */}
            {isEditing && (
                <div className="fixed inset-0 z-[999999] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm" onClick={(e) => e.stopPropagation()}>
                    <div className="bg-white rounded-2xl shadow-2xl max-w-xl w-full overflow-hidden flex flex-col max-h-[90vh]" onClick={(e) => e.stopPropagation()}>
                        <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
                            <h3 className="font-semibold text-gray-900">Adjust Profile Media</h3>
                            <button
                                type="button"
                                onClick={(e) => {
                                    e.preventDefault();
                                    setIsEditing(false);
                                }}
                                className="text-gray-400 hover:text-gray-600"
                            >
                                <X size={20} />
                            </button>
                        </div>

                        <div className="flex-1 p-8 bg-gray-900 flex flex-col items-center justify-center overflow-hidden">
                            {/* The "WhatsApp Style" Cropper */}
                            <div
                                ref={containerRef}
                                className="relative w-72 h-72 rounded-full overflow-hidden border-2 border-white/30 shadow-[0_0_100px_rgba(0,0,0,0.5)] bg-slate-800"
                            >
                                <motion.div
                                    drag
                                    dragMomentum={false}
                                    onPointerDown={(e) => e.stopPropagation()}
                                    onDrag={(e, info) => {
                                        // 288 is the pixel width of w-72 (18rem)
                                        const containerSize = 288;
                                        setPosition(prev => ({
                                            x: prev.x + (info.delta.x / (scale * containerSize / 100)),
                                            y: prev.y + (info.delta.y / (scale * containerSize / 100))
                                        }));
                                    }}
                                    className="w-full h-full flex items-center justify-center cursor-move"
                                >
                                    {type === 'video' ? (
                                        <video
                                            src={url}
                                            className="min-w-full min-h-full pointer-events-none"
                                            style={{
                                                transform: `scale(${scale}) translate(${position.x}%, ${position.y}%)`,
                                                objectFit: 'cover'
                                            }}
                                            muted
                                            autoPlay
                                            loop
                                        />
                                    ) : (
                                        <img
                                            src={url}
                                            alt="Editor"
                                            className="min-w-full min-h-full pointer-events-none"
                                            style={{
                                                transform: `scale(${scale}) translate(${position.x}%, ${position.y}%)`,
                                                objectFit: 'cover'
                                            }}
                                        />
                                    )}
                                </motion.div>

                                {/* Center Target UI */}
                                <div className="absolute inset-0 border-[60px] border-black/40 pointer-events-none rounded-full" />
                                <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 border-t border-white/20 pointer-events-none" />
                                <div className="absolute inset-y-0 left-1/2 -translate-x-1/2 border-l border-white/20 pointer-events-none" />
                            </div>

                            <p className="text-white/40 text-[10px] mt-6 flex items-center gap-1">
                                <Move size={10} /> Drag to reposition
                            </p>
                        </div>

                        <div className="px-6 py-4 bg-gray-50 flex flex-col gap-4">
                            <div className="flex items-center gap-4">
                                <ZoomOut size={16} className="text-gray-400" />
                                <input
                                    type="range"
                                    min="1"
                                    max="5"
                                    step="0.1"
                                    value={scale}
                                    onChange={(e) => setScale(parseFloat(e.target.value))}
                                    className="flex-1 h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                                />
                                <ZoomIn size={16} className="text-gray-400" />
                            </div>

                            <div className="flex justify-end gap-3 mt-2">
                                <button
                                    type="button"
                                    onClick={(e) => {
                                        e.preventDefault();
                                        setIsEditing(false);
                                    }}
                                    className="px-4 py-2 text-sm font-medium text-gray-600 hover:text-gray-800"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="button"
                                    onClick={(e) => {
                                        e.preventDefault();
                                        e.stopPropagation();
                                        handleSave();
                                    }}
                                    className="px-6 py-2 bg-blue-600 text-white rounded-xl text-sm font-medium hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all active:scale-95"
                                >
                                    Save Profile Image
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

