import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import Slider from 'rc-slider';
import 'rc-slider/assets/index.css';
import Cropper from 'react-easy-crop';
import { Play, Pause, ZoomIn, Maximize2 } from 'lucide-react';

interface VideoTrimmerProps {
    file: File;
    onConfirm: (start: number, end: number, crop: any) => void;
    onCancel: () => void;
}

export default function VideoTrimmer({ file, onConfirm, onCancel }: VideoTrimmerProps) {
    const videoRef = useRef<HTMLVideoElement | null>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Playback State
    const [duration, setDuration] = useState(0);
    const [range, setRange] = useState<[number, number]>([0, 10]);
    const [isPlaying, setIsPlaying] = useState(false);

    // Crop State
    const [crop, setCrop] = useState({ x: 0, y: 0 });
    const [zoom, setZoom] = useState(1);
    const [aspect, setAspect] = useState<number | undefined>(undefined);
    const [naturalAspect, setNaturalAspect] = useState<number | undefined>(undefined);
    const [croppedAreaPixels, setCroppedAreaPixels] = useState<any>(null);

    // Internal Video Source
    const [videoSrc, setVideoSrc] = useState<string>('');

    // Blob URL Lifecycle
    useEffect(() => {
        if (!file) return;
        const url = URL.createObjectURL(file);
        setVideoSrc(url);

        return () => {
            URL.revokeObjectURL(url);
        };
    }, [file]);

    // Safety check for video element ref
    useEffect(() => {
        if (containerRef.current) {
            const videoEl = containerRef.current.querySelector('video');
            if (videoEl) {
                videoRef.current = videoEl;
                if (!Number.isNaN(videoEl.duration)) {
                    const dur = videoEl.duration;
                    requestAnimationFrame(() => {
                        setDuration(dur);
                        if (range[1] === 10 && dur > 0) setRange([0, dur]);
                    });
                }
            }
        }
    }, [range]); // Run when range changes to check if we need to expand it to full duration

    const onMediaLoaded = (mediaSize: { width: number, height: number, naturalWidth: number, naturalHeight: number }) => {
        // Ensure ref is captured
        if (!videoRef.current && containerRef.current) {
            videoRef.current = containerRef.current.querySelector('video');
        }

        // Initialize duration
        if (videoRef.current) {
            const vidDur = videoRef.current.duration;
            if (!Number.isNaN(vidDur)) {
                setDuration(vidDur);
                if (range[1] === 10) setRange([0, vidDur]);
            }
        }

        // Initialize Aspect Ratio
        if (mediaSize.naturalWidth && mediaSize.naturalHeight) {
            const natAspect = mediaSize.naturalWidth / mediaSize.naturalHeight;
            setNaturalAspect(natAspect);

            // Set initial aspect to Natural (Original) if not set
            if (aspect === undefined) {
                setAspect(natAspect);
            }
        }
    };

    const handleTimeUpdate = () => {
        if (videoRef.current) {
            const currentTime = videoRef.current.currentTime;
            if (currentTime >= range[1]) {
                videoRef.current.currentTime = range[0];
                if (isPlaying) {
                    videoRef.current.play();
                }
            }
        }
    };

    const togglePlay = () => {
        if (videoRef.current) {
            if (isPlaying) {
                videoRef.current.pause();
                setIsPlaying(false);
            } else {
                if (videoRef.current.currentTime < range[0] || videoRef.current.currentTime >= range[1]) {
                    videoRef.current.currentTime = range[0];
                }
                videoRef.current.play().catch(e => console.error("Play failed", e));
                setIsPlaying(true);
            }
        }
    };

    const handleSliderChange = (value: number | number[]) => {
        if (Array.isArray(value)) {
            const [start, end] = value;
            setRange([start, end]);
            if (videoRef.current) {
                const tolerance = 0.1;
                if (!isPlaying) {
                    if (Math.abs(range[0] - start) > tolerance) {
                        videoRef.current.currentTime = start;
                    } else if (Math.abs(range[1] - end) > tolerance) {
                        videoRef.current.currentTime = end;
                    }
                }
            }
        }
    };

    const onCropCompleteEvent = useCallback((croppedArea: any, croppedAreaPixels: any) => {
        setCroppedAreaPixels(croppedAreaPixels);
    }, []);

    const formatTime = (seconds: number) => {
        const m = Math.floor(seconds / 60);
        const s = Math.floor(seconds % 60);
        return `${m}:${s < 10 ? '0' : ''}${s}`;
    };

    // Aspect Ratio Options
    // We define this inside render to access 'naturalAspect'
    const aspectOptions = [
        { label: 'Free', value: undefined },
        { label: 'Original', value: naturalAspect },
        { label: '16:9', value: 16 / 9 },
        { label: '9:16', value: 9 / 16 },
        { label: '4:5', value: 4 / 5 },
        { label: '1:1', value: 1 / 1 },
    ];

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-90 p-4 animate-in fade-in duration-200">
            <div className="bg-white w-full max-w-5xl h-[90vh] rounded-lg overflow-hidden flex flex-col shadow-2xl">
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b shrink-0">
                    <div>
                        <h3 className="text-lg font-bold text-gray-800">Edit Video</h3>
                        <p className="text-xs text-gray-500">Trim duration and Crop area</p>
                    </div>

                    <button onClick={onCancel} className="text-gray-500 hover:text-gray-700">✕</button>
                </div>

                {/* Main Area: Cropper */}
                <div ref={containerRef} className="relative flex-1 bg-black overflow-hidden group">
                    <Cropper
                        video={videoSrc}
                        crop={crop}
                        zoom={zoom}
                        aspect={aspect}
                        onCropChange={setCrop}
                        onCropComplete={onCropCompleteEvent}
                        onZoomChange={setZoom}
                        onMediaLoaded={onMediaLoaded}
                        mediaProps={{
                            playsInline: true,
                            crossOrigin: 'anonymous',
                            onTimeUpdate: handleTimeUpdate,
                            onEnded: () => setIsPlaying(false),
                            onClick: togglePlay,
                        } as any}
                    />

                    {/* Controls Overlay (Top Right) */}
                    <div className="absolute top-4 right-4 flex flex-col gap-2 bg-white/90 p-2 rounded shadow-lg backdrop-blur text-xs z-10">
                        <span className="font-bold text-gray-500 uppercase flex items-center gap-1">
                            <Maximize2 size={12} /> Ratio
                        </span>
                        <div className="flex flex-col gap-1">
                            {aspectOptions.map((opt) => (
                                <button
                                    key={opt.label}
                                    onClick={() => setAspect(opt.value)}
                                    className={`px-2 py-1 rounded border transition-colors ${
                                        // Complex check for 'Free' vs 'Original' when naturalAspect might match others
                                        (aspect === opt.value && (opt.value !== undefined || aspect === undefined))
                                            ? 'bg-violet-600 text-white border-violet-600'
                                            : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
                                        }`}
                                >
                                    {opt.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Centered Play Control */}
                    {!isPlaying && (
                        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                            <div className="w-16 h-16 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center">
                                <Play className="w-8 h-8 text-white ml-1" fill="currentColor" />
                            </div>
                        </div>
                    )}
                </div>

                {/* Bottom Panel */}
                <div className="p-4 bg-gray-50 border-t space-y-4 shrink-0">

                    <div className="flex items-end gap-4">
                        {/* Play Button */}
                        <button
                            onClick={togglePlay}
                            className="w-12 h-12 flex items-center justify-center rounded-full bg-violet-100 text-violet-600 hover:bg-violet-200 transition-colors shrink-0"
                            title={isPlaying ? "Pause" : "Play"}
                        >
                            {isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" className="ml-1" />}
                        </button>

                        {/* Slider & Info */}
                        <div className="flex-1 space-y-2">
                            <div className="flex justify-between items-center text-xs font-bold text-gray-500 uppercase tracking-wider">
                                <span>Timeline</span>
                                <span>{formatTime(range[0])} - {formatTime(range[1])} / {formatTime(duration)}</span>
                            </div>
                            <div className="px-1">
                                <Slider
                                    range
                                    min={0}
                                    max={duration || 10}
                                    step={0.1}
                                    value={range}
                                    onChange={handleSliderChange as any}
                                    trackStyle={[{ backgroundColor: '#7c3aed', height: 6 }]}
                                    handleStyle={[
                                        { borderColor: '#7c3aed', backgroundColor: '#fff', opacity: 1, height: 18, width: 18, marginTop: -6, cursor: 'ew-resize' },
                                        { borderColor: '#7c3aed', backgroundColor: '#fff', opacity: 1, height: 18, width: 18, marginTop: -6, cursor: 'ew-resize' }
                                    ]}
                                    railStyle={{ backgroundColor: '#d1d5db', height: 6 }}
                                />
                            </div>
                        </div>
                    </div>

                    {/* Footer Actions */}
                    <div className="flex justify-between items-center pt-2 border-t border-gray-200 mt-2">
                        <div className="flex items-center gap-2">
                            <ZoomIn size={16} className="text-gray-400" />
                            <input
                                type="range"
                                min={1} max={3} step={0.1}
                                value={zoom}
                                onChange={(e) => setZoom(Number(e.target.value))}
                                className="w-32 h-1.5 bg-gray-300 rounded-lg appearance-none cursor-pointer"
                                title="Zoom"
                            />
                        </div>

                        <div className="flex gap-3">
                            <button
                                onClick={onCancel}
                                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={() => onConfirm(range[0], range[1], croppedAreaPixels)}
                                className="px-6 py-2 text-sm font-medium text-white bg-violet-600 rounded-md hover:bg-violet-700 shadow-sm"
                            >
                                Process Video
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Save, Plus, Trash2, Loader2, Sparkles } from 'lucide-react';
import { useAdminAuth } from '@/hooks/useAdminAuth';

interface PhilosophyStep {
    number: string;
    title: string;
    desc: string;
    quote: string;
}

interface DesignPhilosophyData {
    heading: string;
    subheading: string;
    steps: PhilosophyStep[];
}

export default function DesignPhilosophyForm() {
    const [formData, setFormData] = useState<DesignPhilosophyData | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const { csrfToken } = useAdminAuth();
    const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

    // Fetch initial data
    useEffect(() => {
        const fetchData = async () => {
            try {
                const res = await fetch('/api/about/philosophy');
                if (res.ok) {
                    const data = await res.json();
                    setFormData(data);
                }
            } catch (error) {
                console.error('Failed to fetch philosophy data:', error);
                setMessage({ type: 'error', text: 'Gagal mengambil data' });
            } finally {
                setIsLoading(false);
            }
        };
        fetchData();
    }, []);

    const handleChange = (field: keyof DesignPhilosophyData, value: string) => {
        if (!formData) return;
        setFormData({ ...formData, [field]: value });
    };

    const handleStepChange = (index: number, field: keyof PhilosophyStep, value: string) => {
        if (!formData) return;
        const newSteps = [...formData.steps];
        newSteps[index] = { ...newSteps[index], [field]: value };
        setFormData({ ...formData, steps: newSteps });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData) return;

        setIsSaving(true);
        setMessage(null);

        try {
            const res = await fetch('/api/about/philosophy', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-csrf-token': csrfToken
                },
                credentials: 'include',
                body: JSON.stringify(formData)
            });

            if (res.ok) {
                setMessage({ type: 'success', text: 'Perubahan berhasil disimpan! ✨' });
                // Clean up message after 3 seconds
                setTimeout(() => setMessage(null), 3000);
            } else {
                throw new Error('Failed to save');
            }
        } catch (error) {
            setMessage({ type: 'error', text: 'Gagal menyimpan perubahan.' });
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center py-12">
                <Loader2 className="w-8 h-8 animate-spin text-gray-400" />
            </div>
        );
    }

    if (!formData) return null;

    return (
        <form onSubmit={handleSubmit} className="space-y-8 bg-white dark:bg-zinc-900 p-6 rounded-2xl border border-gray-100 dark:border-zinc-800 shadow-sm">
            <div className="flex items-center justify-between border-b border-gray-100 dark:border-zinc-800 pb-6">
                <div>
                    <h2 className="text-xl font-bold flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-blue-500" />
                        Design Philosophy
                    </h2>
