'use client';

import React, { useState, useEffect } from 'react';
import Masonry from 'react-masonry-css';

interface MasonryGridProps {
    children: React.ReactNode;
    className?: string;
    columns?: 'default' | 'sidebar' | 'bottom';
    width?: number;
}

const defaultBreakpoints = {
    default: 7,    // Desktop (> 1280px)
    1280: 7,       // Desktop
    1024: 5,       // Tablet L
    768: 4,        // Match md:grid-cols-4
    640: 3,        // Match sm:grid-cols-3
    0: 2           // Base
};
const sidebarBreakpoints = {
    default: 3,    // Max 3 columns for sidebar
    1280: 3,       // Desktop
    1024: 2,       // Tablet L
    768: 2,        // Tablet
    640: 2         // Mobile
};

const bottomBreakpoints = {
    default: 6,    // 6 columns to match 3+3 layout
    1536: 6,       // Desktop L
    1280: 4,       // Desktop
    1024: 3,       // Tablet L
    768: 2,        // Tablet
    640: 2         // Mobile L
};

export default function MasonryGrid({ children, className = '', columns = 'default', width }: MasonryGridProps) {
    const breakpointColumns = columns === 'sidebar' ? sidebarBreakpoints : columns === 'bottom' ? bottomBreakpoints : defaultBreakpoints;
    const [mounted, setMounted] = useState(false);

    // Container-aware responsive logic
    const containerRef = React.useRef<HTMLDivElement>(null);

    // Determine initial default based on the columns prop type
    // Use window width if available to prevent desktop showing as mobile initially
    const getInitialCols = () => {
        if (typeof window === 'undefined') return 2; // SSR fallback
        const w = window.innerWidth;
        if (w >= 1280) return breakpointColumns.default || 7;
        if (w >= 1024) return (breakpointColumns as any)[1024] || 4;
        if (w >= 768) return (breakpointColumns as any)[768] || 3;
        return 2; // Mobile
    };

    const [columnCount, setColumnCount] = useState(() => {
        if (typeof window === 'undefined') return 2;
        return getInitialCols();
    });

    const getCols = (w: number) => {
        if (!breakpointColumns) return 2; // Safety fallback
        let cols = breakpointColumns.default || 2;

        // Sort breakpoints descending (numeric keys)
        const breakpoints = Object.keys(breakpointColumns)
            .filter(k => k !== 'default')
            .map(Number)
            .sort((a, b) => b - a);

        for (let bp of breakpoints) {
            if (w <= bp) {
                cols = (breakpointColumns as any)[bp];
            }
        }
        return cols;
    };

    useEffect(() => {
        setMounted(true);

        const updateCallback = (w: number) => {
            setColumnCount(getCols(w));
        };

        // 1. Explicit Width Mode (Prop-based) - Preferred for OS Windows
        if (width !== undefined) {
            updateCallback(width);
            return;
        }

        // 2. Observer Mode (DOM-based) - Fallback for standard pages
        if (!containerRef.current) return;

        const handleResize = (entries: ResizeObserverEntry[]) => {
            for (let entry of entries) {
                if (entry.contentRect.width > 0) {
                    updateCallback(entry.contentRect.width);
                }
            }
        };

        const observer = new ResizeObserver(handleResize);
        observer.observe(containerRef.current);

        // Immediate check
        if (containerRef.current.offsetWidth > 0) {
            updateCallback(containerRef.current.offsetWidth);
        } else if (typeof window !== 'undefined') {
            // Fallback to window width if container has no width yet
            updateCallback(window.innerWidth);
        }

        return () => {
            observer.disconnect();
        };
    }, [breakpointColumns, width]); // Added width as dependency

    // Helper to determine grid classes based on props
    const getGridClasses = () => {
        if (columns === 'sidebar') return 'grid-cols-2 lg:grid-cols-3';
        if (columns === 'bottom') return 'grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-6';

        // Match defaultBreakpoints EXACTLY
        return 'grid-cols-2 xs:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-7';
    };

    const renderNativeGrid = () => (
        <div
            className={`w-full grid items-start content-start ${className} ${getGridClasses()} gap-2 md:gap-4`}
        >
            {React.Children.map(children, (child) => (
                <div className="mb-2 md:mb-4 break-inside-avoid">
                    {child}
                </div>
            ))}
        </div>
    );

    // SSR / Hydration Stability
    // We render the wrapper div immediately and only populate the Masonry 
    // library once client-side hooks are ready. This prevents the "native -> masonry" jump.
    if (!mounted) {
        return <div ref={containerRef} className="w-full" style={{ visibility: 'hidden', minHeight: '50vh' }} />;
    }

    // Optimization removed: User requested true masonry layout. 
    // Native Grid causes gaps with varying heights.
    // We will use react-masonry-css for all sizes.

    /* 
    if (columnCount <= 2) {
        return renderNativeGrid();
    } 
    */

    // Use manual column count ONLY if explicit width is provided (OS Window mode)
    // Otherwise, let Masonry library handle responsiveness using the breakpoint object (Main Page mode)
    // This fixes the issue where ResizeObserver might report incorrect width on mobile initial load.
    const masonryCols = width !== undefined ? columnCount : breakpointColumns;

    return (
        <div ref={containerRef} className="w-full" style={{ width: '100%' }}>
            <Masonry
                breakpointCols={masonryCols}
                className={`masonry-grid -ml-2 md:-ml-4 w-auto flex ${className}`}
                columnClassName="masonry-grid-column pl-2 md:pl-4 bg-clip-padding"
            >
                {children}
            </Masonry>
        </div>
    );
}

"use client"

import { useEffect, useRef, useState, useCallback } from 'react'
import type { GalleryItem } from '@/types/projects'
import Media from '@/components/shared/Media'
import { useNavbarVisibility } from '@/contexts/NavbarVisibilityContext'

// Error boundary component for gallery items
function GalleryItemErrorBoundary({ children, fallback }: { children: React.ReactNode; fallback: React.ReactNode }) {
  const [hasError, setHasError] = useState(false)

  useEffect(() => {
    const handleError = () => setHasError(true)
    window.addEventListener('error', handleError)
    return () => window.removeEventListener('error', handleError)
  }, [])

  if (hasError) {
    return <>{fallback}</>
  }

  return <>{children}</>
}

type Item = string | GalleryItem

type GalleryProps = {
  items?: Item[]
  autoplay?: boolean
  muted?: boolean
  loop?: boolean
  playsInline?: boolean
}

export default function Gallery({
  items = [],
  autoplay = true,
  muted = true,
  loop = true,
  playsInline = true
}: GalleryProps) {
  const list: GalleryItem[] = items.map((it) => (
    typeof it === 'string' ? { kind: 'image', src: it } : it
  ))
  const [open, setOpen] = useState<{ i: number } | null>(null)
  const [isClient, setIsClient] = useState(false)
  const viewerRef = useRef<HTMLDivElement | null>(null)
  const hasMany = list.length > 1
  const { hideNavbar, showNavbar } = useNavbarVisibility()

  const goPrev = useCallback(() => {
    setOpen((o) => !o ? o : ({ i: (o.i - 1 + list.length) % list.length }))
  }, [list.length])

  const goNext = useCallback(() => {
    setOpen((o) => !o ? o : ({ i: (o.i + 1) % list.length }))
  }, [list.length])

  const enterFullscreen = useCallback(() => {
    const el = viewerRef.current
    if (!el) return
    try {
      if (el.requestFullscreen) {
        el.requestFullscreen()
      } else if ((el as any).webkitRequestFullscreen) {
        ; (el as any).webkitRequestFullscreen()
      } else if ((el as any).msRequestFullscreen) {
        ; (el as any).msRequestFullscreen()
      }
    } catch (e) {
      // Failed to enter fullscreen
    }
  }, [])

  useEffect(() => {
    setIsClient(true)
  }, [])

  useEffect(() => {
    if (!open || !isClient) return

    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        showNavbar()
        setOpen(null)
      }
      else if (e.key === 'ArrowLeft') goPrev()
      else if (e.key === 'ArrowRight') goNext()
      else if (e.key.toLowerCase() === 'f') enterFullscreen()
    }

    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [open, goPrev, goNext, enterFullscreen, isClient, showNavbar])

  // Show nothing until client is ready
  if (!isClient) {
    return null
  }

  return (
    <>
      <div className="grid md:grid-cols-2 gap-4 mt-8">
        {list.map((item, i) => {
          const ratio = (item.width && item.height) ? `${item.width} / ${item.height}` : '16 / 10'
          return (
            <button
              key={i}
              className="overflow-hidden rounded-lg block w-full text-left focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
              onClick={() => {
                hideNavbar()
                setOpen({ i })
              }}
              title="Klik untuk perbesar"
              aria-label={`Open gallery item ${i + 1} in fullscreen`}
              type="button"
            >
              <div style={{ aspectRatio: ratio }}>
                <GalleryItemErrorBoundary
                  fallback={
                    <div className="w-full h-full bg-gray-200 flex items-center justify-center">
                      <div className="text-center text-gray-500">
                        <svg className="w-8 h-8 mx-auto mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
                        </svg>
                        <p className="text-xs">Failed to load</p>
                      </div>
                    </div>
                  }
                >
                  <Media
                    kind={item.kind}
                    src={item.src}
                    poster={item.poster}
                    alt={`Gallery item ${i + 1} - ${item.kind === 'video' ? 'Video content' : 'Image content'}`}
                    sizes="(max-width: 768px) 100vw, 50vw"
                    autoplay={autoplay}
                    muted={muted}
                    loop={loop}
                    playsInline={playsInline}
                    className="w-full h-full object-cover"
                  />
                </GalleryItemErrorBoundary>
              </div>
            </button>
          )
        })}
      </div>

      {open && list[open.i] && (
        <div
          role="dialog"
          aria-modal="true"
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/75"
          onClick={() => {
            showNavbar()
            setOpen(null)
          }}
        >
          <div
            ref={viewerRef}
            className="relative max-w-5xl w-full mx-4"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="absolute -top-12 left-0 right-0 flex items-center justify-between px-1">
              <button
                className="text-white/80 hover:text-white text-sm underline focus:outline-none focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-black rounded"
                onClick={() => {
                  showNavbar()
                  setOpen(null)
                }}
                aria-label="Close gallery"
                type="button"
              >
                Tutup (Esc)
              </button>
              <div className="flex items-center gap-3">
                {hasMany && (
                  <>
                    <button
                      className="text-white/80 hover:text-white text-sm underline focus:outline-none focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-black rounded"
                      onClick={goPrev}
                      aria-label="Previous image"
                      type="button"
                    >
                      ← Prev
                    </button>
                    <button
                      className="text-white/80 hover:text-white text-sm underline focus:outline-none focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-black rounded"
                      onClick={goNext}
                      aria-label="Next image"
                      type="button"
                    >
                      Next →
                    </button>
                  </>
                )}
                <button
                  className="text-white/80 hover:text-white text-sm underline focus:outline-none focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-black rounded"
                  onClick={enterFullscreen}
                  aria-label="Enter fullscreen mode"
                  type="button"
                >
                  Fullscreen (F)
                </button>
              </div>
            </div>
            <div
              className="w-full"
              style={{
                aspectRatio: (list[open.i].width && list[open.i].height)
                  ? `${list[open.i].width} / ${list[open.i].height}`
                  : '16 / 9'
              }}
            >
              <Media
                kind={list[open.i].kind}
                src={list[open.i].src}
                poster={list[open.i].poster}
                alt={`Fullscreen gallery item ${open.i + 1} - ${list[open.i].kind === 'video' ? 'Video content' : 'Image content'}`}
                autoplay={list[open.i].kind === 'video'}
                muted={true}
                loop={false}
                playsInline={true}
                controls={true}
                className="w-full h-full object-contain bg-black"
              />
            </div>
            {hasMany && (
              <>
                <button
                  aria-label="Previous"
                  className="absolute inset-y-0 left-0 w-1/5 md:w-1/4 hover:bg-white/5 transition"
                  onClick={goPrev}
                />
                <button
                  aria-label="Next"
                  className="absolute inset-y-0 right-0 w-1/5 md:w-1/4 hover:bg-white/5 transition"
                  onClick={goNext}
                />
              </>
            )}
          </div>
        </div>
      )}
    </>
  )
}

'use client';

import Link from 'next/link';
import { Project } from '@/types/projects';
import Media from '@/components/shared/Media';
import { resolveCover } from '@/lib/images';
import { Heart, Share2 } from 'lucide-react';

interface ProjectCardPinterestProps {
    project: Project;
    priority?: boolean;
    videoEnabled?: boolean;
    interactive?: boolean;
    highlightedTag?: string;
}

export default function ProjectCardPinterest({
    project,
    priority = false,
    videoEnabled = true,
    interactive = true,
    highlightedTag,
    onClick
}: ProjectCardPinterestProps & { onClick?: () => void }) {
    const { slug, title, tags, likes, shares } = project;
    const cover = resolveCover(project);
    const shouldAutoplay = videoEnabled && (project.autoplay ?? true);

    // Calculate aspect ratio for the image/video container
    const width = project.coverWidth || 800;
    const height = (project.coverHeight && project.coverHeight > 0) ? project.coverHeight : 600;
    const ratio = (width > 0 && height > 0) ? (width / height) : (4 / 3);

    // SMART TAG DISPLAY LOGIC:
    // This logic ensures that if the user is filtering by a specific tag (e.g., "Design"),
    // that specific tag is the one displayed on the card, rather than just the first tag
    // in the list. This provides better feedback to the user on why the card matches.
    // - If highlightedTag matches one of the project's tags -> Show it.
    // - Else -> Show the first tag (default).
    const displayTag = highlightedTag && tags?.some(t => t.toLowerCase() === highlightedTag.toLowerCase())
        ? tags.find(t => t.toLowerCase() === highlightedTag.toLowerCase())
        : tags?.[0];

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const Component: any = onClick ? 'div' : (interactive ? Link : 'div');
    const hrefProps = (!onClick && interactive) ? { href: `/projects/${slug}` } : {};
    const isInteractive = interactive || !!onClick;

    return (
        <Component {...hrefProps} onClick={onClick} className={`block mb-2 md:mb-6 relative z-0 ${isInteractive ? 'group hover:z-10 cursor-pointer' : ''}`}>
            {/* ... (keep media container) ... */}
            <div
                className={`relative overflow-hidden rounded-md bg-neutral-200 dark:bg-neutral-900 transition-transform duration-300 ${isInteractive ? 'hover:scale-[1.02]' : ''}`}
                style={{
                    aspectRatio: ratio,
                }}
            >
                <div className="absolute inset-0">
                    <Media
                        kind={cover.kind}
                        src={cover.src}
                        poster={cover.poster}
                        alt={title}
                        // Optimized: Request 256px for thumbnails (closer to actual display size ~170-200px)
                        width={256}
                        height={Math.round(256 / ratio)}
                        priority={priority}
                        lazy={!priority}
                        quality={75}
                        autoplay={shouldAutoplay}
                        muted={project.muted ?? true}
                        loop={project.loop ?? true}
                        playsInline={project.playsInline ?? true}
                        className="w-full h-full object-cover"
                        sizes="(max-width: 640px) 45vw, (max-width: 1024px) 30vw, 20vw"
                    />
                </div>
            </div>

            {/* Project Info */}
            <div className="mt-3 px-1 space-y-1">
                <div className="flex items-baseline justify-between gap-4">
                    <p className="font-medium text-sm text-gray-900 dark:text-gray-100 leading-tight group-hover:underline decoration-1 underline-offset-2 truncate">
                        {title}
                    </p>
                    {displayTag && (
                        <p className="text-[10px] uppercase tracking-wider font-bold text-gray-500 whitespace-nowrap shrink-0">{displayTag}</p>
                    )}
                </div>

                {/* Metrics bar */}
                <div className="flex items-center gap-3 text-gray-500">
                    <div className="flex items-center gap-1">
                        <Heart className="w-3 h-3 fill-current text-rose-500" />
                        <span className="text-[10px] font-medium">{likes || 0}</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <Share2 className="w-3 h-3 text-sky-500" />
                        <span className="text-[10px] font-medium">{shares || 0}</span>
                    </div>
                </div>
            </div>
        </Component>
    );
}

