'use client';

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

interface LoveButtonProps {
  projectId: string;
  initialLikes?: number;
  initialLoved?: boolean;
  className?: string;
}

export default function LoveButton({ 
  projectId, 
  initialLikes = 0, 
  initialLoved = false,
  className = '' 
}: LoveButtonProps) {
  const [isLoved, setIsLoved] = useState(initialLoved);
  const [likes, setLikes] = useState(initialLikes);
  const [isAnimating, setIsAnimating] = useState(false);

  // Load saved state from localStorage
  useEffect(() => {
    const savedState = localStorage.getItem(`love-${projectId}`);
    if (savedState) {
      const { isLoved: savedLoved, likes: savedLikes } = JSON.parse(savedState);
      setIsLoved(savedLoved);
      setLikes(savedLikes);
    }
  }, [projectId]);

  const handleLove = async () => {
    if (isAnimating) return;

    setIsAnimating(true);
    
    const newLoved = !isLoved;
    const newLikes = newLoved ? likes + 1 : Math.max(0, likes - 1);
    
    // Optimistic update
    setIsLoved(newLoved);
    setLikes(newLikes);
    
    // Save to localStorage
    localStorage.setItem(`love-${projectId}`, JSON.stringify({
      isLoved: newLoved,
      likes: newLikes
    }));

    // Here you could also send to your API
    try {
      // await fetch(`/api/projects/${projectId}/like`, {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ loved: newLoved })
      // });
    } catch (error) {
      console.error('Failed to update like:', error);
      // Revert on error
      setIsLoved(!newLoved);
      setLikes(likes);
    }

    setTimeout(() => setIsAnimating(false), 300);
  };

  return (
    <motion.button
      onClick={handleLove}
      disabled={isAnimating}
      className={`
        flex items-center space-x-2 px-4 py-2 rounded-full border transition-all duration-200
        focus:outline-none focus:ring-2 focus:ring-offset-2
        ${isLoved 
          ? 'bg-red-50 border-red-200 text-red-600 hover:bg-red-100 focus:ring-red-500' 
          : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50 focus:ring-gray-500'
        }
        ${isAnimating ? 'cursor-not-allowed' : 'cursor-pointer'}
        ${className}
      `}
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.95 }}
      aria-label={isLoved ? 'Unlike this project' : 'Like this project'}
    >
      <motion.div
        animate={isLoved ? { scale: [1, 1.3, 1] } : {}}
        transition={{ duration: 0.3 }}
        className="relative"
      >
        <svg 
          className={`w-5 h-5 transition-colors duration-200 ${
            isLoved ? 'text-red-500' : 'text-gray-400'
          }`}
          fill={isLoved ? 'currentColor' : 'none'}
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path 
            strokeLinecap="round" 
            strokeLinejoin="round" 
            strokeWidth={2} 
            d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" 
          />
        </svg>
        
        {/* Floating hearts animation */}
        {isLoved && isAnimating && (
          <motion.div
            className="absolute inset-0 flex items-center justify-center"
            initial={{ opacity: 0, scale: 0 }}
            animate={{ 
              opacity: [0, 1, 0], 
              scale: [0, 1, 1.5],
              y: [0, -20, -40]
            }}
            transition={{ duration: 0.6 }}
          >
            <svg className="w-3 h-3 text-red-400" fill="currentColor" viewBox="0 0 24 24">
              <path d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
            </svg>
          </motion.div>
        )}
      </motion.div>
      
      <span className="text-sm font-medium">
        {likes > 0 ? likes : 'Like'}
      </span>
    </motion.button>
  );
}

"use client"
import { useEffect, useState } from 'react'

type Props = {
  message: string
  type?: 'success' | 'error' | 'info' | 'warning' | 'saving' | 'saved'
  duration?: number
  onClose?: () => void
}

export default function Toast({ message, type = 'info', duration = 3000, onClose }: Props){
  const [show, setShow] = useState(true)
  const [isAnimating, setIsAnimating] = useState(false)
  
  useEffect(()=>{
    setIsAnimating(true)
    const t = setTimeout(()=>{ 
      setShow(false)
      setTimeout(() => {
        onClose && onClose()
      }, 300) // Wait for animation to complete
    }, duration)
    return ()=> clearTimeout(t)
  }, [duration, onClose])

  const getToastStyles = () => {
    switch (type) {
      case 'success':
      case 'saved':
        return {
          bg: 'bg-emerald-600 text-white',
          icon: (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
            </svg>
          ),
          animation: 'animate-bounce'
        }
      case 'error':
        return {
          bg: 'bg-red-600 text-white',
          icon: (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          ),
          animation: 'animate-pulse'
        }
      case 'warning':
        return {
          bg: 'bg-yellow-600 text-white',
          icon: (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
            </svg>
          ),
          animation: 'animate-pulse'
        }
      case 'saving':
        return {
          bg: 'bg-blue-600 text-white',
          icon: (
            <svg className="w-5 h-5 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
            </svg>
          ),
          animation: 'animate-pulse'
        }
      default:
        return {
          bg: 'bg-gray-900 text-white',
          icon: (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          ),
          animation: ''
        }
    }
  }

  const styles = getToastStyles()
  const ariaRole = (type === 'error' || type === 'warning') ? 'alert' : 'status'
  const ariaLive = (type === 'error' || type === 'warning') ? 'assertive' : 'polite'

  return (
    <div 
      role={ariaRole}
      aria-live={ariaLive}
      className={`fixed bottom-4 right-4 z-50 transition-all duration-300 ease-in-out ${
      show ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-2 scale-95'
    }`}
    >
      <div className={`px-4 py-3 rounded-lg shadow-xl ${styles.bg} max-w-sm text-sm flex items-center gap-3 ${
        isAnimating ? styles.animation : ''
      }`}>
        <div className="flex-shrink-0">
          {styles.icon}
        </div>
        <div className="flex-1">
          {message}
        </div>
        <button
          onClick={() => {
            setShow(false)
            setTimeout(() => onClose && onClose(), 300)
          }}
          aria-label="Close notification"
          className="flex-shrink-0 ml-2 hover:bg-black hover:bg-opacity-20 rounded-full p-1 transition-colors"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>
    </div>
  )
}

"use client";
import React, { useState, useEffect, useRef, useCallback } from "react";
import { SparklesCore } from "@/components/ui/sparkles";
import { AnimatePresence, motion, useMotionValue, useSpring, useTransform, useMotionTemplate } from "framer-motion";
import { cn } from "@/lib/utils";
import { IconDotsVertical } from "@tabler/icons-react";

interface CompareProps {
  firstImage?: string;
  secondImage?: string;
  className?: string;
  firstImageClassName?: string;
  secondImageClassname?: string;
  initialSliderPercentage?: number;
  slideMode?: "hover" | "drag";
  showHandlebar?: boolean;
  autoplay?: boolean;
  autoplayDuration?: number;
  firstSlideLabel?: string;
  secondSlideLabel?: string;
}

export const Compare = ({
  firstImage = "",
  secondImage = "",
  className,
  firstImageClassName,
  secondImageClassname,
  initialSliderPercentage = 50,
  slideMode = "hover",
  showHandlebar = true,
  autoplay = false,
  autoplayDuration = 5000,
  firstSlideLabel = "Original",
  secondSlideLabel = "Retouched",
}: CompareProps) => {
  const sliderRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isMouseOver, setIsMouseOver] = useState(false);

  // Motion values for smooth interaction
  const x = useMotionValue(0);
  const width = useMotionValue(0); // Cache width to avoid layout thrashing

  // Spring physics for natural movement (damping: smoothens the stop, stiffness: responsiveness)
  const springX = useSpring(x, {
    stiffness: 400,
    damping: 30,
    mass: 1
  });

  const percentage = useTransform(() => {
    const w = width.get();
    if (w === 0) return initialSliderPercentage;
    const currentX = springX.get();
    return (currentX / w) * 100;
  });

  const clipPathLeft = useMotionTemplate`inset(0 ${useTransform(percentage, (p) => 100 - p)}% 0 0)`;
  const leftPosition = useMotionTemplate`${percentage}%`;

  // Autoplay Effect
  const autoplayRef = useRef<NodeJS.Timeout | null>(null);

  const startAutoplay = useCallback(() => {
    if (!autoplay) return;

    const startTime = Date.now();
    const animate = () => {
      const w = width.get();
      if (w === 0) return;

      const elapsedTime = Date.now() - startTime;
      const progress = (elapsedTime % (autoplayDuration * 2)) / autoplayDuration;
      const currentPercent = progress <= 1 ? progress * 100 : (2 - progress) * 100;

      const nextX = (currentPercent / 100) * w;

      x.set(nextX);
      autoplayRef.current = setTimeout(animate, 16);
    };

    animate();
  }, [autoplay, autoplayDuration, x, width]);

  const stopAutoplay = useCallback(() => {
    if (autoplayRef.current) {
      clearTimeout(autoplayRef.current);
      autoplayRef.current = null;
    }
  }, []);

  // Update width on resize
  useEffect(() => {
    if (!sliderRef.current) return;

    const element = sliderRef.current;

    // Initial measure
    const rect = element.getBoundingClientRect();
    width.set(rect.width);
    x.set((initialSliderPercentage / 100) * rect.width);

    // Observer
    const resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        if (entry.contentBoxSize) {
          // Use measure for consistent box model
          const newWidth = entry.contentRect.width;
          width.set(newWidth);
          // Optional: Keep relative percentage? For now, keep absolute X for stability or re-calc.
          // let's just update width, X stays (so percentage drops/gains). 
          // It's acceptable for edge case.
        }
      }
    });

    resizeObserver.observe(element);
    return () => resizeObserver.disconnect();
  }, [initialSliderPercentage, x, width]);

  useEffect(() => {
    startAutoplay();
    return () => stopAutoplay();
  }, [startAutoplay, stopAutoplay]);

  const mouseEnterHandler = () => {
    setIsMouseOver(true);
    stopAutoplay();
  };

  const mouseLeaveHandler = () => {
    setIsMouseOver(false);
    // Removed auto-reset to center. Slider stays where user left it.
    if (slideMode === "drag") {
      setIsDragging(false);
    }
    startAutoplay();
  };

  const handleStart = useCallback(() => {
    if (slideMode === "drag") {
      setIsDragging(true);
    }
  }, [slideMode]);

  const handleEnd = useCallback(() => {
    if (slideMode === "drag") {
      setIsDragging(false);
    }
  }, [slideMode]);

  const handleMove = useCallback(
    (clientX: number) => {
      if (!sliderRef.current) return;
      if (slideMode === "hover" || (slideMode === "drag" && isDragging)) {
        const rect = sliderRef.current.getBoundingClientRect();
        const newX = clientX - rect.left;
        const w = width.get();
        // Clamp value
        x.set(Math.max(0, Math.min(w, newX)));
      }
    },
    [slideMode, isDragging, x, width]
  );

  const renderMedia = (src: string, className: string, alt: string) => {
    const isVideo = src.toLowerCase().endsWith('.mp4') || src.toLowerCase().endsWith('.webm');

    if (isVideo) {
      return (
        <video
          src={src}
          className={cn(className, "object-cover")}
          autoPlay
          loop
          muted
          playsInline
          draggable={false}
        />
      );
    }

    return (
      <img
        alt={alt}
        src={src}
        className={className}
        draggable={false}
      />
    );
  };

  return (
    <div
      ref={sliderRef}
      className={cn("w-[400px] h-[400px] overflow-hidden relative", className)}
      style={{
        position: "relative",
        cursor: slideMode === "drag" ? "grab" : "col-resize",
      }}
      onMouseMove={(e) => handleMove(e.clientX)}
      onMouseLeave={mouseLeaveHandler}
      onMouseEnter={mouseEnterHandler}
      onMouseDown={(e) => {
        handleStart();
        handleMove(e.clientX);
      }}
      onMouseUp={handleEnd}
      onTouchStart={(e) => {
        handleStart();
        handleMove(e.touches[0].clientX);
      }}
      onTouchEnd={handleEnd}
      onTouchMove={(e) => handleMove(e.touches[0].clientX)}
    >
      {/* Slider Handle Line */}
      <AnimatePresence initial={false}>
        <motion.div
          className="h-full w-px absolute top-0 m-auto z-30 bg-gradient-to-b from-transparent from-[5%] to-[95%] via-indigo-500 to-transparent"
          style={{
            left: leftPosition, // USE SPRING for handle
          }}
        >
          {/* Sparkles Decoration */}
          <div className="w-36 h-full [mask-image:radial-gradient(100px_at_left,white,transparent)] absolute top-1/2 -translate-y-1/2 left-0 bg-gradient-to-r from-indigo-400 via-transparent to-transparent z-20 opacity-50" />
          <div className="w-10 h-1/2 [mask-image:radial-gradient(50px_at_left,white,transparent)] absolute top-1/2 -translate-y-1/2 left-0 bg-gradient-to-r from-cyan-400 via-transparent to-transparent z-10 opacity-100" />
          <div className="w-10 h-3/4 top-1/2 -translate-y-1/2 absolute -right-10 [mask-image:radial-gradient(100px_at_left,white,transparent)]">
            <MemoizedSparklesCore
              background="transparent"
              minSize={0.4}
              maxSize={1}
              particleDensity={1200}
              className="w-full h-full"
              particleColor="#FFFFFF"
            />
          </div>
          {showHandlebar && (
            <div className="h-5 w-5 rounded-md top-1/2 -translate-y-1/2 bg-white z-30 -right-2.5 absolute flex items-center justify-center shadow-[0px_-1px_0px_0px_#FFFFFF40]">
              <IconDotsVertical className="h-4 w-4 text-black" />
            </div>
          )}
        </motion.div>
      </AnimatePresence>

      {/* First Image (Overlay) - Clipped */}
      <div className="overflow-hidden w-full h-full relative z-20 pointer-events-none">
        <AnimatePresence initial={false}>
          {firstImage ? (
            <motion.div
              className={cn(
                "absolute inset-0 z-20 rounded-2xl shrink-0 w-full h-full select-none overflow-hidden",
                firstImageClassName
              )}
              style={{
                clipPath: clipPathLeft, // USE SPRING
              }}
            >
              {renderMedia(
                firstImage,
                cn(
                  "absolute inset-0 z-20 rounded-2xl shrink-0 w-full h-full select-none",
                  firstImageClassName
                ),
                "first image"
              )}
              {/* Label for First Image (Visible when this layer is visible) */}
              {firstSlideLabel && (
                <div className="absolute top-4 left-4 bg-black/50 text-white text-xs px-2 py-1 rounded backdrop-blur-sm z-30">
                  {firstSlideLabel}
                </div>
              )}
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>

      {/* Second Image (Base) */}
      <AnimatePresence initial={false}>
        {secondImage ? (
          <div className="absolute inset-0 w-full h-full z-[19]"> {/* Wrap in div to hold label relative to it */}
            {renderMedia(
              secondImage,
              cn(
                "absolute top-0 left-0 z-[19] rounded-2xl w-full h-full select-none",
                secondImageClassname
              ),
              "second image"
            )}
            {/* Label for Second Image (Visible when overlay is clipped away) */}
            {secondSlideLabel && (
              <div className="absolute top-4 right-4 bg-black/50 text-white text-xs px-2 py-1 rounded backdrop-blur-sm z-[20]">
                {secondSlideLabel}
              </div>
            )}
          </div>
        ) : null}
      </AnimatePresence>
    </div>
  );
};

const MemoizedSparklesCore = React.memo(SparklesCore);

